window.__D("text/zohar-hebrew-translation/c004",{"p":[[9522011204,"<p>וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם הוֹצִיא לֶחֶם וָיָיִן. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (תהלים עו) וַיְהִי בְשָׁלֵם סוּכּוֹ וְגוֹ'. בֹּא רְאֵה, כְּשֶׁעָלָה בִּרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָם, הוֹצִיא שַׁלְהֶבֶת אַחַת שֶׁל הַמָּאוֹר שֶׁל הַנִּיצוֹץ הַקָּשֶׁה, וְנָשַׁף רוּחַ בְּרוּחַ חֲשׁוּכָה וְשׂוֹרֶפֶת. וְהוֹצִיא מִתּוֹךְ צִדְדֵי הַתְּהוֹם טִפָּה אַחַת, וְחִבֵּר אוֹתָם יַחַד, וּבָרָא בָהֶם אֶת הָעוֹלָם.</p>\n<p>אוֹתָהּ הַשַּׁלְהֶבֶת עָלְתָה וְהִתְעַטְּרָה בִּשְׂמֹאל, וְאוֹתָהּ הַטִּפָּה עָלְתָה וְהִתְעַטְּרָה בְּיָמִין. עָלוּ אֶחָד עִם אֶחָד, הֶחֱלִיפוּ מְקוֹמוֹת, זֶה לְצַד זֶה וְזֶה לְצַד זֶה. זֶה שֶׁיָּרַד עָלָה, וְזֶה שֶׁעָלָה יָרַד. נִ</p>\n<p>קְשְׁרוּ זֶה עִם זֶה וְיָצְאָה מִבֵּינֵיהֶם רוּחַ שְׁלֵמָה, וְאָז אוֹתָם שְׁנֵי הַצְּדָדִים נַעֲשׂוּ אֶחָד, וְנִתְּנָה בֵינֵיהֶם (הרוח) וְהִתְעַטְּרוּ הָאֶחָד עִם הָאֶחָד. וְאָז נִמְצָא שָׁלוֹם לְמַעְלָה וְשָׁלוֹם לְמַטָּה, וְהַדַּרְגָּה הִתְקַיְּמָה.</p>\n<p>הִתְעַטְרָה הֵ\"א עִם וָא\"ו, וָא\"ו עִם הֵ\"א, וְאָז עָלְתָה הֵ\"א וְנִקְשְׁרָה בְּקֶשֶׁר שָׁלֵם. וְאָז וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם. מֶלֶךְ שָׁלֵם הוּא וַדַּאי מֶלֶךְ שֶׁשּׁוֹלֵט בִּשְׁלֵמוּת. מָתַי הוּא מֶלֶךְ שָׁלֵם? בְּיוֹם הַכִּפּוּרִים, כְּשֶׁכָּל הַפָּנִים מְאִירוֹת. (דבר אחר מלכי צדק מלך שלם, אמר רבי שמעון, רצה הקדוש ברוך הוא להוציא כהנה משם, כמו שנאמר ברוך אברם לאל עליון, כיון שהקדים ברכת אברהם לברכת רבונו, אמר לו אברהם', וכי מקדימים ברכת העבד לברכת רבו? מיד נתנה הכהנה לאברהם, שכתוב (תהלים קי) נאם ה' לאדני שב לימיני, וכתוב אחריו, נשבע ה' ולא ינחם אתה כהן לעולם על דברתי מלכי צדק, שכתוב והוא כהן לאל עליון, ואין זרעו כהן).</p>\n<p>דָּבָר אַחֵר וּמַלְכִּי צֶדֶק - זֶה הָעוֹלָם הָאַחֲרוֹן. מֶלֶךְ שָׁלֵם - זֶה הָעוֹלָם הָעֶלְיוֹן. שֶׁהִתְעַטֵּר אֶחָד עִם אֶחָד בְּלִי פֵרוּד שְׁנֵי עוֹלָמוֹת יַחַד, וַאֲפִלּוּ הָעוֹלָם הַתַּחְתּוֹן הוּא הַכֹּל, וְהוּא דָבָר אֶחָד. הוֹצִיא לֶחֶם וָיָיִן - שֶׁבּוֹ שְׁנֵי אֵלּוּ. וְהוּא כֹהֵן לְאֵל עֶלְיוֹן - מְשַׁמֵּשׁ עוֹלָם נֶגֶד עוֹלָם. וְהוּא כֹהֵן - זֶה הַיָּמִין. לְאֵל עֶלְיוֹן - הָעוֹלָם הָעֶלְיוֹן, וּמִשּׁוּם כָּךְ צָרִיךְ הַכֹּהֵן לְבָרֵךְ אֶת הָעוֹלָם.</p>\n<p>בֹּא רְאֵה, הַבְּרָכוֹת נוֹטֵל הָעוֹלָם הַתַּחְתּוֹן הַזֶּה, כְּשֶׁמִּתְחַבֵּר עִם הַכֹּהֵן הַגָּדוֹל, וְאָז וַיְבָרֲכֵהוּ וַיֹּאמַר בָּרוּךְ אַבְרָם לְאֵל עֶלְיוֹן. כָּךְ זֶה וַדַּאי. כְּמוֹ כֵן צָרִיךְ הַכֹּהֵן לְמַטָּה לִקְשֹׁר קְשָׁרִים וּלְבָרֵךְ אֶת הַמָּקוֹם הַזֶּה, כְּדֵי שֶׁיִּתְקַשֵּׁר הַיָּמִין לִקְשֹׁר שְׁנֵי עוֹלָמוֹת יַחַד. בָּרוּךְ אַבְרָם - סוֹד הַדָּבָר הוּא תִקּוּן הַבְּרָכוֹת.</p>\n<p>בָּרוּךָ אַבְרָם - כְּמוֹ שֶׁאָמַרְנוּ, בָּרוּךְ אַתָּה. לְאֵל עֶלְיוֹן - ה' אֱלֹהֵינוּ. קֹנֵה שָׁמַיִם וָאָרֶץ - מֶלֶךְ הָעוֹלָם. וְהַפָּסוּק הַזֶּה הוּא סוֹד הַבְּרָכוֹת. (ומשום כך) וַיְבָרֲכֵהוּ - מִמַּטָּה לְמַעְלָה. וּבָרוּךְ אֵל עֶלְיוֹן (אשר מגן צריך בידך), וּבָרוּךְ אֵל עֶלְיוֹן - מִמַּעְלָה לְמַטָּה. וַיִּתֶּן לוֹ מַעֲשֵׂר מִכֹּל - לְהִתְדַּבֵּק בַּמָּקוֹם שֶׁהַקֶּשֶׁר נִקְשָׁר לְמַטָּה.</p>\n<p>בְּעוֹדָם הוֹלְכִים פָּגַשׁ בָּהֶם רַבִּי יֵיסָא וִיהוּדִי אֶחָד עִמּוֹ. וְהָיָה אוֹתוֹ הַיְּהוּדִי אוֹמֵר, (שם כה) לְדָוִד אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא. לְדָוִד, וְכִי לָמָּה לֹא כָתוּב מִזְמוֹר לְדָוִד אוֹ לְדָוִד מִזְמוֹר?</p>\n<p>אֶלָּא בִּשְׁבִיל דַּרְגָּתוֹ אָמַר דָּוִד אֶת הַתִּשְׁבַּחַת שֶׁאָמַר בִּשְׁבִילוֹ. אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא, אֵלֶיךְ ה' לְמַעְלָה. נַפְשִׁי, מִי זוֹ נַפְשִׁי? (אשא) זֶה דָוִד, (הוא) הַדַּרְגָּה הָרִאשׁוֹנָה שֶׁאָמַרְנוּ. אֶשָּׂא - אַעֲלֶה, כְּמוֹ שֶׁנֶּאֱמַר (שם קכא) אֶשָּׂא עֵינַי אֶל הֶהָרִים. מִשּׁוּם שֶׁדָּוִד הָיָה מִשְׁתַּדֵּל כָּל יָמָיו לְהַעֲלוֹת אֶת דַּרְגָּתוֹ לְהִתְעַטֵּר לְמַעְלָה וּלְהִתְקַשֵּׁר שָׁם בְּקֶשֶׁר שָׁלֵם כָּרָאוּי.</p>\n<p>כְּמוֹ כֵן (שם קג) לְדָוִד בָּרְכִי נַפְשִׁי אֶת ה'. מִשּׁוּם דַּרְגָּתוֹ אָמַר. וּמָה אָמַר בָּרְכִי נַפְשִׁי אֶת ה'? אֶת - לְהִתְקַשֵּׁר בְּקֶשֶׁר לְמַעְלָה. וְכָל קְרָבַי, מִי הֵם קְרָבַי? אֵלּוּ שְׁאָר חַיּוֹת הַשָּׂדֶה שֶׁנִּקְרָאוֹת קְרָבַיִם, כְּמוֹ שֶׁנֶּאֱמַר (שיר ה) וּמֵעַי הָמוּ עָלָיו. דָּבָר אַחֵר בָּרְכִי נַפְשִׁי - בִּשְׁבִילוֹ הוּא אָמַר. אֶת ה' - זוֹ שְׁלֵמוּת הַכֹּל. אֶת ה' - הַכְּלָל שֶׁל הַכֹּל.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר לְרַבִּי יֵיסָא, רָאִיתִי אוֹתְךְ שֶׁבָּאתָ עִם הַשְּׁכִינָה וְהִתְחַבַּרְתָּ. אָמַר לוֹ, כָּךְ זֶה וַדַּאי. וְשָׁלֹשׁ פַּרְסָאוֹת שֶׁהָלַכְתִּי עִמָּהּ וְאָמְרָה לִי כַּמָּה דְבָרִים מְעֻלִּים, וַאֲנִי שָׁמַרְתִּי אוֹתָם לַיּוֹם הַזֶּה, וְלֹא יָדַעְתִּי שֶׁהוּא הַמָּאוֹר שֶׁמֵּאִיר כְּמוֹ שֶׁרָאִיתִי כָּעֵת.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר לַיְּהוּדִי הַהוּא, מַה שְּׁמֶךְ? אָמַר לוֹ, יוֹעֵזֶר. אָמַר לוֹ, יוֹעֵזֶר וְאֶלְעָזָר (דבר אחד) יוֹשְׁבִים יַחַד. יָשְׁבוּ עַל סֶלַע אֶחָד בַּשָּׂדֶה הַהוּא. פָּתַח אוֹתוֹ הַיְּהוּדִי וְאָמַר, (ישעיה מג) אָנֹכִי אָנֹכִי הוּא מֹחֶה פְשָׁעֶיךְ לְמַעֲנִי וְחַטֹּאתֶיךְ לֹא אֶזְכֹּר. מָה הַטַּעַם פַּעֲמַיִם אָנֹכִי אָנֹכִי?.</p>\n<p>אֶלָּא אֶחָד בְּסִינַי, וְאֶחָד בְּשָׁעָה שֶׁבָּרָא אֶת הָעוֹלָם, שֶׁכָּתוּב (שמות כ) אָנֹכִי ה' אֱלֹהֶיךְ. זֶה הוּא בְּסִינַי. וְאֶחָד כְּשֶׁבָּרָא אֶת הָעוֹלָם, שֶׁכָּתוּב (ישעיה מה) אָנֹכִי עָשִׂיתִי אֶרֶץ וְאָדָם עָלֶיהָ בָרָאתִי. הוּא כְּדֵי לְהַרְאוֹת שֶׁאֵין פֵּרוּד בֵּין מַעְלָה וּמַטָּה.</p>\n<p>מֹחֶה פְשָׁעֶיךְ, לֹא כָתוּב מַעֲבִיר פְּשָׁעֶיךְ אֶלָּא מוֹחֶה, כְּדֵי שֶׁלֹּא יִתְרָאוּ לְעוֹלָמִים. לְמַעֲנִי, מַה זֶּה לְמַעֲנִי? מִשּׁוּם אוֹתָם הָרַחֲמִים שֶׁתְּלוּיִים בִּי, שֶׁכָּתוּב (דברים ד) כִּי אֵל רַחוּם ה' אֱלֹהֶיךְ וְגוֹ'.</p>\n<p>דָּבָר אַחֵר מֹחֶה פְשָׁעֶיךְ לְמַעֲנִי - בֹּא רְאֵה, הָרְשָׁעִים שֶׁל הָעוֹלָם עוֹשִׂים פְּגָם לְמַעְלָה, שֶׁכַּאֲשֶׁר אוֹתָם חֲטָאִים עוֹלִים, רַחֲמִים וְאוֹר עֶלְיוֹן וִינִיקַת הַבְּרָכוֹת לֹא יוֹרְדוֹת לְמַטָּה, וְהַדַּרְגָּה הַזּוֹ אֵינָהּ נוֹטֶלֶת בְּרָכוֹת שֶׁלְּמַעְלָה לְהָנִיק לְמַטָּה. וּמִשּׁוּם כָּךְ לְמַעֲנִי, כְּדֵי שֶׁלֹּא יִמָּנְעוּ בְרָכוֹת לְהָנִיק (לו) לַכֹּל.</p>\n<p>כְּמוֹ כֵן, (שם לב) רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא. לְהַרְאוֹת שֶׁאֵין פֵּרוּד בֵּין מַעְלָה וּמַטָּה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, כְּמוֹ זֶה כְּשֶׁנִּמְצָאִים צַדִּיקִים בָּעוֹלָם, מִתְעוֹרְרוֹת בְּרָכוֹת לְכָל הָעוֹלָמוֹת. כֵּיוָן שֶׁבָּא אַבְרָהָם, הִתְעוֹרְרוּ בְרָכוֹת לָעוֹלָם, שֶׁכָּתוּב וַאֲבָרֶכְךְ וֶהְיֵה בְּרָכָה. מַה זֶּה וֶהְיֵה בְּרָכָה? רֶמֶז שֶׁיִּמָּצְאוּ בִגְלָלוֹ בְּרָכוֹת לְמַעְלָה וּמַטָּה, שֶׁכָּתוּב וְנִבְרְכוּ בְךְ וְגוֹ', וְכָתוּב וַאֲבָרְכָה מְבָרֲכֶיךְ.</p>\n<p>בָּא יִצְחָק וְהוֹדִיעַ לַכֹּל שֶׁיֵּשׁ דִּין וְיֵשׁ דַּיָּן לְמַעְלָה לְהִפָּרַע מִן הָרְשָׁעִים, וְהוּא עוֹרֵר אֶת הַדִּין בָּעוֹלָם כְּדֵי שֶׁיִּירְאוּ מֵהַקָּדוֹשׁ בָּרוּךְ הוּא כָּל בְּנֵי הָעוֹלָם. בָּא יַעֲקֹב וְעוֹרֵר רַחֲמִים בָּעוֹלָם, וְהִשְׁלִים אֶת הָאֱמוּנָה בָּעוֹלָם כָּרָאוּי.</p>\n<p>בִּימֵי אַבְרָהָם מַה כָּתוּב? וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם. שֶׁהִתְעַטֵּר הַכִּסֵּא בִּמְקוֹמוֹ, וְאָז נִמְצָא מֶלֶךְ שָׁלֵם לְלֹא פְגָם כְּלָל. הוֹצִיא לֶחֶם וָיָיִן - שֶׁהוֹצִיא מְזוֹנוֹת וּבְרָכוֹת לָעוֹלָמוֹת כֻּלָּם כָּרָאוּי. הוֹצִיא לֶחֶם וָיָיִן - שֶׁלֹּא יִמָּנְעוּ הַבְּרָכוֹת מִכָּל הָעוֹלָמוֹת. הוֹצִיא - כְּמוֹ שֶׁנֶּאֱמַר תּוֹצֵא הָאָרֶץ, מֵהַדְּרָגוֹת שֶׁלְּמַעְלָה מוֹצִיא מְזוֹנוֹת וּבְרָכוֹת לְכָל הָעוֹלָמוֹת.</p>\n<p>וְהוּא כֹהֵן לְאֵל עֶלְיוֹן - שֶׁהַכֹּל נִמְצָא בִּשְׁלֵמוּת עֶלְיוֹנָה כָּרָאוּי. לְהַרְאוֹת, כְּמוֹ שֶׁהָרְשָׁעִים עוֹשִׂים פְּגָם בָּעוֹלָם וּמוֹנְעִים בְּרָכוֹת, כָּךְ גַּם בִּשְׁבִיל הַצַּדִּיקִים בָּאוֹת בְּרָכוֹת לָעוֹלָם, וּבִגְלָלָם מִתְבָּרְכִים כָּל בְּנֵי הָעוֹלָם.</p>\n<p>וַיִּתֶּן לוֹ מַעֲשֵׂר מִכֹּל, מַה זֶּה מַעֲשֵׂר מִכֹּל? מֵאוֹתָם הַבְּרָכוֹת שֶׁיּוֹצְאוֹת מִכֹּל, מִשּׁוּם שֶׁהוּא הַמָּקוֹם שֶׁכָּל הַבְּרָכוֹת שֶׁיּוֹרְדוֹת לָעוֹלָם יוֹצְאוֹת מִשָּׁם. דָּבָר אַחֵר וַיִּתֶּן לוֹ מַעֲשֵׂר מִכֹּל - הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ מַעֲשֵׂר, וּמַה הוּא? זוֹ הַדַּרְגָּה שֶׁכָּל פִּתְחֵי הָאֱמוּנָה וְהַבְּרָכוֹת שֶׁל הָעוֹלָם עוֹמְדוֹת בָּהּ, וְהִיא מַעֲשֵׂר, וְהִיא אַחַת מֵעֲשָׂרָה, וְהִיא עֲשָׂרָה מִמֵּאָה. מִכָּאן וָהָלְאָה נִכְנַס אַבְרָהָם בַּקִּיּוּם שֶׁלְּמַעְלָה כָּרָאוּי.</p>\n<p>אָמַר לוֹ רַבִּי אֶלְעָזָר, יָפֶה אָמַרְתָּ. אָמַר לוֹ רַבִּי אֶלְעָזָר, מַה מַּעֲשֶׂיךְ? אָמַר לוֹ, מְלַמֵּד תִּינוֹקוֹת בִּמְקוֹמִי. כָּעֵת בָּא רַבִּי יוֹסֵי מִכְּפָר חָנִין לָעִיר, וְסִלְּקוּ אוֹתָם מֵאֶצְלִי, וְהוֹשִׁיבוּ אוֹתָם אֶצְלוֹ. וְהָיוּ נוֹתְנִים לִי כָּל בְּנֵי הָעִיר שָׂכָר כְּמוֹ אוֹתוֹ הַזְּמַן שֶׁהַתִּינוֹקוֹת הָיוּ אֶצְלִי, וְהִסְתַּכַּלְתִּי בְעַצְמִי שֶׁלֹּא רָאוּי לִי לֵהָנוֹת מֵהֶם בְּחִנָּם, וְהִשְׂכַּרְתִּי עַצְמִי עִם הֶחָכָם (ההוא) הַזֶּה. אָמַר רַבִּי אֶלְעָזָר, כָּאן צָרִיךְ אֶת הַבְּרָכוֹת שֶׁל אַבָּא.</p>\n<p>קָמוּ, הָלְכוּ לִפְנֵי רַבִּי שִׁמְעוֹן (אחר כך), וְהָיָה יוֹשֵׁב וְלוֹמֵד כָּל יוֹם לִפְנֵי רַבִּי שִׁמְעוֹן. וְיוֹם אֶחָד הָיָה עָסוּק בִּנְטִילַת יָדַיִם לְפָנָיו. אָמַר, כָּל מִי שֶׁלֹּא נוֹטֵל יָדָיו כָּרָאוּי, אַף עַל גַּב שֶׁנֶּעֱנָשׁ לְמַעְלָה - נֶעֱנָשׁ לְמַטָּה. וּמָה עָנְשׁוֹ לְמַטָּה? שֶׁגּוֹרֵם לְעַצְמוֹ עֹנִי. כְּמוֹ שֶׁעָנְשׁוֹ כָּךְ - כָּךְ זוֹכֶה מִי שֶׁנּוֹטֵל יָדָיו כָּרָאוּי, שֶׁגּוֹרֵם לְעַצְמוֹ בְּרָכוֹת שֶׁלְּמַעְלָה, שֶׁשּׁוֹרוֹת הַבְּרָכוֹת עַל יָדוֹ כָּרָאוּי וּמִתְבָּרֵךְ בְּעֹשֶׁר.</p>\n<p>אַחַר כָּךְ הִקְדִּים רַבִּי שִׁמְעוֹן, וְרָאָה אוֹתוֹ שֶׁנּוֹטֵל יָדָיו בְּמַיִם, וְנוֹטֵל יָדָיו בְּשִׁעוּר רַב שֶׁל מַיִם. אָמַר רַבִּי שִׁמְעוֹן, מַלֵּא יָדָיו מִבִּרְכוֹתֶיךְ. וְכָךְ הָיָה. מֵאוֹתוֹ הַיּוֹם וָהָלְאָה הִתְעַשֵּׁר וּמָצָא אוֹצָר, וְהָיָה עוֹסֵק בַּתּוֹרָה וְנוֹתֵן מָזוֹן לַעֲנִיִּים כָּל יוֹם, וְהָיָה שָׂמֵחַ עִמָּהֶם, וּמַסְבִּיר לָהֶם בְּפָנִים מְאִירוֹת. קָרָא עָלָיו רַבִּי שִׁמְעוֹן, (ישעיה מא) וְאַתָּה תָּגִיל בַּה' בִּקְדוֹשׁ וְגוֹ'.</p>"],[9522011205,"<p>אַחַר הַדְּבָרִים הָאֵלֶּה הָיָה דְבַר ה' אֶל אַבְרָם וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (שיר ז) אֲנִי לְדוֹדִי וְעָלַי תְּשׁוּקָתוֹ. הֲרֵי פֵּרְשׁוּהָ, אֲבָל בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה תִּמְצָא הַהִתְעוֹרְרוּת שֶׁלְּמַעְלָה, שֶׁהֲרֵי אֵין מִתְעוֹרֵר לְמַעְלָה עַד שֶׁמִּתְעוֹרֵר לְמַטָּה, וְהַבְּרָכוֹת שֶׁלְּמַעְלָה לֹא נִמְצָאוֹת אֶלָּא בְּמַה שֶּׁיֵּשׁ בּוֹ מַמָּשׁ, וְאֵינוֹ רֵיקָן.</p>\n<p>מִנַּיִן לָנוּ? מֵאֵשֶׁת עוֹבַדְיָהוּ שֶׁאָמַר לָהּ אֱלִישָׁע (מלכים ב ד) הַגִּידִי לִי מַה יֶּשׁ לָךְ בַּבָּיִת. שֶׁהֲרֵי הַבְּרָכוֹת שֶׁלְּמַעְלָה אֵינָן שׁוֹרוֹת עַל שֻׁלְחָן רֵיק וְלֹא בְּמָקוֹם רֵיק. מַה כָּתוּב? וַתֹּאמֶר אֵין לְשִׁפְחָתְךְ כֹל בַּבַּיִת כִּי אִם אָסוּךְ שָׁמֶן. מַה זֶּה אָסוּךְ? אֶלָּא אָמְרָה לוֹ, הַשִּׁעוּר שֶׁל הַשֶּׁמֶן הַזֶּה אֵינוֹ אֶלָּא כְּדֵי מְשִׁיחַת אֶצְבַּע קְטַנָּה.</p>\n<p>אָמַר לָהּ, נִחַמְתַּנִי, שֶׁהֲרֵי לֹא יָדַעְתִּי אֵיךְ יִשְׁרוּ הַבְּרָכוֹת שֶׁלְּמַעְלָה בְּמָקוֹם רֵיק, אֲבָל עַכְשָׁו שֶׁיֵּשׁ לָךְ שֶׁמֶן, זֶהוּ מָקוֹם שֶׁיִּמָּצְאוּ בוֹ בְּרָכוֹת. מִנַּיִן לָנוּ? שֶׁכָּתוּב (תהלים קלג) כַּשֶּׁמֶן הַטּוֹב וְגוֹ'. וּבְסוֹפוֹ מַה כָּתוּב? (שם) כִּי שָׁם צִוָּה ה' אֶת הַבְּרָכָה חַיִּים עַד הָעוֹלָם. וּבַמָּקוֹם הַזֶּה שׁוֹרוֹת הַבְּרָכוֹת. (ונתבאר).</p>\n<p>וְאִם תֹּאמַר, (שם) כְּטַל חֶרְמוֹן שֶׁיֹּרֵד עַל הַרְרֵי צִיּוֹן, וְלֹא כָתוּב שֶׁמֶן אֶלָּא טַל? אֶלָּא הוּא שֶׁמֶן וְהוּא טַל. אוֹתוֹ הַטַּל הוּא שֶׁהִטִּיל הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהַשֶּׁמֶן הָעֶלְיוֹן. שֶׁאוֹתוֹ הַשֶּׁמֶן יוֹצֵא לְצַד הַיָּמִין.</p>\n<p>שְׁנַיִם הֵם - יַיִן וְשֶׁמֶן, וְהָלְכוּ לִשְׁנֵי צְדָדִים - הַיַּיִן לְצַד שְׂמֹאל, וְהַשֶּׁמֶן לְצַד יָמִין. וּמִצַּד הַיָּמִין יוֹצְאוֹת בְּרָכוֹת לָעוֹלָם, וּמִשָּׁם נִמְשַׁחַת הַמַּלְכוּת הַקְּדוֹשָׁה. וּמִשּׁוּם שֶׁהַשֶּׁמֶן הָיָה נִתְקָן לְמַטָּה בָּרִאשׁוֹנָה, הַשֶּׁמֶן מְזַמֵּן לְמַעְלָה הֲרָקַת הַבְּרָכוֹת.</p>\n<p>בֹּא רְאֵה, מֵהַהִתְעוֹרְרוּת שֶׁל הַשֶּׁמֶן הַזֶּה שֶׁלְּמַעְלָה בָּא לְהָרִיק עַל דָּוִד וּשְׁלֹמֹה לְהִתְבָּרֵךְ (על) בְּנוֹ. מִנַּיִן לָנוּ? שֶׁכָּתוּב וַיַּעֲמֹד הַשָּׁמֶן. כָּתוּב כָּאן וַיַּעֲמֹד, וְכָתוּב שָׁם (ישעיה יא) שֹׁרֶשׁ יִשַׁי אֲשֶׁר עֹמֵד לְנֵס עַמִּים.</p>\n<p>בֹּא רְאֵה, מִשֻּׁלְחָן שֶׁל לֶחֶם הַפָּנִים, שֶׁמִּשָּׁם יוֹצְאוֹת הַבְּרָכוֹת וּמָזוֹן לָעוֹלָם, לֹא צָרִיךְ שֶׁיִּמָּצֵא רֵיק אֲפִלּוּ רֶגַע אֶחָד, כְּדֵי שֶׁלֹּא יִסְתַּלְּקוּ מִשָּׁם הַבְּרָכוֹת. אַף כָּךְ לֹא מְבָרְכִים עַל שֻׁלְחָן רֵיק, שֶׁהֲרֵי הַבְּרָכוֹת שֶׁלְּמַעְלָה אֵין שׁוֹרוֹת עַל שֻׁלְחָן רֵיק.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, אֲנִי לְדוֹדִי וְעָלַי תְּשׁוּקָתוֹ. אֲנִי לְדוֹדִי בַּתְּחִלָּה, וְאַחַר כָּךְ וְעָלַי תְּשׁוּקָתוֹ. אֲנִי לְדוֹדִי לְתַקֵּן לוֹ מָקוֹם בַּתְּחִלָּה, וְאַחַר כָּךְ וְעָלַי תְּשׁוּקָתוֹ.</p>\n<p>דָּבָר אַחֵר אֲנִי לְדוֹדִי, שֶׁהֲרֵי שָׁנִינוּ שֶׁשְּׁכִינָה לֹא נִמְצֵאת עִם הָרְשָׁעִים. כֵּיוָן שֶׁבָּא הָאָדָם לְהִטָּהֵר וּלְהִתְקָרֵב לַקָּדוֹשׁ-בָּרוּךְ-הוּא, אָז הַשְּׁכִינָה שׁוֹרָה עָלָיו. זֶהוּ שֶׁכָּתוּב אֲנִי לְדוֹדִי - בַּהַתְחָלָה, וְעָלַי תְּשׁוּקָתוֹ - לְאַחַר מִכֵּן. בָּא הָאָדָם לְהִטָּהֵר - מְטַהֲרִים אוֹתוֹ.</p>\n<p>בֹּא רְאֵה, אַחַר הַדְּבָרִים הָאֵלֶּה שֶׁאַבְרָהָם רָדַף אַחַר הַמְּלָכִים הַלָּלוּ וְהָרַג אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, הָיָה אַבְרָהָם תּוֹהֶה. אָמַר, אוּלַי חַס וְחָלִילָה גָּרַעְתִּי אוֹתוֹ הַשָּׂכָר שֶׁהָיִיתִי מַחֲזִיר בְּנֵי אָדָם אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָחַזְתִּי בָהֶם לְקָרֵב אוֹתָם אֵלָיו, וְכָעֵת נֶהֶרְגוּ אֲנָשִׁים עַל יָדִי. מִיָּד אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַל תִּירָא אַבְרָם אָנֹכִי מָגֵן לָךְ שְׂכָרְךְ הַרְבֵּה מְאֹד וְגוֹ'. שָׂכָר קִבַּלְתָּ עֲלֵיהֶם, שֶׁהֲרֵי כֻּלָּם לֹא יִזְכּוּ לְעוֹלָמִים.</p>"],[9522011206,"<p>הָיָה דְבַר ה' אֶל אַבְרָם בַּמַּחֲזֶה לֵאמֹר, מַה זֶּה בַּמַּחֲזֶה? אֶלָּא בְּאוֹתוֹ הַמַּרְאֶה, הַדַּרְגָּה שֶׁכָּל הַדְּמֻיּוֹת נִרְאוֹת בָּהּ. אָמַר רַבִּי שִׁמְעוֹן, בּא רְאֵה, טֶרֶם שֶׁנִּמּוֹל אַבְרָהָם, הָיְתָה דַרְגָּה אַחַת מְדַבֶּרֶת עִמּוֹ, וּמִי הַמַּחֲזֶה הַזֶּה? שֶׁכָּתוּב (במדבר כד) מַחֲזֵה שַׁדַּי יֶחֱזֶה.</p>\n<p>כֵּיוָן שֶׁנִּמּוֹל, הָיוּ כָּל הַדְּרָגוֹת שׁוֹרוֹת עַל הַדַּרְגָּה הַזּוֹ, וְאָז דִּבֵּר עִמּוֹ. זֶהוּ שֶׁכָּתוּב (שמות ו) וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדַּי. וְטֶרֶם שֶׁנִּמּוֹל, לֹא הָיוּ אוֹתָן הַדְּרָגוֹת שׁוֹרוֹת עָלָיו לְדַבֵּר.</p>\n<p>וְאִם תֹּאמַר שֶׁהִנֵּה בַּתְּחִלָּה כָּתוּב וַיֵּרָא ה' אֶל אַבְרָם, וְכָתוּב וַיִּסַּע אַבְרָם הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה, וְכָתוּב וַיִּבֶן שָׁם מִזְבֵּחַ. הִנֵּה כָּאן אוֹתָן הַדְּרָגוֹת הָעֶלְיוֹנוֹת. וְכָעֵת אוֹמְרִים, שֶׁטֶּרֶם שֶׁנִּמּוֹל לֹא הָיָה אוֹתָן הַדְּרָגוֹת הָעֶלְיוֹנוֹת שׁוֹרוֹת עַל הַדַּרְגָּה הַזּוֹ לְדַבֵּר עִמּוֹ?</p>\n<p>בֹּא רְאֵה, בַּתְּחִלָּה נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא חָכְמָה לְאַבְרָהָם לָדַעַת אֶת הַחָכְמָה לְהִדָּבֵק בּוֹ, וְיָדַע אֶת סוֹד הָאֱמוּנָה, אֲבָל לְדַבֵּר עִמּוֹ לֹא הָיְתָה אֶלָּא הַדַּרְגָּה הַתַּחְתּוֹנָה הַזּוֹ לְבַדָּהּ. כֵּיוָן שֶׁנִּמּוֹל, כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת הָיוּ שׁוֹרוֹת עַל הַדַּרְגָּה הַזּוֹ הַתַּחְתּוֹנָה כְּדֵי לְדַבֵּר עִמּוֹ, וְאָז הִתְעַלָּה אַבְרָהָם בַּכֹּל, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, טֶרֶם שֶׁנִּמּוֹל הָאָדָם, לֹא נֶאֱחַז בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. כֵּיוָן שֶׁנִּמּוֹל, נִכְנַס בִּשְׁמוֹ וְנֶאֱחַז בּוֹ. וְאִם תֹּאמַר, אַבְרָהָם שֶׁנֶּאֱחַז בּוֹ טֶרֶם שֶׁנִּמּוֹל? כָּךְ הָיָה, שֶׁנֶּאֱחַז בּוֹ וְלֹא כָּרָאוּי, שֶׁהֲרֵי מִתּוֹךְ הָאַהֲבָה הָעֶלְיוֹנָה שֶׁאָהַב אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא קֵרַב אוֹתוֹ,</p>\n<p>אַחַר כָּךְ צִוָּה אוֹתוֹ שֶׁיִּמּוֹל וְנִתְּנָה לוֹ הַבְּרִית, הַקֶּשֶׁר שֶׁל כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת. הַבְּרִית - הַקֶּשֶׁר לְקַשֵּׁר הַכֹּל יַחַד לְהַכְלִיל זֶה עִם זֶה. הַבְּרִית - הַקֶּשֶׁר שֶׁהַכֹּל נִקְשָׁר בּוֹ. וּמִשּׁוּם כָּךְ, טֶרֶם שֶׁנִּמּוֹל אַבְרָהָם, דִּבּוּרוֹ לֹא הָיָה עִמּוֹ אֶלָּא בְּמַחֲזֶה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, לֹא נִבְרָא אֶלָּא עַל הַבְּרִית, כְּמוֹ שֶׁנֶּאֱמַר בָּרָ\"א שִׁי\"ת, בָּרָא אֱלֹהִים. וְהַיְנוּ (ברית) שֶׁעַל הַבְּרִית קִיֵּם הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, וְכָתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. שֶׁהֲרֵי הַבְּרִית הִיא הַקֶּשֶׁר שֶׁהַיּוֹם וְהַלַּיְלָה לֹא נִפְרָדִים.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עַל תְּנַאי הָיָה: שֶׁכַּאֲשֶׁר יָבֹאוּ יִשְׂרָאֵל, אִם יְקַבְּלוּ אֶת הַתּוֹרָה - יָפֶה, וְאִם לֹא - הֲרֵינִי מַחֲזִירְכֶם לְתֹהוּ וָבהוּ. וְהָעוֹלָם לֹא הִתְקַיֵּם עַד שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי וְקִבְּלוּ תוֹרָה, וְאָז הִתְקַיֵּם הָעוֹלָם.</p>\n<p>וּמֵאוֹתוֹ הַיּוֹם וָהָלְאָה, הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹרֵא עוֹלָמוֹת, וּמִי הֵם? זִוּוּגֵי בְּנֵי הָאָדָם. שֶׁהֲרֵי מֵאוֹתוֹ הַזְּמַן הַקָּדוֹשׁ בָּרוּךְ הוּא מְזַוֵּג זִוּוּגִים וְאוֹמֵר: בַּת פְּלוֹנִי לִפְלוֹנִי. וְאֵלּוּ הֵם הָעוֹלָמוֹת שֶׁהוּא בוֹרֵא. בּא רְאֵה, אָנֹכִי מָגֵן לָךְ, אָנֹכִי - זוֹ הִיא הַדַּרְגָּה הָרִאשׁוֹנָה שֶׁנֶּאֱחַז בָּהּ בַּתְּחִלָּה.</p>\n<p>אַחַר הַדְּבָרִים הָאֵלֶּה וְגוֹ' - אֵלּוּ דִּבְרֵי תוֹרָה, שֶׁכָּתוּב (דברים ה) אֶת הַדְּבָרִים הָאֵלֶּה דִּבֶּר ה' אֶל כָּל קְהַלְכֶם. מַה לְּהַלָּן דִּבְרֵי תוֹרָה - אַף כָּאן דִּבְרֵי תוֹרָה. אַחַר שֶׁהִשְׁתַּדֵּל אָדָם בָּעוֹלָם הַזֶּה בַּדְּבָרִים הָאֵלֶּה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְבַשֵּׂר לוֹ וּמַקְדִּים לַנְּשָׁמָה שָׁלוֹם (בשורות טובות), זֶהוּ שֶׁכָּתוּב אַל תִּירָא אַבְרָם אָנֹכִי מָגֵן לָךְ, מִכָּל הַמִּינִים הָרָעִים שֶׁל הַגֵּיהִנֹּם.</p>\n<p>שְׂכָרְךָ הַרְבֵּה מְאֹד, מִשּׁוּם שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה בָּעוֹלָם הַזֶּה, זוֹכֶה וְנוֹחֵל יְרֻשַּׁת נַחֲלָה בָּעוֹלָם הַבָּא, כַּכָּתוּב (משלי ח) לְהַנְחִיל אֹהֲבַי יֵשׁ. מַה זֶּה יֵ\"שׁ? (זה י\"ש מאין שלש עשרה נהרות אפרסמון טהור (מדּות) שנותנים לו ירשה עליונה בעולם הבא (נ\"א: זה הָעולָם הבָּא). ואצרתיהם אמלא - בעולם הזה, מעשר וכל טוב של העולם.) מי שהולך לימין - זוכה לעולם הבא, ומי שהולך לשמאל - הנה עשר בעולם הזה (שיש שמאל קדוש ויש שמאל טמא, וזה הוא שאמרנו, מי שמתעסק בתורה, נותנים לו ארך ימים בעולם הבא ונותנים לו עשר וכבוד בעולם הזה, שנאמר (משלי ג) ארך ימים בימינה וגו', ומי שירצה שיהנה הגוף בעולם הזה ולא מתעסק בתורה ובמעשים טובים, נותנים לו עשר בעולם הזה מצד השמאל, מצד היצר הרע, ובעשר הזה עושה רע ויורש גיהנם, ואם תאמר, וכי אין בעולם הזה עשר מצד הקדשה? כן, שכל המקים את התורה מעני, סופו לקימה מעשר, וזהו עשר טוב שמצד הקדשה).</p>\n<p>כשבא משם רבי אבא, היה מכריז: מי רוצה עשר ומי רוצה ארך חיים בעולם הבא, יבא וישתדל בתורה. היו מתכנסים אליו כל העולם. היה רוק אחד בשכונתו. יום אחד בא אליו. אמר לו: רבי, אני רוצה לעסק בתורה כדי שיהיה לי עשר. אמר לו: הנה ודאי. אמר לו: מה שמך? אמר לו: יוסי. אמר לתלמידיו שיקראו לו רבי יוסי בעל העשר והכבוד. ישב והתעסק בתורה.</p>\n<p>לימים היה עומד לפניו. אמר לו: רבי, איפה העשר? אמר: נשמע מזה שלא עשה לשם שמים. נכנס לחדרו, שמע קול אחד שהיה אומר: אל תעניש אותו (שוב אליו), שיהיה איש גדול. שב אליו. אמר לו: שב, בני, שב, ואני נותן לך עשר.</p>\n<p>בינתים בא איש אחד וכלי של פז בידו. הוציא אותו ונפל אור בבית. אמר לו: רבי, אני רוצה לזכות בתורה ואני לא זכיתי, ורוצה מי שישתדל בתורה בשבילי, שהרי יש לי עשר רב שהשאיר לי אבי, שכאשר ישב על שלחנו היה מסדר עליו שלשה עשר כוסות מאלו, ואני רוצה לזכות בתורה ואני נותן עשר.</p>\n<p>אמר לאותו הרוק: תשתדל בתורה, וזה נותן לך עשר. נתן לו אותו הכוס של הפז. קרא עליו רבי אבא: (איוב כח) לא יערכנה זהב וזכוכית ותמורתה כלי פז. ישב ולמד בתורה, והאדם ההוא היה נותן לו עשר.</p>\n<p>לימים נכנסה חמדת התורה למעיו. יום אחד היה יושב והיה בוכה. מצא אותו רבו שהיה בוכה. אמר לו: על מה אתה בוכה? אמר לו: ומה אני מניח את חיי העולם הבא בשביל זה? איני רוצה אלא לזכות אצלי. אמר: עכשו מזה נשמע שהנה עשה לשם שמים.</p>\n<p>קָרָא לְאוֹתוֹ הָאִישׁ, אָמַר לוֹ: טֹל אֶת עָשְׁרְךְ וְתֵן אוֹתוֹ לִיתוֹמִים וַעֲנִיִּים, וַאֲנִי נוֹתֵן לְךְ חֵלֶק יָתֵר בַּתּוֹרָה בְּכָל מַה שֶּׁאֲנִי לוֹמֵד. הֶחֱזִיר לוֹ רַבִּי יוֹסֵי אוֹתוֹ הַכּוֹס שֶׁל פָּז, וְעַד הַיּוֹם לֹא סָר שְׁמוֹ, וּמִבָּנָיו בֶּן פָּזִי, וְהַיְנוּ רַבִּי יוֹסֵי בֶּן פָּזִי, וְזָכָה לְכַמָּה תוֹרָה הוּא וּבָנָיו (משום שלמד תורה). שֶׁאֵין לְךְ שָׂכָר טוֹב בָּעוֹלָם כְּמִי שֶׁלּוֹמֵד תּוֹרָה וּמְקַיֵּם אוֹתָהּ.</p>\n<p>אַחַר הַדְּבָרִים הָאֵלֶּה הָיָה דְבַר ה' אֶל אַבְרָם בַּמַּחֲזֶה לֵאמֹר וְגוֹ'. בְּכָל מָקוֹם שֶׁכָּתוּב בַּתּוֹרָה בַּמַּחֲזֶה, זֶה הַשֵּׁם שֶׁהִתְגַּלָּה לָאָבוֹת, וּמִי הוּא? שַׁדַּ\"י, שֶׁנֶּאֱמַר (שמות ו) וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדַּי, כְּמוֹ שֶׁנֶּאֱמַר (במדבר כד) אֲשֶׁר מַחֲזֵה שַׁדַּי יֶחֱזֶה. וְזֶה הַמַּרְאֶה שֶׁכָּל הַמַּרְאוֹת הָעֶלְיוֹנוֹת נִרְאִים מִתּוֹכוֹ. כְּמוֹ הַמַּרְאֶה הַזֶּה שֶׁכָּל הַדְּמֻיּוֹת נִרְאוֹת בּוֹ וְהַכֹּל אֶחָד. מַרְאֶה וּמַחֲזֶה הוּא אֶחָד. זֶה תַרְגּוּם וְזֶה לְשׁוֹן הַקֹּדֶשׁ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, רַבִּים הֵם בַּתּוֹרָה, וְעַל כֵּן הָיְתָה רְשׁוּת לְאוּנְקְלוּס לְתַרְגֵּם בְּאוֹתָהּ הַלָּשׁוֹן שֶׁגִּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתּוֹרָה, וְהַלָּשׁוֹן הַזּוֹ הִיא נִסְתֶּרֶת מֵהַמַּלְאָכִים הָעֶלְיוֹנִים. בַּמַּחֲזֶה, (שהנה) שֶׁהָיָה נִסְתָּר מֵהַמַּלְאָכִים הָעֶלְיוֹנִים שֶׁאֵינָם יוֹדְעִים בָּזֶה כְּשֶׁמְּדַבֵּר עִם אַבְרָהָם.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁאַבְרָהָם לֹא הָיָה מָהוּל, וְהָיָה עָרֵל סְתוּם בָּשָׂר, וּמִשּׁוּם כָּךְ הָיָה מַסְתִּיר מֵהֶם בִּלְשׁוֹן תַּרְגּוּם. כְּמוֹ כֵן בְּבִלְעָם, שֶׁכָּתוּב אֲשֶׁר מַחֲזֵה שַׁדַּי יֶחֱזֶה. יֶחֱזֶה, נִסְתָּר הָיָה הַדָּבָר מִתּוֹךְ מַלְאֲכֵי הַשָּׁרֵת כְּדֵי שֶׁלֹּא יִהְיֶה לָהֶם פִּתְחוֹן פֶּה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְדַבֵּר עִם אוֹתוֹ הֶעָרֵל הַטָּמֵא, שֶׁהֲרֵי הַמַּלְאָכִים הַקְּדוֹשִׁים אֵינָם (קוראים) נִזְקָקִים לִלְשׁוֹן תַּרְגּוּם.</p>\n<p>אִם תֹּאמַר שֶׁלֹּא יוֹדְעִים - וַהֲרֵי גַבְרִיאֵל לִמֵּד אֶת יוֹסֵף שִׁבְעִים לָשׁוֹן, וְהַתַּרְגּוּם הוּא אֶחָד מִשִּׁבְעִים לָשׁוֹן? אֶלָּא יָדוֹעַ יוֹדְעִים, אֲבָל שָׁנִינוּ שֶׁלֹּא נִזְקָקִים, שֶׁאֵין חוֹשְׁשִׁים וְאֵין מִתְבּוֹנְנִים עָלָיו, שֶׁהֲרֵי הוּא מָאוּס לִפְנֵיהֶם מִכָּל שְׁאָר הַלְּשׁוֹנוֹת.</p>\n<p>וְאִם תֹּאמַר, שֶׁהוֹאִיל וְהוּא מָאוּס מִן הַמַּלְאָכִים הָעֶלְיוֹנִים, לָמָּה תִרְגֵּם אוּנְקְלוּס אֶת הַתּוֹרָה בַּלָּשׁוֹן הַזּוֹ, וְיוֹנָתָן בֶּן עֻזִּיאֵל אֶת הַמִּקְרָא? אֶלָּא מָאוּס הוּא לִפְנֵיהֶם, וְכָךְ צָרִיךְ! שֶׁאֵין קִנְאָה לַמַּלְאָכִים הָעֶלְיוֹנִים עִם יִשְׂרָאֵל יוֹתֵר, וְעַל כֵּן תַּרְגּוּם תּוֹרָה וּמִקְרָא כָּךְ, וְאֵינוֹ מָאוּס, שֶׁהֲרֵי בְּכַמָּה מְקוֹמוֹת כָּתַב הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתּוֹרָה כָּךְ.</p>\n<p>וּמִשּׁוּם כָּךְ הוּא נִסְתָּר מִתּוֹךְ הַמַּלְאָכִים הָעֶלְיוֹנִים הַקְּדוֹשִׁים. וְעַל כֵּן הִתְגַּלָּה לְאַבְרָהָם בְּדֶרֶךְ נִסְתָּר, שֶׁלֹּא יַשְׁגִּיחוּ בוֹ הַמַּלְאָכִים הַקְּדוֹשִׁים, וְלֹא יִהְיֶה לָהֶם פִּתְחוֹן פֶּה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְגַּלָּה עַל אִישׁ עָרֵל.</p>\n<p>מָתַי הִתְגַּלָּה לוֹ בְּהִתְגַּלּוּת שֶׁל מַלְאָכִים עֶלְיוֹנִים? כַּאֲשֶׁר נָתַן לוֹ בְּרִית קִיּוּם הַקֹּדֶשׁ, שֶׁכָּתוּב וַיְדַבֵּר אִתּוֹ אֱלֹהִים לֵאמֹר. אֱלֹהִים - הַשֵּׁם שֶׁל הַקֹּדֶשׁ, וְלֹא כָתוּב בְּמַחֲזֵה הַשֵּׁם בַּהִתְגַּלּוּת.</p>\n<p>לֵאמֹר, מַה זֶּה לֵאמֹר? לֵאמֹר וּלְהַכְרִיז בְּכָל לָשׁוֹן שֶׁלֹּא תִהְיֶה בִּמְכֻסֶּה, לֹא בְּלָשׁוֹן אַחֶרֶת, אֶלָּא בְּלָשׁוֹן שֶׁכֻּלָּם מְדַבְּרִים בָּהּ, שֶׁיְּכוֹלִים לוֹמַר זֶה לָזֶה וְלֹא יְכוֹלִים לְקַטְרֵג וְלוֹמַר פִּתְחוֹן פֶּה, וְעַל כֵּן וַיְדַבֵּר אִתּוֹ אֱלֹהִים לֵאמֹר. אֱלֹהִים וְלֹא מַחֲזֶה, מִשּׁוּם שֶׁהָיָה מַכְנִיס אוֹתוֹ לִבְרִית קִיּוּם הַקֹּדֶשׁ וְקֵרַב אוֹתוֹ אֵלָיו.</p>\n<p>רַבִּי יְהוּדָה אָמַר, מִשּׁוּם כָּךְ הַהֵ\"א לֹא נִתְּנָה לוֹ עַד שֶׁנִּמּוֹל. מָה הַטַּעַם? שֶׁהִיא מַמָּשׁ נִקְרֵאת בְּרִית. וְעַל כֵּן, כֵּיוָן שֶׁנִּכְנַס בַּבְּרִית, אָז נִתְּנָה לוֹ הָאוֹת הֵ\"א, שֶׁכָּתוּב אֲנִי הִנֵּה בְּרִיתִי אִתָּךְ וְהָיִיתָ לְאַב הֲמוֹן גּוֹיִם וְלֹא יִקָּרֵא עוֹד שִׁמְךְ אַבְרָם וְגוֹ'.</p>"],[9522011207,"<p>אַחַר הַדְּבָרִים הָאֵלֶּה. רַבִּי חִיָּיא הָיָה הוֹלֵךְ לִרְאוֹת אֶת רַבִּי אֶלְעָזָר. פָּגַשׁ אוֹתוֹ רַבִּי חַגַּאי. אָמַר לוֹ, הַדֶּרֶךְ הַזּוֹ שֶׁמְּתֻקֶּנֶת לִפְנֵי מַר, לְאָן הוֹלֶכֶת הִיא? אָמַר לוֹ, לִרְאוֹת אֶת רַבִּי אֶלְעָזָר. אָמַר לוֹ, וְגַם אֲנִי אֵלֵךְ עִמְּךְ? אָמַר לוֹ, אִם תּוּכַל לְהָבִין לְהַשְׂכִּיל לְמַה שֶּׁתִּשְׁמַע - לֵךְ, וְאִם לֹא - שׁוּב לַאֲחוֹרֶיךְ. אָמַר לוֹ, שֶׁלֹּא יַחְשֹׁשׁ מוֹר לָזֶה, שֶׁהֲרֵי אֲנִי שָׁמַעְתִּי כַּמָּה סוֹדוֹת שֶׁל תּוֹרָה וְיָכֹלְתִּי לַעֲמֹד בָּהֶן.</p>\n<p>פָּתַח רַבִּי חַגַּאי וְאָמַר, מַה שֶּׁכָּתוּב (במדבר כח) אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי וְגוֹ', אֶת קָרְבָּנִי - זֶה קָרְבַּן הַבָּשָׂר שֶׁנִּקְרָב לְכַפֵּר דָּם עַל דָּם, בָּשָׂר עַל בָּשָׂר, מִשּׁוּם שֶׁכָּל הַקָּרְבָּנוֹת לֹא נִקְרָבִים אֶלָּא הַבָּשָׂר לְכַפֵּר עַל הַבָּשָׂר.</p>\n<p>וְכָךָ שָׁמַעְתִּי, אִם אָדָם חָטָא - בְּהֵמָה מֶה חָטְאָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר (ויקרא א) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן וְגוֹ'? לָמָּה? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת רוּחַ בְּנֵי אָדָם וְאֶת רוּחַ הַבְּהֵמָה, וְהִפְרִיד זוֹ מִזּוֹ, וּמִשּׁוּם כָּךְ (קהלת ג) רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעְלָה וְרוּחַ הַבְּהֵמָה וְגוֹ'. וַדַּאי נִפְרָדִים זֶה מִזֶּה.</p>\n<p>בְּטֶרֶם שֶׁחָטָא אָדָם מַה כָּתוּב? (בראשית א) וַיֹּאמֶר אֱלֹהִים הִנֵּה נָתַתִּי לָכֶם אֶת כָּל עֵשֶׂב זרֵעַ זֶרַע וְגוֹ', וְכָתוּב לָכֶם יִהְיֶה לְאָכְלָה, וְלֹא יוֹתֵר! כֵּיוָן שֶׁחָטָא וְהַיֵּצֶר נִשְׁאַב לְגוּפוֹ, וּבְכָל אוֹתָם הַתּוֹלָדוֹת עָשָׂה דִין,</p>\n<p>וְאַחַר בָּא נֹחַ וְרָאָה שֶׁהִנֵּה הַגּוּף נִבְנָה מֵהַמָּקוֹם שֶׁל הַיֵּצֶר הָרָע, הִקְרִיב קָרְבָּן כְּמוֹ שֶׁהִקְרִיב אָדָם, מַה כָּתוּב? (שם ח) וַיָּרַח ה' אֶת רֵיחַ הַנִּיחֹחַ וְגוֹ', וְכָתוּב כִּי יֵצֶר לֵב הָאָדָם רַע מִנְּעֻרָיו. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִכָּאן וָהָלְאָה, הוֹאִיל וְהַגּוּף נִשְׁאָב מֵאוֹתוֹ הַיֵּצֶר הָרָע, יִתְעַנֵּג הַגּוּף כְּמוֹ שֶׁרָאוּי לוֹ, יֹאכַל בָּשָׂר. כְּיֶרֶק עֵשֶׂב נָתַתִּי לָכֶם אֶת כֹּל.</p>\n<p>כְּשֶׁאוֹכֵל בָּשָׂר, מֵאוֹתוֹ הַבָּשָׂר מִתְעַנֵּג הַבָּשָׂר שֶׁלּוֹ, וּמִתְעָרְבִים זֶה עִם זֶה וּמִתְגַּדֵּל מִמֶּנּוּ הַגּוּף, וּמֵאוֹתוֹ הָעֹנֶג הַגּוּף חוֹטֵא בְּכַמָּה חֲטָאִים. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, הַבָּשָׂר כַּפָּרָה עַל הַגּוּף. בָּשָׂר אוֹכֵל, וּבָשָׂר מִתְרַבֶּה מִמֶּנּוּ, וּבוֹ חָטָא. מִשּׁוּם כָּךְ בָּשָׂר לְכַפֵּר עַל גּוּפוֹ, וְהַבָּשָׂר שֶׁאוֹכֵל עוֹשֶׂה דָּם לַגּוּף (משום כך הדם שנשאר מאותו הבשר שאוכל, הבשר עושה לגוף דם). מִשּׁוּם כָּךְ, הַדָּם שֶׁנִּשְׁאָר מֵאוֹתוֹ הַבָּשָׂר בַּחוּץ, מִתְעַתֵּד לְכַפֵּר עַל הַדָּם שֶׁנַּעֲשָׂה מֵאוֹתוֹ הַבָּשָׂר שֶׁלּוֹ, שֶׁכָּתוּב (ויקרא יז) כִּי הַדָּם הוּא בַּנֶּפֶשׁ יְכַפֵּר.</p>\n<p>כָּתוּב קָרְבָּנִי, וְכָתוּב קָרְבַּנְכֶם, שֶׁכָּתוּב (שם א) תַּקְרִיבוּ אֶת קָרְבַּנְכֶם. מַה בֵּין זֶה לָזֶה? אֶלָּא קָרְבָּנִי - כְּמוֹ שְׁלָמִים שֶׁבָּאִים עַל שָׁלוֹם. קָרְבַּנְכֶם - כְּמוֹ חַטָּאוֹת וַאֲשָׁמוֹת שֶׁבָּאִים עַל חֵטְא וְאָשָׁם. מִשּׁוּם כָּךְ, (במדבר כח) אֶת קָרְבָּנִי - בָּשָׂר. לַחְמִי - לֶחֶם וְיַיִן. רֵיחַ - זוֹ הַקְּטֹרֶת. נִיחֹחִי - זוֹ נַחַת רוּחַ שֶׁעוֹשֶׂה הַכֹּהֵן בָּרָצוֹן שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וְהַלְוִיִּם בְּרָצוֹן שֶׁל שִׁיר וּשְׁבָחָה.</p>\n<p>תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ, מַה זֶּה בְּמוֹעֲדוֹ? אִם תֹּאמַר בְּכָל יוֹם בַּבֹּקֶר וּבָעֶרֶב, מַה זֶּה בְּמוֹעֲדוֹ? (נ\"א: מה אומר שהוא מו דו)? אֶלָּא הַמּוֹעֲדוֹ שֶׁשּׁוֹלֵט בְּאוֹתָהּ עֵת רָצוֹן, הָרָצוֹן שֶׁנִּמְצָא לְמַעְלָה בְּדַרְגָּה יְדוּעָה. וְעַל כֵּן כָּתוּב בְּמוֹעֲדוֹ.</p>\n<p>כְּשֶׁנִּקְרָב הַקָּרְבָּן. הַכֹּל נוֹטְלִים חֵלֶק, וּמִתְפַּזְּרוֹת הַקְּלִפּוֹת לְכָל צַד, וְהַיִּחוּד נִקְרָב וּמִתְיַחֵד, וְהַמְּאוֹרוֹת מְאִירִים, וְנִמְצָא רָצוֹן בְּכָל הָעוֹלָמוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בְּסוֹד שֶׁל יִחוּד אֶחָד כָּרָאוּי. בָּא רַבִּי חִיָּיא וְנָשַׁק אוֹתוֹ. אָמַר לוֹ, נָאֶה אַתָּה, בְּנִי, מִמֶּנִּי לָלֶכֶת וְלִרְאוֹת אֶת סֵבֶר פְּנֵי הַיָּמִים. (עוד פתח ואמר דוד המלך, שהוא רביעי, שהוא אבן מאסו הבונים) (נ\"א: למה דוד המלך ירש המלכות? שהוא הרביעי, שהוא אבן מאסו הבונים).</p>\n<p>הָלְכוּ, כְּשֶׁהִגִּיעוּ אֵלָיו, רָאָה אוֹתָם יוֹשְׁבִים עַל הַשַּׁעַר. אָמַר לוֹ לַשַּׁמָּשׁ, לֵךְ וֶאֱמֹר לָהֶם, הַכִּסֵּא הַזֶּה שֶׁל שְׁלֹשָׁה עַמּוּדִים מַה הוּא כָּל אֶחָד (הכל אחד)? אָמְרוּ לוֹ, לֵךְ וֶאֱמֹר לוֹ לְמַר, שֶׁלֹּא לְחִנָּם אָמַר דָּוִד הַמֶּלֶךְ, שֶׁהוּא הָרְבִיעִי, אֶבֶן מָאֲסוּ הַבּוֹנִים. אָמַר לוֹ, לֵךְ וֶאֱמֹר לָהֶם, שֶׁאֵיפֹה מָאֲסוּ בוֹ בְּדָוִד שֶׁהוּא אָמַר אֶבֶן מָאֲסוּ הַבּוֹנִים.</p>\n<p>הֶחֱזִיר רַבִּי חִיָּיא אֶת רֹאשׁוֹ לְרַבִּי חַגַּאי, וְאָמַר לוֹ, הֲשָׁמַעְתָּ בָּזֶה דָּבָר? אָמַר, שָׁמַעְתִּי בַּפָּסוּק הַזֶּה שֶׁכָּתוּב (שיר א) \"בְּנֵי \"אִמִּי \"נִחֲרוּ בִי שָׂמוּנִי וְגוֹ', שֶׁהַפָּסוּק הַזֶּה אָמַר אוֹתוֹ שְׁלֹמֹה, וְעַל דָּוִד הַמֶּלֶךְ הוּא נֶאֱמַר, כְּשֶׁדָּחוּ אוֹתוֹ הָאַחִים שֶׁלּוֹ מֵהֶם.</p>\n<p>וְעוֹד שָׁמַעְתִּי, מָה רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת מַלְכוּת לִיהוּדָה מִכָּל אֶחָיו? אֶלָּא אוֹתִיּוֹת שְׁמוֹ חֲקוּקוֹת בּוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן כָּבוֹד לִשְׁמוֹ, וּמִשּׁוּם כָּךְ יָרַשׁ אֶת הַמַּלְכוּת. וְעוֹד שָׁמַעְתִּי, יְהוּדָה - הִנֵּה אוֹתִיּוֹת שְׁמוֹ וַדַּאי. ד' אֵינֶנָּה לָמָּה? אֶלָּא זֶה דָּוִד הַמֶּלֶךְ שֶׁנִּקְשַׁר בִּשְׁמוֹ מִכָּל בְּנֵי הָעוֹלָם, שֶׁכָּתוּב (הושע ג) וּבִקְשׁוּ אֶת ה' אֱלֹהֵיהֶם וְאֵת דָּוִיד מַלְכָּם וְגוֹ'. הִנֵּה דָּוִד קָשׁוּר בִּשְׁמוֹ. וְעוֹד, שֶׁהוּא קֶשֶׁר שֶׁל תְּפִלִּין וַדַּאי, ד' דָּוִד הַמֶּלֶךְ (ד\"א קשר של תפלין ודאי), וּמִשּׁוּם כָּךְ דָּוִד נִקְשַׁר בִּשְׁמוֹ.</p>\n<p>נִכְנְסוּ, כֵּיוָן שֶׁנִּכְנְסוּ, יָשְׁבוּ לְפָנָיו. שָׁתַק רַבִּי אֶלְעָזָר וְהֵם שָׁתְקוּ. נִכְנַס רַבִּי אֶלְעָזָר לְחַדְרוֹ, וְשָׁמַע קוֹל אֶחָד שֶׁהָיָה אוֹמֵר: לֵךְ וֶאֱמֹר לָהֶם מַה שֶּׁהֵם רוֹצִים, שֶׁהֲרֵי הֵם כְּשֵׁרִים. חָזַר אֲלֵיהֶם. אָמַר לָהֶם, אִם יֵשׁ מִי שֶׁשָּׁמַע דָּבָר - שֶׁיֹּאמַר לִי. אָמְרוּ לוֹ, אָנוּ מְחַכִּים לִהְיוֹת מוּאָרִים מִתּוֹךְ הַצַּחוּת שֶׁל הַמָּאוֹר הָעֶלְיוֹן, וּלְהָבִין וּלְהַשְׂכִּיל.</p>\n<p>פָּתַח וְאָמַר, (חבקוק ב) וַה' בְּהֵיכַל קָדְשׁוֹ הַס מִפָּנָיו כָּל הָאָרֶץ. כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָם, הִסְתַּכֵּל בְּתוֹךְ הַמַּחֲשָׁבָה סוֹד הַתּוֹרָה וְרָשַׁם רִשּׁוּמִים, וְלֹא הָיָה יָכוֹל לַעֲמֹד, עַד שֶׁבָּרָא הַתְּשׁוּבָה, שֶׁהִיא הֵיכָל פְּנִימִי עֶלְיוֹן וְסוֹד נִסְתָּר, וְשָׁם נִרְשְׁמוּ וְהִצְטַיְּרוּ הָאוֹתִיּוֹת בַּחֲקִיקוֹתֵיהֶן.</p>\n<p>כֵּיוָן שֶׁזֶּה נִבְרָא, הָיָה מִסְתַּכֵּל בַּהֵיכָל הַזֶּה, וְרוֹשֵׁם לְפָנָיו צִיּוּרִים שֶׁל כָּל הָעוֹלָם, שֶׁכָּתוּב הַס מִפָּנָיו כָּל הָאָרֶץ. רָשַׁם לְפָנָיו רִשּׁוּמִים וְצִיּוּרִים שֶׁל כָּל הָעוֹלָם. רָצָה לִבְרֹא שָׁמַיִם, מֶה עָשָׂה? הִסְתַּכֵּל בָּאוֹר הָרִאשׁוֹן וְהִתְעַטֵּף בּוֹ וּבָרָא שָׁמַיִם, שֶׁכָּתוּב (תהלים קד) עֹטֶה אוֹר כַּשַּׂלְמָה, וְאַחַר כָּךְ נוֹטֶה שָׁמַיִם כַּיְרִיעָה.</p>\n<p>הִסְתַּכֵּל לַעֲשׂוֹת הָעוֹלָם הַתַּחְתּוֹן, עָשָׂה הֵיכָל אַחֵר וְנִכְנַס בּוֹ, וּמִמֶּנּוּ הִסְתַּכֵּל וְרָשַׁם לְפָנָיו אֶת כָּל הָעוֹלָמוֹת לְמַטָּה וּבָרָא אוֹתוֹ. זֶהוּ שֶׁכָּתוּב וַה' בְּהֵיכַל קָדְשׁוֹ הַס מִפָּנָיו כָּל הָאָרֶץ. הַ\"ס מִפָּנָיו - ה\"ס רָשַׁם לְפָנָיו כָּל הַנְּקֻדּוֹת שֶׁל כָּל הָעוֹלָם, שֶׁהֵם שִׁשִּׁים וְחָמֵשׁ כְּחֶשְׁבּוֹן ה\"ס. שִׁשִּׁים וְחָמֵשׁ הֵן. וְכֻלָּן רָשַׁם לְפָנָיו כְּשֶׁבָּרָא אֶת הָעוֹלָם. מִשּׁוּם כָּךְ כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵינוֹ אֶלָּא לְאוֹתָם שֶׁיּוֹדְעִים דְּרָכָיו וְהוֹלְכִים בָּהֶם בְּדֶרֶךְ אֱמֶת כָּרָאוּי.</p>\n<p>בֵּינְתַיִם שֶׁהָיָה מְדַבֵּר עִמָּם, בָּאָה אֵשׁ וְהִקִּיפָה אוֹתוֹ, וְהֵם יָשְׁבוּ בַּחוּץ. שָׁמְעוּ קוֹל אֶחָד שֶׁהָיָה אוֹמֵר: אֵי קָדוֹשׁ, הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו, בְּכָל אוֹתָם הַחֲדָרִים שֶׁל פְּנֵי הַזָּקֵן, הָעֵלֶם הַקָּדוֹשׁ (העלמה הקדושה) שֶׁנִּמְסְרוּ הַמַּפְתְּחוֹת שֶׁלָּהֶם בְּיָדוֹ, וְכֻלָּם מְתֻקָּנִים לְךְ וּלְאוֹתָם שֶׁבִּשְׁבִילְךְ. וּבְחַיֶּיךְ הַקְּדוֹשִׁים, כָּל צְבָא הַשָּׁמַיִם נָגִילָה וְנִשְׂמְחָה בָךְ.</p>\n<p>כְּשֶׁאֵלֶּה רָאוּ כָּךְ, הִזְדַּעְזְעוּ, וּפַחַד רַב נָפַל עֲלֵיהֶם. אָמְרוּ, אֵינֶנּוּ רְאוּיִים לָזֶה, נֵצֵא מִכָּאן וְנֵלֵךְ לְדַרְכֵּנוּ. (הלכו). יָשְׁבוּ שָׁם כָּל אוֹתוֹ יוֹם וְלֹא יָכְלוּ לִרְאוֹת אוֹתוֹ, וְאָמְרוּ, אֵין רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנֵּשֵׁב כָּאן. יָצְאוּ מִשָּׁם וְהָלְכוּ.</p>"],[9522011208,"<p>בְּעוֹדָם הוֹלְכִים, פָּתַח רַבִּי חִיָּיא וְאָמַר, (שם קג) בָּרְכוּ ה' מַלְאָכָיו גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ וְגוֹ'. אַשְׁרֵיהֶם יִשְׂרָאֵל מִכָּל שְׁאָר הָעַמִּים שֶׁל הָעוֹלָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם מִכָּל שְׁאָר הָעַמִּים וְעָשָׂה אוֹתָם חֶלְקוֹ וְנַחֲלָתוֹ, וְעַל כֵּן נָתַן לָהֶם תּוֹרָה קְדוֹשָׁה, מִשּׁוּם שֶׁכֻּלָּם הָיוּ בְּרָצוֹן אֶחָד עַל הַר סִינַי וְהִקְדִּימוּ עֲשִׂיָּה לִשְׁמִיעָה.</p>\n<p>כֵּיוָן שֶׁהִקְדִּימוּ עֲשִׂיָּה לִשְׁמִיעָה, קָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לַפַּמַלְיָה שֶׁלּוֹ. אָמַר לָהֶם, עַד כָּאן אַתֶּם הֱיִיתֶם יְחִידִים לְפָנַי בָּעוֹלָם, מִכָּאן וָהָלְאָה הִנֵּה בָּנַי בָּאָרֶץ חֲבֵרִים עִמָּהֶם בַּכֹּל. אֵין לָכֶם רְשׁוּת לְקַדֵּשׁ אֶת שְׁמִי עַד שֶׁיִּשְׂרָאֵל יִתְחַבְּרוּ עִמָּכֶם בָּאָרֶץ, וְכֻלְּכֶם תִּהְיוּ יַחַד חֲבֵרִים לְקַדֵּשׁ אֶת שְׁמִי, מִשּׁוּם שֶׁהִקְדִּימוּ עֲשִׂיָּה לִשְׁמִיעָה כְּמוֹ שֶׁעוֹשִׂים הַמַּלְאָכִים הָעֶלְיוֹנִים בָּרָקִיעַ, שֶׁכָּתוּב בָּרְכוּ ה' מַלְאָכָיו גִּבֹּרֵי כֹחַ עֹשֵׂ\"י דְבָרוֹ לִשְׁמֹ\"עַ בְּקוֹל דְּבָרוֹ. עֹשֵׂי דְבָרוֹ בַּהַתְחָלָה, וְאַחַר כָּךְ לִשְׁמֹעַ.</p>\n<p>דָּבָר אַחֵר בָּרְכוּ ה' מַלְאָכָיו - אֵלּוּ אוֹתָם הַצַּדִּיקִים בָּאָרֶץ שֶׁהֵם חֲשׁוּבִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כַּמַּלְאָכִים הָעֶלְיוֹנִים בָּרָקִיעַ, מִשּׁוּם שֶׁהֵם גִּבּוֹרֵי כֹחַ שֶׁמִּתְגַּבְּרִים עַל יִצְרָם כְּגִבּוֹר טוֹב שֶׁמִּתְגַּבֵּר עַל שׂוֹנְאוֹ. לִשְׁמֹעַ בְּקוֹל דְּבָרוֹ - שֶׁזּוֹכִים בְּכָל יוֹם לִשְׁמֹעַ קוֹל מִלְמַעְלָה בְּשָׁעָה שֶׁמִּצְטָרְכִים.</p>\n<p>כָּעֵת מִי יָכוֹל לַעֲמֹד עִם אוֹתָם שֶׁהֵם קְדוֹשִׁים עֶלְיוֹנִים? אַשְׁרֵי אוֹתָם שֶׁיְּכוֹלִים לַעֲמֹד לִפְנֵיהֶם. אַשְׁרֵי אוֹתָם שֶׁיְּכוֹלִים (למי שיוכל) לְהִנָּצֵל מִלִּפְנֵיהֶם. הַשְׁגָּחָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם בְּכָל יוֹם. אֵיךְ אָנוּ יְכוֹלִים לְהִכָּנֵס לִפְנֵיהֶם? וְעַל זֶה כָּתוּב (שם סה) אַשְׁרֵי תִּבְחַר וּתְקָרֵב, וְכָתוּב (שם פד) אַשְׁרֵי אָדָם עוֹז לוֹ בָךְ וְגוֹ'. (עד כאן סתרי תורה).</p>"],[9522011209,"<p>וַיֹּאמֶר אַבְרָם אֲדנָי יֱהִֹוִ\"ה מַה תִּתֶּן לִי. אֲדנָ\"י - אָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד. אֱלֹהִים - יוֹ\"ד הֵ\"א וָי\"ו הֵ\"א (אלהים יהוה בנקוד אלהים). אֶלָּא סוֹד הַדָּבָר - חִבּוּר שֶׁל שְׁנֵי עוֹלָמוֹת יַחַד, הָעוֹלָם הַתַּחְתּוֹן וְהָעוֹלָם הָעֶלְיוֹן.</p>\n<p>מַה תִּתֶּן לִי וְאָנֹכִי הוֹלֵךְ עֲרִירִי, שֶׁאֵין לִי בֵּן. וְלָמַדְנוּ, שֶׁכָּל מִי שֶׁאֵין לוֹ בֵּן בָּעוֹלָם הַזֶּה נִקְרָא עֲרִירִי, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כ) עֲרִירִים יִהְיוּ. וְאַבְרָהָם, עַל מָה אָמַר הַדָּבָר הַזֶּה שֶׁאָמַר מַה תִּתֶּן לִי? כִּבְיָכוֹל לֹא הֶאֱמִין בַּקָּדוֹשׁ- בָּרוּךְ-הוּא?</p>\n<p>אֶלָּא אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אָנֹכִי מָגֵן לָךְ - בָּעוֹלָם הַזֶּה, שְׂכָרְךְ הַרְבֵּה מְאֹד - בָּעוֹלָם הַבָּא. מִיָּד הִתְעוֹרֵר אַבְרָהָם בְּסוֹד הַחָכְמָה וְאָמַר מַה תִּתֶּן לִי, שֶׁהֲרֵי יָדַעְתִּי שֶׁלֹּא מְקַבֵּל שָׂכָר לְהִכָּנֵס לָעוֹלָם הַהוּא אָדָם שֶׁלֹּא מוֹלִיד בֵּן. וְעַל זֶה אָמַר מַה תִּתֶּן לִי וְאָנֹכִי הֹלֵךְ עֲרִירִי. שֶׁהֲרֵי לֹא תִתֵּן לִי, שֶׁלֹּא זָכִיתִי בוֹ. מִכָּאן שֶׁאָדָם שֶׁלֹּא זוֹכֶה בְּבָנִים בָּעוֹלָם הַזֶּה, לֹא זוֹכֶה בָּעוֹלָם הַהוּא לְהִכָּנֵס לְתוֹךְ הַפַּרְגּוֹד.</p>\n<p>וְאַבְרָהָם הָיָה רוֹאֶה בָּאִצְטַגְנִינוּת שֶׁלּוֹ שֶׁלֹּא יוֹלִיד. מַה כָּתוּב? וַיּוֹצֵא אֹתוֹ הַחוּצָה וְגוֹ'. (אמר לו הקדוש ברוך הוא, צא מאצטגנינות שלך, אברם אינו מוליד, אברהם מוליד) אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַל תִּסְתַּכֵּל בָּזֶה, אֶלָּא בַּסּוֹד שֶׁל שְׁמִי יִהְיֶה לְךְ בֵּן. זֶהוּ שֶׁכָּתוּב כֹּה יִהְיֶה זַרְעֶךְ. הַסּוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁמִּשָּׁם נִקְשַׁר לוֹ עִם זֶה (בן) וְלֹא מֵהַצַּד הָאַחֵר.</p>\n<p>כֹּה - שֶׁהוּא הַשַּׁעַר לַתְּפִלָּה, בָּהּ יִמְצָא בְרָכָה, בָּהּ יִמְצָא אָדָם אֶת בַּקָּשָׁתוֹ. כֹּה - אוֹתוֹ הַצַּד שֶׁבָּא מִצַּד הַגְּבוּרָה, שֶׁהֲרֵי מִצַּד הַגְּבוּרָה בָּא יִצְחָק. וְאוֹתוֹ צַד הַגְּבוּרָה נִקְרָא כֹּ\"ה, שֶׁמִּשָּׁם בָּאִים פֵּרוֹת וּפֵרוֹת לָעוֹלָם, וְלֹא מֵהַצַּד שֶׁלְּמַטָּה שֶׁל כּוֹכָבִים וּמַזָּלוֹת.</p>\n<p>אָז והִאִמן בַּה'. נִדְבַּק לְמַעְלָה וְלֹא נִדְבַּק לְמַטָּה. וְהֶאֱמִן בַּה', וְלֹא בְכוֹכָבִים וּמַזָּלוֹת. וְהֶאֱמִן בַּה' - שֶׁהִבְטִיחַ לוֹ שֶׁיַּרְבֶּה אֶת שְׂכָרוֹ לָעוֹלָם הַבָּא. וְהֶאֱמִן בַּה' - בְּאוֹתָהּ הַדַּרְגָּה שֶׁנִּתְּנָה לוֹ, שֶׁמִּשָּׁם יָבא לוֹ זֶרַע לְהוֹלִיד בָּעוֹלָם.</p>\n<p>וַיַּחְשְׁבֶהָ לּוֹ צְדָקָה. וַיַּחְשְׁבֶהָ לּוֹ - שֶׁאַף עַל גַּב שֶׁהִיא דִין, כְּאִלּוּ הִיא רַחֲמִים הַ\"כֹּה\" הַזֹּאת. דָּבָר אַחֵר וַיַּחְשְׁבֶהָ לּוֹ צְדָקָה - שֶׁקָּשַׁר קֶשֶׁר עֶלְיוֹן בַּתַּחְתּוֹן לְחַבְּרָם יַחַד.</p>\n<p>בֹּא רְאֵה, הִנֵּה הֵעִירוּ, אַבְרָהָם מוֹלִיד - אַבְרָם אֵינוֹ מוֹלִיד. וְכִי תֹאמַר שֶׁהִנֵּה הוֹלִיד אֶת יִשְׁמָעֵאל בְּעוֹדוֹ אַבְרָם? אֶלָּא הַבֵּן הַהוּא שֶׁהִבְטִיחַ לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא הוֹלִיד אוֹתוֹ בְּעוֹדוֹ אַבְרָם, שֶׁהֲרֵי בְּעוֹדוֹ אַבְרָם הוֹלִיד לְמַטָּה. כֵּיוָן שֶׁנִּקְרָא אַבְרָהָם וְנִכְנַס בַּבְּרִית, אָז הוֹלִיד לְמַעְלָה. וּמִשּׁוּם כָּךְ אַבְרָם אֵינוֹ מוֹלִיד בְּקֶשֶׁר עֶלְיוֹן, אַבְרָהָם מוֹלִיד כְּמוֹ שֶׁאָמַרְנוּ, וְנִקְשָׁר לְמַעְלָה בְּיִצְחָק.</p>"],[9522011210,"<p>וַיְהִי אַבְרָם בֶּן תִּשְׁעִים שָׁנָה וְתֵשַׁע שָׁנִים וְגוֹ'. רַבִּי אַבָּא פָּתַח, (שמואל ב כב) כִּי מִי אֵל מִבַּלְעֲדֵי ה' וּמִי צוּר וְגוֹ'. דָּוִד הַמֶּלֶךְ אָמַר אֶת הַפָּסוּק הַזֶּה, כִּי מִי אֵל מִבַּלְעֲדֵי ה' - מִי הוּא הַשַּׁלִּיט אוֹ הַמְמֻנֶּה שֶׁיָּכוֹל לַעֲשׂוֹת דָּבָר מִבַּלְעֲדֵי ה'? אֶלָּא מִי שֶׁהִצְטַוָּה מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁכֻּלָּם אֵין עוֹמְדִים בִּרְשׁוּתָם וְלֹא יְכוֹלִים לַעֲשׂוֹת דָּבָר. וּמִי צוּר - וּמִי הוּא הַתַּקִּיף שֶׁיָּכוֹל לַעֲשׂוֹת תֹּקֶף וּגְבוּרָה מֵעַצְמוֹ מִבַּלְעֲדֵי אֱלֹהֵינוּ? אֶלָּא כֻּלָּם בְּיַד הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא יָכוֹל לַעֲשׂוֹת דָּבָר, רַק מֵרְשׁוּתוֹ.</p>\n<p>דָּבָר אַחֵר כִּי מִי אֵל מִבַּלְעֲדֵי ה' - שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הַכֹּל בִּרְשׁוּתוֹ, וְלֹא כְּמִי שֶׁנִּרְאֶה בְּמַרְאֵה הַכּוֹכָבִים וְהַמַּזָּלוֹת, שֶׁכֻּלָּם מַרְאִים דָּבָר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲלִיפוֹ לְגָוֶן אַחֵר. וּמִי צוּר זוּלָתִי אֱלֹהֵינוּ, הֲרֵי פֵּרְשׁוּהָ שֶׁאֵין צַיָּר כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא צַיָּר שָׁלֵם, עוֹשֶׂה וּמְצַיֵּר דְּמוּת בְּתוֹךְ דְּמוּת, וּמַשְׁלִים אֶת אוֹתָהּ הַדְּמוּת בְּכָל תִּקּוּנָהּ, וּמַכְנִיס בּוֹ נֶפֶשׁ עֶלְיוֹנָה, שֶׁדּוֹמֶה לַתִּקּוּן הָעֶלְיוֹן, מִשּׁוּם כָּךְ אֵין צַיָּר כְּמוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בֹּא רְאֵה, מֵאוֹתוֹ הַזֶּרַע שֶׁל אָדָם, כְּשֶׁמִּתְעוֹרֶרֶת תְּשׁוּקָתוֹ לִנְקֵבָתוֹ, וּנְקֵבָתוֹ מִתְעוֹרֶרֶת אֵלָיו, אָז מִתְחַבְּרִים שְׁנֵיהֶם יַחַד, וְיוֹצֵא מֵהֶם בֵּן אֶחָד שֶׁכָּלוּל מִשְּׁתֵּי דְמֻיּוֹת כְּאֶחָד, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא צִיֵּר אוֹתוֹ בְּצִיּוּר שֶׁנִּכְלָל מִשְּׁנֵיהֶם. וְעַל כֵּן צָרִיךְ אָדָם לְקַדֵּשׁ אֶת עַצְמוֹ בַּזְּמַן הַהוּא, כְּדֵי שֶׁיִּמָּצֵא הַדְּמוּת הַהִיא בְּצִיּוּר שָׁלֵם כָּרָאוּי.</p>\n<p>אָמַר רַבִּי חִיָּיא, בּא רְאֵה, כַּמָּה גְּדוֹלִים הֵם מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי הָאֻמָּנוּת וְהַצִּיּוּר שֶׁל הָאָדָם הִיא כְּמוֹ הָעוֹלָם, וּבְכָל יוֹם וָיוֹם הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹרֵא עוֹלָמוֹת, וּמְזַוֵּג זִוּוּגִים כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, וְהוּא צִיֵּר אֶת דְּמוּתָם טֶרֶם בּוֹאָם לָעוֹלָם.</p>\n<p>בֹּא רְאֵה, שֶׁאָמַר רַבִּי שִׁמְעוֹן, כָּתוּב זֶה סֵפֶר תּוֹלְדת אָדָם, וְכִי סֵפֶר הָיָה לוֹ? אֶלָּא פֵּרְשׁוּהָ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לְאָדָם הָרִאשׁוֹן דּוֹר דּוֹר וְדוֹרְשָׁיו וְכוּ'. אֵיךְ הֶרְאָה לוֹ? אִם תֹּאמַר שֶׁרָאָה בְּרוּחַ הַקֹּדֶשׁ שֶׁהֵם עֲתִידִים לָבֹא לָעוֹלָם כְּמִי שֶׁרוֹאֶה בְּחָכְמָה מַה יָּבֹא לָעוֹלָם - לֹא כָּךְ, אֶלָּא רָאָה בְּעַיִן אֶת כֻּלָּם, וְאוֹתָהּ הַדְּמוּת שֶׁעֲתִידִים לַעֲמֹד בָּהּ בָּעוֹלָם, אֶת כֻּלָּם הוּא רָאָה בְּעַיִן. מָה הַטַּעַם? מִשּׁוּם שֶׁמִּיּוֹם שֶׁנִּבְרָא הָעוֹלָם, כָּל הַנְּפָשׁוֹת הָעֲתִידוֹת לַעֲמֹד בִּבְנֵי הָאָדָם, כֻּלָּן עוֹמְדוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָהּ הַדְּמוּת מַמָּשׁ שֶׁעֲתִידוֹת לַעֲמֹד בָּהּ בָּעוֹלָם.</p>\n<p>כְּמוֹ כֵן כָּל אוֹתָם הַצַּדִּיקִים, אַחַר שֶׁיּוֹצְאִים מִן הָעוֹלָם הַזֶּה, כָּל הַנְּפָשׁוֹת עוֹלוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְזַמֵּן לָהֶם דְּמוּת אַחֶרֶת לְהִתְלַבֵּשׁ בָּהּ כְּמוֹ שֶׁהָיוּ בָּעוֹלָם הַזֶּה. מִשּׁוּם כָּךְ כֻּלָּם עוֹמְדִים לְפָנָיו, וְרָאָה אוֹתָם אָדָם הָרִאשׁוֹן בְּעַיִן.</p>\n<p>וְאִם תֹּאמַר, שֶׁאַחַר שֶׁרָאָה אוֹתָם לֹא עָמְדוּ בְקִיּוּמָם - בֹּא וְתִרְאֶה, כָּל דִּבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם בְּקִיּוּם וְעוֹמְדִים לְפָנָיו עַד שֶׁיּוֹרְדִים לָעוֹלָם. כְּמוֹ זֶה כָּתוּב (דברים כט) כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה וְגוֹ'. הֲרֵי פֵּרְשׁוּהָ, שֶׁכָּל בְּנֵי הָאָדָם שֶׁעֲתִידִים לִהְיוֹת בָּעוֹלָם, כֻּלָּם נִמְצְאוּ שָׁם.</p>\n<p>כָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁהֲרֵי כָּתוּב אֶת אֲשֶׁר אֵינֶנּוּ פֹּה וְגוֹ', וּמַשְׁמָע אֵלּוּ (כלם) שֶׁיָּצְאוּ מֵאוֹתָם שֶׁעָמְדוּ שָׁם, מִשּׁוּם שֶׁכָּתוּב עִמָּנוּ הַיּוֹם, וְלֹא כָתוּב עִמָּנוּ עוֹמֵד הַיּוֹם. אֶלָּא וַדַּאי (כאן) כֻּלָּם עָמְדוּ שָׁם, אֶלָּא שֶׁלֹּא נִרְאוּ לָעַיִן, מִשּׁוּם כָּךְ כָּתוּב עִמָּנוּ הַיּוֹם אַף עַל גַּב שֶׁלֹּא נִרְאוּ.</p>\n<p>וְאִם תֹּאמַר, מָה הַטַּעַם לֹא נִרְאוּ כָּאן כְּמוֹ שֶׁנִּרְאוּ לְאָדָם הָרִאשׁוֹן שֶׁרָאָה אוֹתָם עַיִן בְּעַיִן, וַהֲרֵי כָּאן רָאוּ יוֹתֵר? אֶלָּא כָּאן, כְּשֶׁנִּתְּנָה תוֹרָה לְיִשְׂרָאֵל, מַרְאֶה אַחֵר וּדְרָגוֹת עֶלְיוֹנוֹת. הָיוּ רוֹאִים וּמִסְתַּכְּלִים עַיִן בְּעַיִן, וְהָיוּ מִשְׁתּוֹקְקִים לְהִסְתַּכֵּל וְלִרְאוֹת בִּכְבוֹד רִבּוֹנָם, וּמִשּׁוּם כָּךְ רָאוּ אֶת הַכָּבוֹד הָעֶלְיוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ וְלֹא מֵאַחֵר.</p>\n<p>וְעַל כֵּן, כָּל בְּנֵי הָאָדָם שֶׁעֲתִידִים לַעֲמֹד בָּעוֹלָם, כֻּלָּם עוֹמְדִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָן הַדְּמֻיּוֹת מַמָּשׁ שֶׁעֲתִידִים לַעֲמֹד בָּהֶן. זֶהוּ שֶׁכָּתוּב (תהלים קלט) גָּלְמִי רָאוּ עֵינֶיךְ וְעַל סִפְרְךְ וְגוֹ'. גָּלְמִי רָאוּ עֵינֶיךְ, מָה הַטַּעַם? מִשּׁוּם שֶׁדְּמוּת אַחֶרֶת עֶלְיוֹנָה הָיְתָה כָּזֶה, וּמִשּׁוּם כָּךְ כָּתוּב (שם יח) וּמִי צוּר זוּלָתִי אֱלֹהֵינוּ, מִי הַצַּיָּר הַטּוֹב שֶׁצִּיֵּר (שכולל) הַכֹּל (זה עם זה) כְּמוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא?</p>\n<p>דָּבָר אַחֵר כִּי מִי אֱלוֹהַּ - זֶה סוֹד הַדָּבָר, שֶׁהֲרֵי אֵל הוּא כְּלָל שֶׁנִּכְלָל מִכָּל הַדְּרָגוֹת. וְאִם תֹּאמַר שֶׁאֵל הַזֶּה הִיא דַּרְגָּה אַחֶרֶת, מִשּׁוּם שֶׁכָּתוּב (שם ז) וְאֵל זעֵם בְּכָל יוֹם? בֹּא רְאֵה, שֶׁהֲרֵי אֵין אֵל מִבַּלְעֲדֵי ה' שֶׁאֵינוֹ לְבַדּוֹ, וְלֹא נִפְרָד לְעוֹלָמִים, וְעַל כֵּן כָּתוּב (שמואל ב כב) כִּי מִי אֵל מִבַּלְעֲדֵי ה' וְגוֹ'. וּמִי צוּר וְגוֹ', שֶׁהֲרֵי צוּר אֵינוֹ לְבַדּוֹ, אֶלָּא הַכֹּל אֶחָד, כַּכָּתוּב (דברים ד) וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבתָ אֶל לְבָבֶךְ כִּי ה' הוּא הָאֱלֹהִים וְגוֹ'.</p>"],[9522011211,"<p>בֹּא רְאֵה, שֶׁטֶּרֶם שֶׁנִּמּוֹל אַבְרָהָם, הָיָה מְדַבֵּר עִמּוֹ מִתּוֹךְ מַחֲזֶה לְבַדּוֹ, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב הָיָה דְבַר ה' אֶל אַבְרָם בַּמַּחֲזֶה וְגוֹ'. בַּמַּחֲזֶה - בְּאוֹתוֹ הַמַּרְאֶה, הַדַּרְגָּה שֶׁכָּל הַדְּמֻיּוֹת נִרְאוֹת בָּהּ, כְּמוֹ שֶׁנֶּאֱמַר. וְהַמַּחֲזֶה הַזֶּה הוּא סוֹד הַבְּרִית.</p>\n<p>וְאִם תֹּאמַר שֶׁמִּשּׁוּם כָּךְ נִקְרָא מַחֲזֶה, מִשּׁוּם שֶׁהִיא הַדַּרְגָּה הַמַּרְאֶה שֶׁכָּל הַדְּמֻיּוֹת נִרְאוֹת בָּהּ וְאָז נִקְרֵאת מַחֲזֶה - הֲרֵי אָמַרְתָּ בָּרִאשׁוֹנָה, שֶׁטֶּרֶם שֶׁנִּמּוֹל אַבְרָהָם, לֹא הָיָה מְדַבֵּר עִמּוֹ, רַק הַדַּרְגָּה הַזּוֹ שֶׁאֵין שׁוֹרִים עָלֶיהָ הַדְּרָגוֹת הָאֲחֵרוֹת, וְעַכְשָׁו אָמַרְתָּ בַּמַּחֲזֶה - הַמַּרְאֶה שֶׁל כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת הוּא, וַהֲרֵי טֶרֶם שֶׁנִּמּוֹל כָּתוּב הָיָה דְבַר ה' אֶל אַבְרָם בַּמַּחֲזֶה?</p>\n<p>אֶלָּא הַדַּרְגָּה הַזּוֹ הִיא הַמַּרְאֶה שֶׁל כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת, וּבַמַּרְאֶה שֶׁל הַדְּרָגוֹת הָעֶלְיוֹנוֹת נִתְקְנָה. וְאַף עַל גַּב שֶׁבְּאוֹתוֹ הַזְּמַן אַבְרָהָם לֹא הָיָה מָהוּל - הַדַּרְגָּה הַזּוֹ בַּמַּרְאֶה שֶׁל הַדְּרָגוֹת הָעֶלְיוֹנוֹת הִיא, וּבְכָל אוֹתָם הַגְּוָנִים עוֹמֶדֶת, וְהַמַּרְאֶה שֶׁל אוֹתָם הַגְּוָנִים עוֹמֵד תַּחְתֶּיהָ. אֶחָד מִיָּמִין - גָּוֶן לָבָן, וְאֶחָד מִשְּׂמֹאל - גָּוֶן אָדם, אֶחָד שֶׁכָּלוּל מִכָּל הַגְּוָנִים. וְהוּא הַמַּרְאֶה שֶׁכָּל הַגְּוָנִים הָעֶלְיוֹנִים עוֹמְדִים עָלָיו. וְעַל זֶה בַּמַּרְאֶה הַזֶּה עָמַד עַל אַבְרָהָם וְדִבֵּר עִמּוֹ, וְאַף עַל גַּב שֶׁלֹּא נִמּוֹל. כֵּיוָן שֶׁנִּמּוֹל מַה כָּתוּב? וַיֵּרָא ה' אֶל אַבְרָם.</p>\n<p>בֹּא רְאֵה, בְּבִלְעָם (אמר) כָּתוּב מַחֲזֵה שַׁדַּי, וּבְאַבְרָהָם כָּתוּב מַחֲזֶה סְתָם. מַה בֵּין זֶה לָזֶה? אֶלָּא מַחֲזֵה שַׁדַּי אֵלּוּ שֶׁלְּמַטָּה (שיצאו) מִמֶּנּוּ, וְהֵם הַמַּרְאֶה שֶׁלּוֹ. מַחֲזֶה סְתָם, מַחֲזֶה זֶה הוּא ה' (של כל מראה) שֶׁכָּל הַדְּמֻיּוֹת הָעֶלְיוֹנוֹת נִרְאוֹת בּוֹ. וּמִשּׁוּם כָּךְ כָּתוּב בְּאַבְרָהָם מַחֲזֶה סְתָם, וּבְבִלְעָם מַחֲזֵה שַׁדַּי.</p>\n<p>וְעַל כֵּן, טֶרֶם שֶׁנִּמּוֹל אַבְרָהָם, הָיְתָה לוֹ הַדַּרְגָּה הַזּוֹ כְּפִי שֶׁאָמַרְנוּ. כֵּיוָן שֶׁנִּמּוֹל, מִיָּד וַיֵּרָא אֵלָיו ה' וְגוֹ'. נִרְאוּ כָּל (שאר) הַדְּרָגוֹת עַל הַדַּרְגָּה הַזּוֹ, וְהַדַּרְגָּה הַזּוֹ דִּבְּרָה עִמּוֹ כָּרָאוּי בִּשְׁלֵמוּת. וְאַבְרָהָם נִקְשַׁר מִדַּרְגָּה לְדַרְגָּה, וְנִכְנַס לִבְרִית הַקֹּדֶשׁ כָּרָאוּי בִּשְׁלֵמוּת.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁנִּמּוֹל אַבְרָהָם, יָצָא מֵהָעָרְלָה, וְנִכְנַס לַבְּרִית הַקְּדוֹשָׁה, וְהִתְעַטֵּר בַּעֲטָרָה קְדוֹשָׁה, וְנִכְנַס בַּבְּרִית שֶׁהָעוֹלָם עוֹמֵד עָלֶיהָ, וְאָז הִתְקַיֵּם הָעוֹלָם בִּגְלָלוֹ, מִשּׁוּם שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי, וְכָתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּהֵ\"א בְּרָאָם, בְּאַבְרָהָם, וְהַכֹּל עוֹמֵד בְּסוֹד אֶחָד. וּבְשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לָאָדָם אֶת כָּל אוֹתָם הַדּוֹרוֹת שֶׁל הָעוֹלָם, וְרָאָה אוֹתָם כָּל אֶחָד וְאֶחָד, כָּל דּוֹר וָדוֹר, כֻּלָּם עוֹמְדִים בְּגַן הָעֵדֶן בְּאוֹתָהּ הַדְּמוּת שֶׁעֲתִידִים לַעֲמֹד בָּהּ בָּעוֹלָם הַזֶּה.</p>\n<p>וּבֹא וּרְאֵה, הֲרֵי נִתְבָּאֵר, כֵּיוָן שֶׁרָאָה אֶת דָּוִד שֶׁאֵין בּוֹ חַיִּים כְּלָל, תָּמַהּ, וְהוּא נָתַן לוֹ מִשֶּׁלּוֹ שִׁבְעִים שָׁנִים. מִשּׁוּם כָּךְ הָיוּ לוֹ לְאָדָם תְּשַׁע מֵאוֹת וּשְׁלֹשִׁים שָׁנִים, וְאוֹתָם הַשִּׁבְעִים עָלוּ לוֹ לְדָוִד.</p>\n<p>וְהַדָּבָר הַזֶּה הוּא סוֹד שֶׁל חָכְמָה, שֶׁלְּדָוִד אֵין (ימים) פְּרָט לְשִׁבְעִים הַשָּׁנִים מֵאָדָם הָרִאשׁוֹן. וְהַכֹּל הוּא סוֹד שֶׁל חָכְמָה. וְכָל מַה שֶּׁלְּמַטָּה, הַכֹּל הוּא בַּסּוֹד שֶׁל מַעְלָה.</p>"],[9522011212,"<p>וּבֹא וּרְאֵה, בְּכָל אוֹתָן הַדְּמֻיּוֹת שֶׁל הַנְּשָׁמוֹת שֶׁל הָעוֹלָם, כֻּלָּם לְפָנָיו זוּגוֹת זוּגוֹת. לְאַחַר מִכֵּן, כְּשֶׁבָּאִים לָעוֹלָם הַזֶּה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְזַוֵּג זִוּוּגִים. אָמַר רַבִּי (יהודה) יִצְחָק, הַקָּדוֹשׁ בָּרוּךְ הוּא (מזוג זווגים ואומר) אוֹמֵר בַּת פְּלוֹנִי לִפְלוֹנִי. אָמַר רַבִּי יוֹסֵי, מַה זֶּה אוֹמֵר, וַהֲרֵי כָּתוּב (קהלת א) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ? אָמַר רַבִּי יְהוּדָה, תַּחַת הַשָּׁמֶשׁ כָּתוּב, שׁוֹנֶה לְמַעְלָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מַה כָּאן הַכְּרוּז, וַהֲרֵי אָמַר רַבִּי חִזְקִיָּה אָמַר רַבִּי חִיָּיא, בְּאוֹתָהּ שָׁעָה מַמָּשׁ שֶׁיּוֹצֵא אָדָם לָעוֹלָם, בַּת זוּגוֹ מְזֻמֶּנֶת לוֹ?</p>\n<p>אָמַר רַבִּי אַבָּא, אַשְׁרֵי הַצַּדִּיקִים שֶׁנִּשְׁמוֹתֵיהֶם מִתְעַטְּרוֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ טֶרֶם יָבֹאוּ לָעוֹלָם. שֶׁכָּךְ שָׁנִינוּ, בַּשָּׁעָה הַהִיא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִיא נְשָׁמוֹת לָעוֹלָם, כָּל אוֹתָן הָרוּחוֹת וְהַנְּשָׁמוֹת, כֻּלָּן כְּלוּלוֹת זָכָר וּנְקֵבָה שֶׁמְּחֻבָּרוֹת יַחַד.</p>\n<p>וְנִמְסָרוֹת בִּידֵי אוֹתוֹ הַמְמֻנֶּה הַשָּׁלִיחַ שֶׁנִּתְמַנָּה עַל הֶרְיוֹנוֹת בְּנֵי הָאָדָם, וּשְׁמוֹ לַיְלָה. וּבְשָׁעָה שֶׁיּוֹרְדוֹת וְנִמְסָרוֹת בְּיָדָיו, נִפְרָדוֹת, וְלִפְעָמִים זֶה מַקְדִּים לִפְנֵי זֶה, וּמוֹרִיד אוֹתָם בִּבְנֵי הָאָדָם.</p>\n<p>וּכְשֶׁמַּגִּיעַ (מכה) זְמַן זִוּוּגָם, הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁמַּכִּיר אוֹתָן הָרוּחוֹת וְהַנְּשָׁמוֹת מְחַבֵּר אוֹתָן כְּבָרִאשׁוֹנָה וּמַכְרִיז עֲלֵיהֶם. וּכְשֶׁמִּתְחַבְּרִים, נַעֲשִׂים גּוּף אֶחָד וּנְשָׁמָה אַחַת, יָמִין וּשְׂמֹאל כָּרָאוּי, וּמִשּׁוּם כָּךְ אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי שָׁנִינוּ שֶׁאֵין זִוּוּג אֶלָּא לְפִי מַעֲשֵׂי וְדַרְכֵי הָאָדָם - כָּךְ זֶה וַדַּאי! שֶׁאִם זוֹכֶה וּמַעֲשָׂיו כְּשֵׁרִים, הוּא זוֹכֶה לְהִתְחַבֵּר עִם אוֹתוֹ שֶׁלּוֹ כְּמוֹ שֶׁיָּצָא.</p>\n<p>אָמַר רַבִּי חִיָּיא, מִי שֶׁמַּעֲשָׂיו כְּשֵׁרִים, בְּאֵיזֶה מָקוֹם יְבַקֵּשׁ (יושב) אֶת זִוּוּגוֹ? אָמַר לוֹ, הֲרֵי שָׁנִינוּ, לְעוֹלָם יִמְכֹּר אָדָם וְכוּ' וְיִשָּׂא בַּת תַּלְמִיד חָכָם, (ד\"א ובא ראה) שֶׁתַּלְמִיד חָכָם פִּקְדוֹן רִבּוֹנוֹ נִפְקָד בְּיָדוֹ.</p>\n<p>שָׁנִינוּ בְּסוֹד הַמִּשְׁנָה, כָּל אוֹתָם שֶׁבָּאוּ בְּגִלְגּוּל שֶׁל נְשָׁמוֹת, יְכוֹלִים לְהַקְדִּים בְּרַחֲמִים אֶת זִוּוּגָם. וְעַל זֶה הֵעִירוּ הַחֲכָמִים, אֵין נוֹשְׂאִים נָשִׁים בַּמּוֹעֵד, אֲבָל מְקַדְּשִׁים, שֶׁמָּא יְקַדְּמֶנּוּ אַחֵר בְּרַחֲמִים. וְיָפֶה אָמְרוּ אַחֵר בְּדִיּוּק. וְעַל כֵּן קָשִׁים הַזִּוּוּגִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעַל כָּל פָּנִים וַדַּאי כָּתוּב כִּי יְשָׁרִים דַּרְכֵי ה'.</p>\n<p>רַבִּי יְהוּדָה שָׁלַח לְרַבִּי אֶלְעָזָר. אָמַר, הֲרֵי סוֹד הַדָּבָר יָדַעְתִּי, אוֹתָם שֶׁבָּאוּ בְּגִלְגּוּל נְשָׁמוֹת - מֵאֵיזֶה מָקוֹם לָהֶם יֵשׁ זִוּוּג? שָׁלַח לוֹ, כָּתוּב (שופטים כא) מַה נַּעֲשֶׂה לָהֶם לַנּוֹתָרִים לְנָשִׁים וְגוֹ'. וְכָתוּב וַחֲטַפְתֶּם לָכֶם וְגוֹ'. פָּרָשַׁת בְּנֵי בִנְיָמִין מוֹכִיחָה, וְעַל זֶה שָׁנִינוּ שֶׁמָּא יְקַדְּמֶנּוּ אַחֵר בְּרַחֲמִים. (וכי אותו אחר אין לו בת זוגו? אבל תמצא זה כמו אדם שנשא בת זוגו ולא היו לו ממנה בנים ומת, יבא אחיו וייבם את אשתו ויולד לו ממנה בן, הבן הזה הוא המת שנשמתו חזרה לעולם, זה הוא האחר שאין לו בת זוג אלא אמו, וזה הוא שמא יקדמנו אחר ברחמים, שיכול להקדים אחר לשא את אשתו של זה ברחמים ובתפלה, ואף על גב שאמרתי לך שיכולים להקדים אחר ברחמים, לא יכול אלא אם (הוא) בעלה הוא רשע והוא צדיק).</p>\n<p>אָמַר רַבִּי יְהוּדָה, (כעת) זֶה הוּא וַדַּאי שֶׁקָּשִׁים הַזִּוּוּגִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַתּוֹרָה מְלַמֶּדֶת אוֹתָם אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל הַנִּסְתָּרוֹת וְהַגְּנָזִים שֶׁגְּנוּזִים לְפָנָיו.</p>\n<p>וַדַּאי כָּתוּב (תהלים יט) תּוֹרַת ה' תְּמִימָה וְגוֹ'. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וְלֹא נִפְרָד מִמֶּנָּה, שֶׁכָּל מִי שֶׁנִּפְרָד מִן הַתּוֹרָה אֲפִלּוּ שָׁעָה אַחַת, כְּמִי שֶׁנִּפְרָד מֵחַיֵּי הָעוֹלָם, שֶׁכָּתוּב (דברים ל) כִּי הִיא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ, וְכָתוּב (משלי ג) אֹרֶךְ יָמִים וּשְׁנוֹת חַיִּים וְשָׁלוֹם יוֹסִיפוּ לָךְ.</p>"],[9522011213,"<p>וַיְהִי אַבְרָם בֶּן תִּשְׁעִים שָׁנָה וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ וְגוֹ'. אַשְׁרֵיהֶם יִשְׂרָאֵל מִכָּל שְׁאָר הָעַמִּים, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לָהֶם צַדִּיקִים. שֶׁלָּמַדְנוּ, מֵאָה וְעֶשְׂרִים (וחמש) וּשְׁמוֹנָה אֲלָפִים בַּעֲלֵי כְנָפַיִם שֶׁהוֹלְכִים וְטָסִים אֶת כָּל הָעוֹלָם, וְשׁוֹמְעִים קוֹל וְאוֹחֲזִים אֶת אוֹתוֹ הַקּוֹל.</p>\n<p>כְּמוֹ שֶׁשָּׁנִינוּ שֶׁאֵין לְךְ דָּבָר בָּעוֹלָם שֶׁאֵין לוֹ קוֹל וְהוֹלֵךְ וְטָס בָּרָקִיעַ. וְאוֹחֲזִים בּוֹ בַּעֲלֵי כְנָפַיִם, וּמַעֲלִים אֶת אוֹתוֹ הַקּוֹל (לרבונם) שֶׁאוֹמְרִים (בעלי הדין) וְדָנִים אוֹתוֹ הֵן לְטוֹב הֵן לְרַע, שֶׁכָּתוּב (קהלת י) כִּי עוֹף הַשָּׁמַיִם יֹלִיךְ אֶת הַקּוֹל וְגוֹ'.</p>\n<p>מָתַי דָּנִים אֶת אוֹתוֹ הַקּוֹל? רַבִּי חִיָּיא אָמַר, בְּשָׁעָה שֶׁבֶּן אָדָם שׁוֹכֵב וְיָשֵׁן וְנִשְׁמָתוֹ יָצְאָה מִמֶּנּוּ, וְהִיא מְעִידָה בְּבֶן הָאָדָם, וְאָז דָּנִים אֶת אוֹתוֹ הַקּוֹל. זֶהוּ שֶׁכָּתוּב (מיכה ז) מִשֹּׁכֶבֶת חֵיקֶךְ שְׁמֹר פִּתְחֵי פִיךְ. מָה הַטַּעַם? מִשּׁוּם שֶׁהִיא מְעִידָה בָּאָדָם. רַבִּי יְהוּדָה אוֹמֵר, כָּל מַה שֶּׁאָדָם עוֹשֶׂה בְּכָל יוֹם, נִשְׁמָתוֹ מְעִידָה בּוֹ בָּאָדָם בַּלַּיְלָה.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי אֶלְעָזָר, בִּתְחִלַּת הַשָּׁעָה הָרִאשׁוֹנָה בַּלַּיְלָה, כְּשֶׁנּוֹשֵׁף (שיוצא) הַיּוֹם וְנִכְנָס הַשֶּׁמֶשׁ, בַּעַל הַמַּפְתְּחוֹת שֶׁמְּמֻנֶּה עַל הַשֶּׁמֶשׁ נִכְנָס בִּתְרֵיסַר שְׁעָרִים שֶׁפְּתוּחִים בַּיּוֹם. אַחַר שֶׁנִּכְנַס בְּכֻלָּם, כָּל אוֹתָם הַשְּׁעָרִים הַסְּתוּמִים (הפתוחים),</p>\n<p>הַכָּרוֹז עוֹמֵד וּמַתְחִיל לְהַכְרִיז. עוֹמֵד מִי שֶׁעוֹמֵד וְאוֹחֵז אֶת אוֹתָם הַמַּפְתְּחוֹת. אַחַר שֶׁסִּיֵּם הַכָּרוֹז, כָּל אוֹתָם שׁוֹמְרֵי הָעוֹלָם מִתְכַּנְּסִים וְעוֹלִים, וְאֵין מִי שֶׁפּוֹתֵחַ (פה) פִּתְחוֹן פֶּה וְהַכֹּל שׁוֹקְטִים. אָז מִתְעוֹרְרִים הַדִּינִים שֶׁלְּמַטָּה, וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם, וְהַלְּבָנָה מַתְחִילָה לְהָאִיר.</p>\n<p>וּבַעָלֵי הַיְבָבָה תּוֹקְעִים וּמְיַלְּלִים. תּוֹקְעִים שֵׁנִית. אָז מִתְעוֹרֶרֶת שִׁירָה וּמְזַמְּרִים לִפְנֵי רִבּוֹנָם. כַּמָּה בַּעֲלֵי מָגִנִּים עוֹמְדִים בִּמְקוֹמָם וּמְעוֹרְרִים דִּינִים בָּעוֹלָם. אָז בְּנֵי הָאָדָם יְשֵׁנִים, וְהַנְּשָׁמָה יוֹצֵאת וּמְעִידָה עֵדוּת וּמִתְחַיֶּבֶת בַּדִּין. וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה חֶסֶד עִם אָדָם, וְהַנְּשָׁמָה שָׁבָה לִמְקוֹמָהּ.</p>\n<p>בַּחֲצוֹת הַלַּיְלָה, כְּשֶׁהַצִּפֳּרִים מִתְעוֹרְרוֹת, צַד הַצָּפוֹן מִתְעוֹרֵר בָּרוּחַ, עוֹמֵד בִּמְקוֹמוֹ הַשַּׁרְבִיט שֶׁבְּצַד הַדָּרוֹם, וּמַכֶּה בְּאוֹתָהּ הָרוּחַ וְשׁוֹקֵט וּמִתְבַּסֵּם. אָז מִתְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִנְהָגָיו לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן.</p>\n<p>בְּאוֹתָהּ שָׁעָה. אַשְׁרֵי חֶלְקוֹ שֶׁל אָדָם שֶׁעוֹמֵד לְהִשְׁתַּעֲשֵׁעַ בַּתּוֹרָה, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן, כֻּלָּם מַקְשִׁיבִים לְקוֹלוֹ. זֶהוּ שֶׁכָּתוּב (שיר ח) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי.</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשֵׁךְ עָלָיו חוּט אֶחָד שֶׁל חֶסֶ\"ד שֶׁיִּהְיֶה (תמיד) שָׁמוּר בָּעוֹלָם, שֶׁהֲרֵי עֶלְיוֹנִים וְתַחְתּוֹנִים שׁוֹמְרִים אוֹתוֹ. זֶהוּ שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי.</p>\n<p>אָמַר רַבִּי חִזְקִיָּה, כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּשָּׁעָה הַזּוֹ בַּתּוֹרָה, וַדַּאי יֵשׁ לוֹ חֵלֶק תָּמִיד בָּעוֹלָם הַבָּא. אָמַר רַבִּי יוֹסֵי, מָה הַטַּעַם תָּמִיד? אָמַר לוֹ, כָּךְ לָמַדְנוּ, שֶׁכָּל חֲצוֹת לַיְלָה, כְּשֶׁמִּתְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַן עֵדֶן, כָּל הַנְּטִיעוֹת שֶׁל הַגָּן מֻשְׁקִים יוֹתֵר מֵאוֹתוֹ הַנַּחַל שֶׁנִּקְרָא נַחַל קְדוּמִים, נַחַל עֲדָנִים, שֶׁאֵין פּוֹסְקִים מֵימָיו לְעוֹלָמִים. כִּבְיָכוֹל אוֹתוֹ שֶׁעוֹמֵד וּמִשְׁתַּדֵּל בַּתּוֹרָה, כְּאִלּוּ אוֹתוֹ הַנַּחַל מוֹרִיק עַל רֹאשׁוֹ וּמַשְׁקֶה אוֹתוֹ בְּתוֹךְ אוֹתָם הַנְּטִיעוֹת שֶׁבְּגַן עֵדֶן.</p>\n<p>(אמר רבי יוסי) וְלֹא עוֹד, אֶלָּא הוֹאִיל וְכָל הַצַּדִּיקִים שֶׁבְּתוֹךְ גַּן הָעֵדֶן מַקְשִׁיבִים לוֹ, שָׂמִים לוֹ חֵלֶק בְּאוֹתָהּ הַשְׁקָאַת הַנַּחַל. נִמְצָא שֶׁיֵּשׁ לוֹ חֵלֶק תָּמִיד בָּעוֹלָם הַבָּא.</p>\n<p>רַבִּי אַבָּא הָיָה בָּא מִטְּבֶרְיָה לְבֵית טְרוֹנְיָא שֶׁלְּחָמִיו, וְרַבִּי יַעֲקֹב בְּנוֹ הָיָה עִמּוֹ. נִפְגְּשׁוּ בִּכְפַר טְרָשָׁא. כְּשֶׁרָצוּ לִשְׁכַּב, אָמַר רַבִּי אַבָּא לְבַעַל הַבַּיִת: יֵשׁ כָּאן תַּרְנְגוֹל? אָמַר לוֹ בַּעַל הַבַּיִת: לָמָּה? אָמַר לוֹ: מִשּׁוּם שֶׁאֲנִי קָם בַּחֲצוֹת הַלַּיְלָה מַמָּשׁ.</p>\n<p>אָמַר לוֹ: לֹא צָרִיךְ, שֶׁהֲרֵי סִימָן יֵשׁ לִי בַּבַּיִת - שֶׁהַמִּשְׁקָל הַזֶּה שֶׁלִּפְנֵי מִטָּתִי, אֲנִי מְמַלֵּא אוֹתוֹ בְּמַיִם, וּמְטַפְטֵף טִפָּה טִפָּה. וּבַחֲצוֹת הַלַּיְלָה מַמָּשׁ מִתְרוֹקְנִים כָּל הַמַּיִם, וּמִתְגַּלְגֵּל הַגַּלְגַּל (הדבוק) הַזֶּה וְנוֹהֵם, וְנִשְׁמָע קוֹלוֹ בְּכָל הַבַּיִת. וְאָז הוּא חֲצוֹת הַלַּיְלָה מַמָּשׁ. וְזָקֵן אֶחָד הָיָה לִי שֶׁהָיָה קָם בְּכָל חֲצוֹת לַיְלָה וּמִשְׁתַּדֵּל בַּתּוֹרָה, וּמִשּׁוּם כָּךְ עָשָׂה אֶת זֶה.</p>\n<p>אָמַר רַבִּי אַבָּא: בָּרוּךְ הָרַחֲמָן שֶׁשְּׁלָחַנִי לְכָאן. בַּחֲצוֹת הַלַּיְלָה נָהַם אוֹתוֹ הַגַּלְגַּל (הדבוק). קָמוּ רַבִּי אַבָּא וְרַבִּי יַעֲקֹב, וְשָׁמְעוּ אֶת אוֹתוֹ הָאִישׁ שֶׁהָיָה יוֹשֵׁב בְּיַרְכְּתֵי הַבַּיִת וּשְׁנֵי בָנָיו עִמּוֹ, וְהָיָה אוֹמֵר, כָּתוּב (תהלים קיט) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ עַל מִשְׁפְּטֵי צִדְקֶךְ. מָה רָאָה דָוִד שֶׁהוּא אָמַר חֲצוֹת לַיְלָה וְלֹא בַּחֲצוֹת הַלַּיְלָה? אֶלָּא חֲצוֹת לַיְלָה - וַדַּאי לַקָּדוֹשׁ- בָּרוּךְ-הוּא אָמַר כָּךְ.</p>\n<p>וְכִי כָּךְ נִקְרָא הַקָּדוֹשׁ בָּרוּךְ הוּא? כֵּן, שֶׁהֲרֵי חֲצוֹת לַיְלָה מַמָּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא וְסִיעָתוֹ, וְאָז הִיא הַשָּׁעָה שֶׁנִּכְנָס לְגַן הָעֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים.</p>\n<p>אָמַר רַבִּי אַבָּא לְרַבִּי יַעֲקֹב, וַדַּאי נִשְׁתַּתֵּף עִם הַשְּׁכִינָה וְנִתְחַבֵּר יַחַד. קָרְבוּ וְיָשְׁבוּ עִמּוֹ. אָמְרוּ לוֹ, אֱמֹר דְּבַר פִּיךְ, שֶׁיָּפֶה אָמַרְתָּ, מִנַּיִן לְךְ זֶה? אָמַר לָהֶם, דָּבָר זֶה לָמַדְתִּי מִסָּבִי.</p>\n<p>וְעוֹד הָיָה אוֹמֵר, שֶׁשְּׁלֹשׁ (שתחלת) הַשָּׁעוֹת הָרִאשׁוֹנוֹת שֶׁל הַלַּיְלָה, כָּל הַדִּינִים שֶׁלְּמַטָּה מִתְעוֹרְרִים וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם. וּבַחֲצוֹת הַלַּיְלָה מַמָּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעוֹרֵר בְּגַן עֵדֶן, וְהַדִּינִים שֶׁלְּמַטָּה אֵין נִמְצָאִים.</p>\n<p>וְכָל הַמִּנְהָגִים שֶׁלְּמַעְלָה בַּלַּיְלָה, אֵין נִמְצָאִים אֶלָּא בַּחֲצוֹת הַלַּיְלָה מַמָּשׁ. מִנַּיִן לָנוּ? מֵאַבְרָהָם, שֶׁכָּתוּב (בראשית יד) וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה. בְּמִצְרַיִם - (שמות יב) וַיְהִי בַּחֲצִי הַלַּיְלָה. וּבִמְקוֹמוֹת רַבִּים בַּתּוֹרָה כָּךְ נִמְצָא. וְדָוִד הָיָה יוֹדֵעַ.</p>\n<p>(ומה) וּמִנַּיִן הָיָה יוֹדֵעַ? אֶלָּא כָּךְ אָמַר הַזָּקֵן, שֶׁמַּלְכוּתוֹ תְּלוּיָה בָּזֶה (הלילה), וְעַל זֶה עוֹמֵד בַּשָּׁעָה הַזּוֹ וְאוֹמֵר שִׁירָה, וְלָכֵן קָרָא לַקָּדוֹשׁ- בָּרוּךְ-הוּא חֲצוֹת לַיְלָה (ממש) אָקוּם לְהוֹדוֹת לָךְ וְגוֹ', שֶׁהֲרֵי כָּל הַדִּינִים תְּלוּיִים מִכָּאן, וְדִינֵי הַמַּלְכוּת נִמְצָאִים מִכָּאן. וּבְאוֹתָהּ הַשָּׁעָה נִקְשַׁר דָּוִד בָּהּ, וְקָם וְאָמַר שִׁירָה. בָּא רַבִּי אַבָּא וּנְשָׁקוֹ. אָמַר לוֹ, וַדַּאי כָּךְ הוּא. בָּרוּךְ הָרַחֲמָן שֶׁשְּׁלָחַנִי לְכָאן.</p>\n<p>בֹּא רְאֵה, הַלַּיְלָה הוּא דִין בְּכָל מָקוֹם, וַהֲרֵי הֵקַמְנוּ אֶת הַדְּבָרִים, וְכָךְ הוּא וַדַּאי, וַהֲרֵי הֵעַרְתִּי לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר אוֹתוֹ הַיֶּלֶד בְּנוֹ שֶׁל אוֹתוֹ הָאִישׁ, אִם כָּךְ, לָמָּה כָּתוּב חֲצוֹת לַיְלָה? אָמַר לוֹ, הֲרֵי נֶאֱמַר שֶׁבַּחֲצוֹת הַלַּיְלָה מִתְעוֹרֶרֶת מַלְכוּת הַשָּׁמַיִם. אָמַר, אֲנִי שָׁמַעְתִּי דָבָר. אָמַר לוֹ רַבִּי אַבָּא, אֱמֹר בְּנִי טוֹב, שֶׁהֲרֵי דְּבַר פִּיךְ יִהְיֶה קוֹל הַמָּאוֹר.</p>\n<p>אָמַר, אֲנִי שָׁמַעְתִּי, שֶׁהֲרֵי הַלַּיְלָה הוּא דִּין הַמַּלְכוּת, וּבְכָל מָקוֹם הוּא דִין. וְזֶה שֶׁאָמַר חֲצוֹת, מִשּׁוּם שֶׁיּוֹנֶקֶת בִּשְׁנֵי גְוָנִים (חצות) - בְּדִין וְחֶסֶד. וּוַדַּאי שֶׁהַמַּחֲצִית הָרִאשׁוֹנָה הִיא דִין, שֶׁהֲרֵי בַּמַּחֲצִית הָאַחֶרֶת הִיא מְאִירָה פָנֶיהָ בְּצַד הַחֶסֶד, וְעַל כֵּן חֲצוֹת לַיְלָה כָּתוּב וַדַּאי.</p>\n<p>קָם רַבִּי אַבָּא וְשָׂם יָדוֹ בְּרֹאשׁוֹ וּבֵרַךְ אוֹתוֹ. אָמַר, וַדַּאי חָשַׁבְתִּי שֶׁאֵין נִמְצֵאת חָכְמָה, רַק בְּאוֹתָם הַצַּדִּיקִים שֶׁזָּכוּ בָהּ. כָּעֵת רָאִיתִי שֶׁאֲפִלּוּ יְלָדִים בַּדּוֹר שֶׁל רַבִּי שִׁמְעוֹן זָכוּ לְחָכְמָה עֶלְיוֹנָה. אַשְׁרֶיךְ רַבִּי שִׁמְעוֹן! אוֹי לַדּוֹר שֶׁאַתָּה תִסְתַּלֵּק מִמֶּנּוּ! יָשְׁבוּ עַד הַבֹּקֶר וְהִתְעַסְּקוּ בַתּוֹרָה.</p>\n<p>פָּתַח רַבִּי אַבָּא וְאָמַר, וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'. הַדָּבָר הַזֶּה הֲרֵי בֵּאֲרוּהוּ הַחֲבֵרִים, מָה הַטַּעַם כָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים, וְכִי כָּל יִשְׂרָאֵל הֵם צַדִּיקִים? וַהֲרֵי כַּמָּה רְשָׁעִים יֵשׁ בְּיִשְׂרָאֵל, כַּמָּה חוֹטְאִים וְכַמָּה רְשָׁעִים שֶׁעוֹבְרִים עַל מִצְווֹת הַתּוֹרָה.</p>\n<p>אֶלָּא כָּךְ שָׁנָה בְּסוֹד הַמִּשְׁנָיוֹת: אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁעוֹשִׂים קָרְבָּן שֶׁל רָצוֹן לַקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁמַּקְרִיבִים אֶת בְּנֵיהֶם לִשְׁמוֹנָה יָמִים לְקָרְבָּן, וּכְשֶׁנִּמּוֹלִים, נִכְנָסִים לַחֵלֶק הַטּוֹב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. וְכֵיוָן שֶׁנִּכְנְסוּ בַּחֵלֶק הַזֶּה שֶׁל הַצַּדִּיק, הֵם נִקְרָאִים צַדִּיקִים. וַדַּאי כֻּלָּם צַדִּיקִים.</p>\n<p>וְעַל כֵּן לְעוֹלָם יִירְשׁוּ אָרֶץ, כַּכָּתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם, וְכָתוּב זֶה הַשַּׁעַר לַה' צַדִּיקִים יָבאוּ בוֹ, אוֹתָם שֶׁנִּמּוֹלוּ וְנִקְרָאִים צַדִּיקִים. נֵצֶר מַטָּעַי - נֵצֶר מֵאוֹתָם הַנְּטִיעוֹת שֶׁנָּטַע הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַן עֵדֶן. הָאָרֶץ הַזּוֹ הִיא אַחַת מֵהֶן, וְעַל כֵּן יֵשׁ לְיִשְׂרָאֵל חֵלֶק טוֹב לָעוֹלָם הַבָּא, וְכָתוּב (שם לז) צַדִּיקִים יִירְשׁוּ אָרֶץ. (יסעיה ס) לְעוֹלָם יִירְשׁוּ אָרֶץ, מַה זֶּה לְעוֹלָם? כְּמוֹ שֶׁבֵּאַרְנוּ בְּמִשְׁנָתֵנוּ, וַהֲרֵי הַדָּבָר הַזֶּה נִתְבָּאֵר בֵּין הַחֲבֵרִים.</p>"],[9522011214,"<p>(ולמדנו, מה ראה הכתוב שלא נקרא אברהם עד עתה)? (נ\"א: בא ראה, הקדוש ברוך הוא לא קרא לאברהם אברהם עד עתה, מה הטעם? אלא כך בארנו, שעד עתה לא נמול, וכשנמול, התחברה בו הה\"א הזו ושרתה בו). אֶלָּא כָּךְ בֵּאַרְנוּ, שֶׁעַד עַכְשָׁו לֹא נִמּוֹל, וּכְשֶׁנִּמּוֹל, הִתְחַבֵּר לַהֵ\"א הַזּוֹ וְהַשְּׁכִינָה שָׁרְתָה בּוֹ, וְאָז נִקְרָא אַבְרָהָם.</p>\n<p>וְהַיְנוּ מַה שֶּׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. וְשָׁנָה בְּה' בְּרָאָם, וְשָׁנָה בְּאַבְרָהָם. מָה אוֹמְרִים? אֶלָּא זֶה חֶסֶד וְזוֹ הַשְּׁכִינָה, וְהַכֹּל יוֹרֵד יַחַד, וְהַדָּבָר לֹא קָשֶׁה, וְזֶה וְזֶה הָיָה.</p>\n<p>אָמַר רַבִּי יַעֲקֹב לְרַבִּי אַבָּא, הַה' הַזּוֹ שֶׁל הִבָּרְאָם הִיא קְטַנָּה, וְה' שֶׁל הַלְה' (דברים לב) - גְּדוֹלָה. מַה בֵּין זֶה לָזֶה? אָמַר לוֹ, זוֹ שְׁמִטָּה, וְזֶה יוֹבֵל, (ויש ששונים שהכל אחד, שכאשר מאירה מהצדיק, אז עומדת בשלמות וה\"א גדולה, שהרי מוארת כראוי, ופעמים שלא עומדת בשלמות ויונקת מצד האחר, אז ה\"א קטנה). וּמִשּׁוּם כָּךְ לִפְעָמִים שֶׁהַלְּבָנָה עוֹמֶדֶת בִּשְׁלֵמוּתָהּ, וְלִפְעָמִים בְּחֶסְרוֹנָהּ, וּבְפָנֶיהָ נִמְצָא וְנוֹדָע, וְהַכֹּל יָפֶה, וְזֶה הוּא בֵּרוּר הַדָּבָר.</p>"],[9522011215,"<p>אָמַר רַבִּי אַבָּא, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם מִכָּל שְׁאָר הָעַמִּים וְנָתַן לָהֶם אוֹת הַבְּרִית הַזּוֹ, שֶׁכָּל מִי שֶׁיֵּשׁ בּוֹ אוֹת הַבְּרִית הַזּוֹ, אֵין יוֹרֵד לַגֵּיהִנֹּם אִם הוּא שׁוֹמֵר אוֹתוֹ כָּרָאוּי, שֶׁאֵין מַכְנִיס אוֹתוֹ לְרָשׁוּת אַחֶרֶת וְלֹא מְשַׁקֵּר בְּשֵׁם הַמֶּלֶךְ. שֶׁכָּל מִי שֶׁמְּשַׁקֵּר בָּזֶה, כְּמִי שֶׁמְּשַׁקֵּר בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (הושע ה) בַּה' בָּגָדוּ כִּי בָנִים זָרִים יָלָדוּ.</p>\n<p>עוֹד אָמַר רַבִּי אַבָּא, בִּזְמַן שֶׁהָאָדָם מַעֲלֶה אֶת בְּנוֹ לְהַכְנִיסוֹ לַבְּרִית הַזּוֹ, קוֹרֵא הַקָּדוֹשׁ בָּרוּךְ הוּא לַפָּמַלְיָא שֶׁלּוֹ וְאוֹמֵר, רְאוּ אֵיזוֹ בְּרִיָּה עָשִׂיתִי בָּעוֹלָם! בְּאוֹתָהּ הַשָּׁעָה מִזְדַּמֵּן (לו) אֵלִיָּהוּ, וְטָס אֶת הָעוֹלָם בְּאַרְבַּע טִיסוֹת וּמִזְדַּמֵּן לְשָׁם,</p>\n<p>וְעַל זֶה שָׁנִינוּ שֶׁצָּרִיךְ אָדָם לְתַקֵּן כִּסֵּא אַחֵר לִכְבוֹדוֹ, וְיֹאמַר: זֶה הַכִּסֵּא שֶׁל אֵלִיָּהוּ. וְאִם לֹא, אֵינוֹ שׁוֹרֶה שָׁם. וְהוּא עוֹלֶה וּמֵעִיד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בֹּא רְאֵה, בָּרִאשׁוֹנָה כָּתוּב (מלכים א יט) מַה לְּךְ פֹּה אֵלִיָּהוּ וְגוֹ', וְכָתוּב קַנֹּא קִנֵּאתִי לַה' אֱלֹהֵי צְבָאוֹת כִּי עָזְבוּ בְרִיתְךְ בְּנֵי יִשְׂרָאֵל וְגוֹ'. אָמַר לוֹ, חַיֶּיךְ, שֶׁבְּכָל מָקוֹם שֶׁהָרֹשֶׁם הַקָּדוֹשׁ הַזֶּה יִרְשְׁמוּ אוֹתוֹ בָּנַי בִּבְשָׂרָם, אַתָּה תִזְדַּמֵּן לְשָׁם. וְהַפֶּה שֶׁהֵעִיד שֶׁיִּשְׂרָאֵל עָזְבוּ, הוּא יָעִיד שֶׁיִּשְׂרָאֵל מְקַיְּמִים אֶת הַבְּרִית הַזּוֹ. וַהֲרֵי שָׁנִינוּ, עַל מָה נֶעֱנַשׁ אֵלִיָּהוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא? עַל שֶׁאָמַר לָשׁוֹן הָרָע עַל בָּנָיו.</p>\n<p>בֵּינְתַיִם בָּא אוֹר הַיּוֹם, וְהָיוּ אוֹמְרִים דִּבְרֵי תוֹרָה. קָמוּ לָלֶכֶת, אָמַר לוֹ אוֹתוֹ הָאִישׁ, בְּמַה שֶּׁעֲסַקְתֶּם בַּלַּיְלָה הַזֶּה הַשְׁלִימוּ. אָמְרוּ, מַה הוּא? אָמַר לוֹ, שֶׁתִּרְאוּ לְמָחָר אֶת פָּנָיו שֶׁל בַּעַל הַבְּרִית, שֶׁהֲרֵי אִשְׁתִּי בִּקְשָׁה אֶת הַבַּקָּשָׁה הַזּוֹ מִכֶּם, וּמִילַת הַבְּרִית שֶׁל בְּנִי שֶׁנּוֹלַד לִי - לְמָחָר תִּהְיֶה הַהִלּוּלָא שֶׁלּוֹ. אָמַר רַבִּי אַבָּא, זוֹ הִיא בַּקָּשָׁה שֶׁל מִצְוָה, וְנֵשֵׁב לִרְאוֹת אֶת פְּנֵי הַשְּׁכִינָה.</p>\n<p>חִכּוּ כָּל אוֹתוֹ הַיּוֹם. בְּאוֹתוֹ הַלַּיְלָה כִּנֵּס אוֹתוֹ הָאִישׁ אֶת כָּל אוֹהֲבָיו, וְכָל אוֹתוֹ הַלַּיְלָה הִתְעַסְּקוּ בַתּוֹרָה, וְלֹא הָיָה מִי שֶׁיָּשַׁן. אָמַר לָהֶם אוֹתוֹ הָאִישׁ, בְּבַקָּשָׁה מִכֶּם, כָּל אֶחָד וְאֶחָד יֹאמַר דָּבָר חָדָשׁ בַּתּוֹרָה.</p>\n<p>פָּתַח אֶחָד (רבי אבא) וְאָמַר, (שופטים ה) בִּפְרֹעַ פְּרָעוֹת בְּיִשְׂרָאֵל בְּהִתְנַדֵּב עָם בָּרְכוּ ה'. מָה רָאוּ דְבוֹרָה וּבָרָק שֶׁפָּתְחוּ בַּפָּסוּק הַזֶּה? אֶלָּא כָּךְ שָׁנִינוּ, אֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא עַל הַבְּרִית הַזּוֹ, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה וְגוֹ'. שֶׁהֲרֵי שָׁמַיִם וָאָרֶץ עַל זֶה קַיָּמִים.</p>\n<p>מִשּׁוּם כָּךְ, כָּל זְמַן שֶׁיִּשְׂרָאֵל מְקַיְּמִים אֶת הַבְּרִית הַזּוֹ, חֻקּוֹת שָׁמַיִם וָאָרֶץ עוֹמְדִים בְּקִיּוּמָם. וְכָל זְמַן שֶׁחַס וְשָׁלוֹם מְבַטְּלִים אֶת הַבְּרִית הַזּוֹ, אֵין שָׁמַיִם וָאָרֶץ מִתְקַיְּמִים, וְאֵין נִמְצָאוֹת בְּרָכוֹת בָּעוֹלָם.</p>\n<p>בֹּא רְאֵה, לֹא שָׁלְטוּ שְׁאָר הָעַמִּים עַל יִשְׂרָאֵל אֶלָּא כְּשֶׁבִּטְּלוּ מֵהֶם אֶת הַבְּרִית הַזּוֹ. וּמַה בִּטְּלוּ מֵהֶם? שֶׁלֹּא נִפְרְעוּ וְלֹא נִתְגַּלּוּ. וְעַל זֶה כָּתוּב (שמואל א יב) וַיַּעַזְבוּ בְּנֵי יִשְׂרָאֵל אֶת ה' וְגוֹ' וַיִּמְכֹּר אֹתָם בְּיַד סִיסְרָא. וַיַּעַזְבוּ אֶת ה' מַמָּשׁ. עַד שֶׁבָּאָה דְבוֹרָה וְנִדְּבָה אֶת כָּל יִשְׂרָאֵל לַדָּבָר הַזֶּה, אָז נִכְנְעוּ שׂוֹנְאֵיהֶם תַּחְתֵּיהֶם.</p>\n<p>וְהַיְנוּ מַה שֶּׁשָּׁנִינוּ, שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לִיהוֹשֻׁעַ, וְכִי יִשְׂרָאֵל הֵם אֲטוּמִים וְלֹא נִפְרְעוּ וְלֹא הִתְגַּלּוּ וְלֹא מְקַיְּמִים אֶת בְּרִיתִי, וְאַתָּה רוֹצֶה לְהַכְנִיסָם לָאָרֶץ וּלְהַכְנִיעַ אֶת שׂוֹנְאֵיהֶם? (יהושע ה) שׁוּב מֹל אֶת בְּנֵי יִשְׂרָאֵל שֵׁנִית. וְעַד שֶׁנִּפְרְעוּ וְנִתְגַּלְּתָה הַבְּרִית הַזּוֹ, לֹא נִכְנְסוּ לָאָרֶץ וְלֹא נִכְנְעוּ שׂוֹנְאֵיהֶם. אַף כָּאן, כֵּיוָן שֶׁהִתְנַדְּבוּ יִשְׂרָאֵל בָּאוֹת הַזּוֹ, נִכְנְעוּ שׂוֹנְאֵיהֶם תַּחְתֵּיהֶם וְחָזְרוּ הַבְּרָכוֹת לָעוֹלָם. זֶהוּ שֶׁכָּתוּב בִּפְרֹעַ פְּרָעוֹת בְּיִשְׂרָאֵל בְּהִתְנַדֵּב עָם בָּרְכוּ ה'.</p>\n<p>קָם אַחֵר, פָּתַח וְאָמַר, (שמות ד) וַיְהִי בַדֶּרֶךְ בַּמָּלוֹן וַיִּפְגְּשֵׁהוּ ה' וַיְבַקֵּשׁ הֲמִיתוֹ. אֶת מִי? אֶת מֹשֶׁה. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכִי אַתָּה הוֹלֵךְ לְהוֹצִיא אֶת יִשְׂרָאֵל מִמִּצְרַיִם וּלְהַכְנִיעַ מֶלֶךְ גָּדוֹל וְשַׁלִּיט, וְאַתָּה שָׁכַחְתָּ מִמְּךְ אֶת הַבְּרִית, שֶׁבִּנְךְ לֹא נִמּוֹל? מִיָּד - וַיְבַקֵּשׁ הֲמִיתוֹ.</p>\n<p>לָמַדְנוּ, יָרַד גַּבְרִיאֵל בְּשַׁלְהֶבֶת שֶׁל אֵשׁ לִשְׂרֹף אוֹתוֹ, וְנִרְמַז לְנָחָשׁ אֶחָד שׂוֹרֵף לִשְׁאֹף אוֹתוֹ לְתוֹכוֹ. לָמָּה נָחָשׁ? אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתָּה הוֹלֵךְ לַהֲרֹג אֶת הַנָּחָשׁ הַגָּדוֹל וְהֶחָזָק, וּבִנְךְ לֹא נִמּוֹל!? מִיָּד נִרְמַז לְנָחָשׁ אֶחָד לַהֲרֹג אוֹתוֹ,</p>\n<p>עַד שֶׁרָאֲתָה צִפּוֹרָה וּמָלָה אֶת בְּנָהּ וְנִצּוֹל. זֶהוּ שֶׁכָּתוּב וַתִּקַּח צִפּוֹרָה צֹר. מַה זֶּה צֹר? אֶלָּא רְפוּאָה. וּמָה הָרְפוּאָה? שֶׁכָּתוּב וַתִּכְרֹת אֶת עָרְלַת בְּנָהּ. שֶׁנִּצְנְצָה בָּהּ רוּחַ הַקֹּדֶשׁ.</p>\n<p>קָם אַחֵר וְאָמַר, (בראשית מה) וַיֹּאמֶר יוֹסֵף אֶל אֶחָיו גְּשׁוּ נָא אֵלַי וַיִּגָּשׁוּ וַיֹּאמֶר וְגוֹ'. וְכִי לָמָּה קָרָא לָהֶם, וַהֲרֵי הֵם הָיוּ קְרוֹבִים אֵלָיו? אֶלָּא בְּשָׁעָה שֶׁאָמַר לָהֶם אֲנִי יוֹסֵף אֲחִיכֶם, תָּמְהוּ שֶׁרָאוּ אוֹתוֹ בְּמַלְכוּת עֶלְיוֹנָה. אָמַר יוֹסֵף, הַמַּלְכוּת הַזּוֹ, מִשּׁוּם זֶה הִרְוַחְתִּי אוֹתָהּ. גְּשׁוּ נָא אֵלַי וַיִּגָּשׁוּ, שֶׁהֶרְאָה לָהֶם אֶת בְּרִית הַמִּילָה. אָמַר, זוֹ גָרְמָה לִי אֶת הַמַּלְכוּת הַזּוֹ, מִשּׁוּם שֶׁשָּׁמַרְתִּי אוֹתָהּ.</p>\n<p>מִכָּאן לָמַדְנוּ, שֶׁמִּי שֶׁשּׁוֹמֵר אֶת אוֹת הַבְּרִית הַזּוֹ, הַמַּלְכוּת שְׁמוּרָה לוֹ. מִנַּיִן לָנוּ? מִבֹּעַז, שֶׁכָּתוּב (רות ג) חַי ה' שִׁכְבִי עַד הַבֹּקֶר. שֶׁיִּצְרוֹ הָיָה מִתְגָּרֶה בּוֹ, עַד שֶׁנִּשְׁבַּע שְׁבוּעָה וְשָׁמַר אֶת הַבְּרִית הַזּוֹ, מִשּׁוּם כָּךְ זָכָה שֶׁיָּצְאוּ מִמֶּנּוּ מְלָכִים שַׁלִּיטִים עַל כָּל שְׁאָר הַמְּלָכִים, וְהַמֶּלֶךְ הַמָּשִׁיחַ שֶׁנִּקְרָא בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>פָּתַח אַחֵר וְאָמַר, כָּתוּב (תהלים כז) אִם תַּחֲנֶה עָלַי מַחֲנֶה וְגוֹ'. כָּךְ שָׁנִינוּ, בְּזאת אֲנִי בוֹטֵחַ, מַה זֶּה בְּזאת? זוֹ אוֹת הַבְּרִית הַמְזֻמֶּנֶת תָּמִיד אֵצֶל אָדָם, וְנִרְמְזָה לְמַעְלָה. וּמִשּׁוּם כָּךְ נֶאֱמַר בְּזֹאת, כְּמוֹ שֶׁכָּתוּב זֹאת אוֹת הַבְּרִית, זאת בְּרִיתִי, וְהַכֹּל בְּדַרְגָּה אַחַת. וְשָׁנִינוּ, זֶה וְזאת הֵם בְּדַרְגָּה אַחַת וְלֹא נִפְרָדִים.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ, הֲרֵי שְׁאָר בְּנֵי הָאָדָם כָּךְ, לָמָּה דָוִד בִּלְבַדּוֹ וְלֹא אַחֵר? אֶלָּא מִשּׁוּם שֶׁהִיא אֲחוּזָה בּוֹ וְנִרְמְזָה בּוֹ, וְהִיא כֶּתֶר הַמַּלְכוּת.</p>\n<p>בֹּא רְאֵה, מִשּׁוּם שֶׁאֶת הַ את הַזּוֹ לֹא שָׁמַר אוֹתָהּ דָּוִד הַמֶּלֶךְ כָּרָאוּי, הַמַּלְכוּת הָעָבְרָה מִמֶּנּוּ כָּל אוֹתוֹ הַזְּמַן. וְכָךְ לָמַדְנוּ, הַ את הַזּוֹ נִרְמְזָה בַּמַּלְכוּת שֶׁלְּמַעְלָה, וְנִרְמְזָה בִּירוּשָׁלַיִם, הַקִּרְיָה הַקְּדוֹשָׁה.</p>\n<p>בְּאוֹתָהּ הַשָּׁעָה שֶׁדָּוִד עָבַר עָלֶיהָ, יָצָא קוֹל וְאָמַר: דָּוִד, בְּמַה שֶּׁנִּקְשַׁרְתָּ תִּוָּתֵר. אוֹתְךְ טוֹרְדִים מִירוּשָׁלַיִם, וְהַמַּלְכוּת תּוּסַר מִמְּךְ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שמואל ב יב) הִנְנִי מֵקִים עָלֶיךְ רָעָה מִבֵּיתְךְ. מִבֵּיתְךְ בִּמְדֻיָּק. וְכָךְ הָיָה. בְּמַה שֶּׁעָבַר עָלָיו נֶעֱנַשׁ. וּמַה דָּוִד הַמֶּלֶךְ כָּךְ - שְׁאָר בְּנֵי הָעוֹלָם עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>פָּתַח אַחֵר וְאָמַר, (תהים צד) לוּלֵי ה' עֶזְרָתָה לִּי כִּמְעַט שָׁכְנָה דוּמָה נַפְשִׁי. לָמַדְנוּ, בַּמֶּה זוֹכִים יִשְׂרָאֵל שֶׁאֵינָם יוֹרְדִים לַגֵּיהִנֹּם כְּמוֹ שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, וְאֵין נִמְסָרִים בִּידֵי דוּמָה? (אלא) בָּאוֹת הַזּוֹ.</p>\n<p>שֶׁכָּךָ לָמַדְנוּ, בְּשָׁעָה שֶׁאָדָם יוֹצֵא מִן הָעוֹלָם הַזֶּה, כַּמָּה קְבוּצוֹת שֶׁל (מלאכי חבלה) מְחַבְּלִים נִפְקָדִים עָלָיו. מְרִימִים עֵינַיִם וְרוֹאִים אֶת הָאוֹת הַזּוֹ, שֶׁהִיא בְּרִית הַקֹּדֶשׁ, וְנִפְרָדִים מִמֶּנּוּ, וְאֵינוֹ נִתָּן בִּידֵי דוּמָה לָרֶדֶת לַגֵּיהִנֹּם. שֶׁכָּל מִי שֶׁנִּמְסָר בְּיָדוֹ, וַדַּאי יוֹרֵד לַגֵּיהִנֹּם.</p>\n<p>וּמֵהָאוֹת הַזּוֹ פּוֹחֲדִים עֶלְיוֹנִים וְתַחְתּוֹנִים, וְהַדִּינִים הָרָעִים אֵין שׁוֹלְטִים בּוֹ בָּאָדָם אִם הוּא זוֹכֶה לִשְׁמֹר אֶת הַבְּרִית הַזּוֹ, מִשּׁוּם שֶׁהוּא נֶאֱחָז בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>כֵּיוָן שֶׁדָּוִד הַמֶּלֶךְ לֹא שָׁמַר אֶת אוֹת הַבְּרִית הַזּוֹ כָּרָאוּי, הָעָבְרָה מִמֶּנּוּ הַמַּלְכוּת, וְנִטְרַד מִירוּשָׁלַיִם. מִיָּד פָּחַד, כִּי סָבַר שֶׁיּוֹרִידוּ אוֹתוֹ מִיָּד, וְיִמְסְרוּ אוֹתוֹ בְּיַד דּוּמָה וְיָמוּת בָּעוֹלָם הַהוּא, עַד שֶׁהִתְבַּשֵּׂר עָלָיו, שֶׁכָּתוּב (שמואל ב ב) גַּם ה' הֶעֱבִיר חַטָּאתְךְ לֹא תָמוּת. בְּאוֹתָהּ הַשָּׁעָה פָּתַח וְאָמַר, לוּלֵי ה' עֶזְרָתָה לִּי כִּמְעַט שָׁכְנָה דוּמָה נַפְשִׁי.</p>\n<p>פָּתַח אַחֵר וְאָמַר, מַה זֶּה (שכתוב) שֶׁאָמַר דָּוִד (שם טו) וְהִרְאַנִי אֹתוֹ וְאֶת נָוֵהוּ? (מהו והראני אתו ואחר כך ואת נוהו)? מִי יָכוֹל לִרְאוֹת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא כָּךְ שָׁנִינוּ, בַּשָּׁעָה הַהִיא שֶׁגָּזַר עָלָיו אוֹתוֹ הָעֹנֶשׁ, וְדָוִד יָדַע שֶׁעַל שֶׁלֹּא שָׁמַר הָאוֹת הַזּוֹ כָּרָאוּי נֶעֱנָשׁ בָּזֶה, שֶׁהַכֹּל יַחַד אָחוּז, וְהַכֹּל נִרְמָז בָּאוֹת הַזּוֹ, וְלֹא נִקְרָא צַדִּיק מִי שֶׁאֵינוֹ שׁוֹמֵר אוֹתוֹ כָּרָאוּי - הָיָה מְבַקֵּשׁ בַּקָּשָׁתוֹ וְאוֹמֵר, וְהִרְאַנִי אֹתוֹ וְאֶת נָוֵהוּ.</p>\n<p>מַה זֶּה אֹתוֹ? (האות שלו, אות הברית, שהרי אותו של הקב\"ה האות שלו) זוֹ אוֹת הַבְּרִית (שלו) הַקְּדוֹשָׁה, שֶׁהֲרֵי אֲנִי פּוֹחֵד שֶׁאָבְדָה מִמֶּנִּי. מָה הַטַּעַם? מִשּׁוּם שֶׁשְּׁנֵי אֵלּוּ - הַמַּלְכוּת וִירוּשָׁלַיִם - אֲחוּזוֹת בָּזֶה. וּמִשּׁוּם כָּךְ תָּלָה בְּבַקָּשָׁתוֹ אֹתוֹ וְאֶת נָוֵהוּ, שֶׁתַּחֲזֹר הַמַּלְכוּת שֶׁל הָאוֹת הַזּוֹ לִמְקוֹמָהּ, וְהַכֹּל דָּבָר אֶחָד.</p>\n<p>פָּתַח אַחֵר וְאָמַר, (איוב יט) וּמִבְּשָׂרִי אֶחֱזֶה אֱלוֹהַּ. מַה זֶּה וּמִבְּשָׂרִי? הָיָה צָרִיךְ לִהְיוֹת וּמֵעַצְמִי! אֶלָּא מִבְּשָׂרִי מַמָּשׁ, וּמַה הִיא? שֶׁכָּתוּב (ירמיה יא) וּבְשַׂר קֹדֶשׁ יַעַבְרוּ מֵעָלָיִךְ, וְכָתוּב (בראשית יז) וְהָיְתָה בְרִיתִי בִּבְשַׂרְכֶם. שֶׁשָּׁנִינוּ, בְּכָל זְמַן שֶׁנִּרְשָׁם אָדָם בָּרֹשֶׁם הַקָּדוֹשׁ שֶׁל הָאוֹת הַזּוֹ, מִמֶּנָּה רוֹאֶה אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, מִמֶּנּוּ מַמָּשׁ, וְהַנְּשָׁמָה הַקְּדוֹשָׁה נֶאֱחֶזֶת בּוֹ.</p>\n<p>וְאִם לֹא זוֹכֶה, שֶׁאֵינוֹ שׁוֹמֵר אֶת הָאוֹת הַזּוֹ, מַה כָּתוּב? (איוב ד) מִנִּשְׁמַת אֱלוֹהַּ יֹאבֵדוּ, שֶׁהֲרֵי הָרֹשֶׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא נִשְׁמָר. וְאִם זוֹכֶה וְשׁוֹמֵר אוֹתוֹ, אֵין הַשְּׁכִינָה נִפְרֶדֶת מִמֶּנּוּ.</p>\n<p>מָתַי מִתְקַיֵּם בּוֹ? כַּאֲשֶׁר הוּא נִשָּׂא, וְהָאוֹת הַזּוֹ נִכְנֶסֶת לִמְקוֹמָהּ (ששנינו, מה הטעם וא\"ו ה\"א הולכות יחד? אלא אחת זכר ואחת נקבה). מִשְׁתַּתְּפִים יַחַד, וְנִקְרָא שֵׁם אֶחָד, אָז שׁוֹרֶה עֲלֵיהֶם הַחֶסֶד הָעֶלְיוֹן. בְּאֵיזֶה מָקוֹם שׁוֹרֶה? בְּצַד הַזָּכָר. וּמִי הַחֶסֶד? חֶסֶ\"ד אֵ\"ל שֶׁבָּא וְיוֹצֵא מֵהַחָכְמָה הָעֶלְיוֹנָה וּמִתְעַטֵּר בַּזָּכָר. וּמִשּׁוּם כָּךְ נִתְבַּשֶּׂמֶת הַנְּקֵבָה. (נ\"א: ששנינו, הסוד של וי\"ו ה\"א הולכים יחד כמו שזכר ונקבה משתתפים יחד והם אחד, אז שורה עליהם החסד העליון, ומתעטר בזכר ונתבשמת הנקבה).</p>\n<p>עוֹד שָׁנִינוּ, אֱלוֹהַּ כָּךְ הוּא. א\"ל, אוֹר הַחָכְמָה. ו' זָכָר, ה' נְקֵבָה. כְּשֶׁמִּשְׁתַּתְּפִים יַחַד נִקְרָא אֱלוֹהַּ. וְהַנְּשָׁמָה הַקְּדוֹשָׁה מֵהַמָּקוֹם הַזֶּה נֶאֱחֶזֶת, וְהַכֹּל תָּלוּי בָּאוֹת הַזּוֹ,</p>\n<p>וְעַל כֵּן כָּתוּב וּמִבְּשָׂרִי אֶחֱזֶה אֱלוֹהַּ. זוֹ הִיא שְׁלֵמוּת הַכֹּל, מִבְּשָׂרִי מַמָּשׁ, מֵהָאוֹת הַזּוֹ מַמָּשׁ. וְעַל כֵּן אַשְׁרֵיהֶם יִשְׂרָאֵל קְדוֹשִׁים שֶׁאֲחוּזִים בַּקָּדוֹשׁ בָּרוּךְ הוּא, אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' וְגוֹ', וּמִשּׁוּם כָּךְ חַיִּים כֻּלְּכֶם הַיּוֹם.</p>\n<p>אָמַר רַבִּי אַבָּא, וּמַה בְּכָל כָּךְ אַתֶּם חֲכָמִים, וְאַתֶּם יוֹשְׁבִים כָּאן? אָמְרוּ לוֹ, אִם הַצִּפֳּרִים יַעַקְרוּ מִמְּקוֹמָם, לֹא יוֹדְעִים לְאָן טָסוֹת. זֶהוּ שֶׁכָּתוּב (משלי כז) כְּצִפּוֹר נוֹדֶדֶת מִן קִנָּהּ כֵּן אִישׁ נוֹדֵד מִמְּקוֹמוֹ.</p>\n<p>וְהַמָּקוֹם הַזֶּה זִכָּה אוֹתָנוּ לַתּוֹרָה, וְהַדֶּרֶךְ הַזּוֹ שֶׁלָּנוּ. בְּכָל לַיְלָה, חֲצִי אָנוּ יְשֵׁנִים, וַחֲצִי אָנוּ עוֹסְקִים בַּתּוֹרָה. וּכְשֶׁאָנוּ עוֹמְדִים בַּבֹּקֶר, רֵיחוֹת הַשָּׂדֶה וְנַהֲרוֹת מַיִם מְאִירִים לָנוּ אֶת הַתּוֹרָה, וְהִיא מִתְיַשֶּׁבֶת בְּלִבֵּנוּ.</p>\n<p>וְאֶת הַמָּקוֹם הַזֶּה הֲרֵי דָּנוּ אוֹתוֹ לְמַעְלָה פַּעַם אַחַת, וְכַמָּה שָׂרֵי מָגִנִּים הִסְתַּלְּקוּ בְּאוֹתוֹ הַדִּין עַל עֹנֶשׁ הַתּוֹרָה, וְאָז הַהִשְׁתַּדְּלוּת שֶׁלָּנוּ יוֹמָם וָלַיְלָה הִיא בַּתּוֹרָה, וְהַמָּקוֹם הַזֶּה מְסַיֵּעַ לָנוּ, וּמִי שֶׁנִּפְרָד מִכָּאן, כְּמִי שֶׁנִּפְרָד מֵחַיֵּי הָעוֹלָם.</p>\n<p>הֵרִים יָדוֹ רַבִּי אַבָּא וּבֵרַךְ אוֹתָם. יָשְׁבוּ עַד שֶׁהֵאִיר הַיּוֹם. אַחַר שֶׁהֵאִיר הַיּוֹם, אָמְרוּ לְאוֹתָם הַתִּינוֹקוֹת שֶׁלִּפְנֵיהֶם: צְאוּ וּרְאוּ אִם הֵאִיר הַיּוֹם, וְכָל אֶחָד יֹאמַר דָּבָר חָדָשׁ בַּתּוֹרָה לָאִישׁ הַגָּדוֹל הַזֶּה.</p>\n<p>יָצְאוּ וְרָאוּ שֶׁהֵאִיר הַיּוֹם. אָמַר אֶחָד מֵהֶם, מְזֻמֶּנֶת בַּיּוֹם הַזֶּה אֵשׁ מִלְמַעְלָה. אָמַר אַחֵר, וּבַבַּיִת הַזֶּה. אָמַר אַחֵר, זָקֵן אֶחָד כָּאן שֶׁעָתִיד בַּיּוֹם הַזֶּה לְהִשָּׂרֵף בָּאֵשׁ הַזּוֹ. אָמַר רַבִּי אַבָּא, הָרַחֲמָן יַצִּילֵנוּ.</p>\n<p>תָּמַהּ וְלֹא יָכֹל לְדַבֵּר. אָמַר, עֲשַׁן הַמַּלְכוּת נִתְפָּס בָּאָרֶץ. וְכָךְ הָיָה, שֶׁהַיּוֹם הַהוּא רָאוּ הַחֲבֵרִים אֶת פְּנֵי הַשְּׁכִינָה וְהֻקְּפוּ בְאֵשׁ, וְרַבִּי אַבָּא לָהֲטוּ פָנָיו כָּאֵשׁ מִשִּׂמְחַת הַתּוֹרָה.</p>\n<p>שָׁנִינוּ, כָּל אוֹתוֹ הַיּוֹם לֹא יָצְאוּ כֻלָּם מִן הַבַּיִת, וְהַבַּיִת נִקְשַׁר בְּעָשָׁן, וְהָיוּ מְחַדְּשִׁים דְּבָרִים בְּתוֹכָם כְּאִלּוּ קִבְּלוּ הַיּוֹם הַהוּא תּוֹרָה מֵהַר סִינַי. אַחַר שֶׁהִסְתַּלְּקוּ, לֹא הָיוּ יוֹדְעִים אִם הוּא יוֹם וְאִם לַיְלָה. אָמַר רַבִּי אַבָּא, בְּעוֹדֵנוּ עוֹמְדִים, יֹאמַר כָּל אֶחָד מֵעִמָּנוּ דָּבָר חָדָשׁ שֶׁל חָכְמָה לִקְשֹׁר חֶסֶד לְבַעַל הַבַּיִת, בַּעַל הַהִלּוּלָא.</p>\n<p>פָּתַח אֶחָד וְאָמַר, (תהלים סה) אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ וְגוֹ'. בַּתְּחִלָּה חֲצֵרֶיךְ, לְאַחַר מִכֵּן בֵּיתֶךְ, וּלְאַחַר מִכֵּן הֵיכָלֶךְ. זֶה פְּנִימִי מִזֶּה, וְזֶה (נ\"א: לתוך) לְמַעְלָה מִזֶּה. יִשְׁכֹּן חֲצֵרֶיךְ בַּתְּחִלָּה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַיִם קָדוֹשׁ יֵאָמֶר לוֹ.</p>\n<p>נִשְׂבְּעָה בְּטוּב בֵּיתֶךְ לְאַחַר מִכֵּן, כְּמוֹ שֶׁנֶּאֱמַר (משלי כד) בְּחָכְמָה יִבָּנֶה בָּיִת. לֹא כָתוּב הַחָכְמָה יִבְנֶה בַיִת. שֶׁאִם הָיָה כָּתוּב כָּךְ, מַשְׁמָע שֶׁחָכְמָה נִקְרֵאת בַּיִת. אֶלָּא כָּתוּב בְּחָכְמָה יִבָּנֶה בָּיִת, הַיְנוּ מַה שֶּׁכָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ'.</p>\n<p>קְדוֹשׁ הֵיכָלֶךְ לְאַחַר זֶה הוּא שְׁלֵמוּת הַכֹּל. שֶׁכָּךְ שָׁנִינוּ, מַה זֶּה הֵיכָל? כְּלוֹמַר ה\"י כ\"ל, זֶה וָזֶה, וְהַכֹּל נִשְׁלָם יַחַד.</p>\n<p>מַה מּוֹכִיחַ רֹאשׁ הַכָּתוּב שֶׁכָּתוּב אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ? זֶה מִי שֶׁמַּקְרִיב אֶת בְּנוֹ קָרְבָּן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּקָּרְבָּן הַהוּא, וּמִתְרַצֶּה בּוֹ וּמְקָרֵב אוֹתוֹ, וְשָׂם אֶת מְדוֹרוֹ בִּשְׁנֵי חֲדָרִים, וְאוֹחֵז אֶת זֶה וְאֶת זֶה, שֶׁאוֹתָם הַשְּׁנַיִם נִקְשְׁרוּ יַחַד, שֶׁכָּתוּב יִשְׁכֹּן חֲצֵרֶיךְ, וַדַּאי שְׁנֵי חֲצֵרֶיךְ.\\</p>\n<p>מִשּׁוּם כָּךְ הַחֲסִידִים הָרִאשׁוֹנִים, זְקֵנֵינוּ שֶׁל כָּאן, כְּשֶׁמַּקְרִיבִים אֶת בְּנֵיהֶם לַקָּרְבָּן הַזֶּה, פּוֹתְחִים וְאוֹמְרִים: אַשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶיךְ. אוֹתָם שֶׁעוֹמְדִים עֲלֵיהֶם אוֹמְרִים: נִשְׂבְּעָה בְּטוּב בֵּיתֶךְ קְדוֹשׁ הֵיכָלֶךְ. אַחַר כָּךְ מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְווֹתָיו וְצִוָּנוּ לְהַכְנִיסוֹ בִּבְרִיתוֹ שֶׁל אַבְרָהָם אָבִינוּ. וְאוֹתָם שֶׁעוֹמְדִים עֲלֵיהֶם אוֹמְרִים: כְּשֵׁם שֶׁהִכְנַסְתּוֹ לַבְּרִית וְכוּ'.</p>\n<p>וְשָׁנִינוּ, בַּתְּחִלָּה יְבַקֵּשׁ אָדָם רַחֲמִים עָלָיו, וְאַחַר כָּךְ עַל הָאַחֵר, שֶׁכָּתוּב (ויקרא טז) וְכִפֶּר בַּעֲדוֹ - בַּתְּחִלָּה, וְאַחַר כָּךְ - וּבְעַד כָּל קְהַל יִשְׂרָאֵל. וְאָנוּ לָקַחְנוּ אֶת הַדֶּרֶךְ הַזּוֹ, וְכָךְ יָפֶה וְרָאוּי לְפָנֵינוּ.</p>\n<p>אָמַר רַבִּי אַבָּא, וַדַּאי כָּךְ הוּא וְנָאֶה הַדָּבָר. וּמִי שֶׁלֹּא אוֹמֵר כָּךְ, הוּא מוֹצִיא אֶת עַצְמוֹ מֵעֲשָׂרָה חֻפּוֹת שֶׁעָתִיד לַעֲשׂוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים בָּעוֹלָם הַבָּא. וְכֻלָּם נִקְשָׁרִים בָּזֶה. וּמִשּׁוּם כָּךְ עֲשָׂרָה דְבָרִים שֶׁל הָאֱמוּנָה יֵשׁ בַּפָּסוּק הַזֶּה אַשְׁרֵי תִּבְחַר וּתְקָרֵב וְגוֹ', וּמִכָּל דָּבָר וְדָבָר נַעֲשֵׂית חֻפָּה אַחַת מִמֶּנָּה.</p>\n<p>אַשְׁרֵי חֶלְקְכֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהֲרֵי הַתּוֹרָה נִקְשֶׁרֶת בִּלְבַבְכֶם כְּאִלּוּ עֲמַדְתֶּם בְּגוּפְכֶם בְּהַר סִינַי בְּשָׁעָה שֶׁנִּתְּנָה תוֹרָה לְיִשְׂרָאֵל.</p>\n<p>פָּתַח אַחֵר וְאָמַר, (שמות כ) מִזְבַּח אֲדָמָה תַּעֲשֶׂה לִּי וְזָבַחְתָּ עָלָיו אֶת עֹלֹתֶיךְ וְאֶת שְׁלָמֶיךְ וְגוֹ'. שָׁנִינוּ, כָּל מִי שֶׁמַּקְרִיב אֶת בְּנוֹ לַקָּרְבָּן הַזֶּה, כְּאִלּוּ הִקְרִיב אֶת כָּל הַקָּרְבָּנוֹת שֶׁל הָעוֹלָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּכְאִלּוּ בָּנָה מִזְבֵּחַ שָׁלֵם לְפָנָיו.</p>\n<p>מִשּׁוּם כָּךְ צָרִיךְ לְסַדֵּר מִזְבֵּחַ עִם כְּלִי אֶחָד מָלֵא עָפָר לָמוּל עָלָיו אֶת הַבְּרִית הַקָּדוֹשׁ הַזֶּה, וְנֶחְשָׁב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּאִלּוּ זָבַח עָלָיו עוֹלוֹת וְקָרְבָּנוֹת, צֹאן וּבָקָר.</p>\n<p>וְנוֹחַ לוֹ יוֹתֵר מִכֻּלָּם, שֶׁכָּתוּב וְזָבַחְתָּ עָלָיו אֶת עֹלֹתֶיךְ וְאֶת שְׁלָמֶיךְ וְגוֹ'. בְּכָל הַמָּקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי. מַהוּ אַזְכִּיר אֶת שְׁמִי? (את) זוֹ הַמִּילָה, שֶׁכָּתוּב בָּהּ (תהלים כה) סוֹד ה' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם. מִזְבַּח הָאֲדָמָה הַזֶּה וַדַּאי כְּמוֹ שֶׁאָמַרְנוּ, מַה כָּתוּב אַחֲרָיו?</p>\n<p>וְאִם מִזְבַּח אֲדָמָה תַּעֲשֶׂה לִּי. רֶמֶז לַגֵּר כַּאֲשֶׁר מִתְגַּיֵּר, שֶׁהֵם מֵעַם קְשֵׁה עֹרֶף וּקְשֵׁה לֵב. זֶה נִקְרָא מִזְבַּח אֲבָנִים.</p>\n<p>לֹא תִבְנֶה אֶתְהֶן גָּזִית, מַה זֶּה? שֶׁצָּרִיךְ לְהַכְנִיסוֹ לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, (כדי) וְלֹא יָמוּל אוֹתוֹ, עַד שֶׁיִּשְׁכַּח עֲבוֹדָה הָאַחֶרֶת שֶׁעָבַד עַד עַתָּה, וְיָסִיר מִמֶּנּוּ אוֹתוֹ קְשִׁי הַלֵּב.</p>\n<p>וְאִם נִמּוֹל וְלֹא הוּסַר מִמֶּנּוּ אוֹתוֹ קְשִׁי הַלֵּב לְהִכָּנֵס לַעֲבוֹדַת הַקֹּדֶשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הֲרֵי הוּא כְּפֶסֶל הָאֶבֶן הַזֶּה שֶׁגּוֹזְרִים אוֹתוֹ מֵהַצַּד הַזֶּה וּמִן הַצַּד הַזֶּה, וְנִשְׁאָר אֶבֶן כְּבָרִאשׁוֹנָה. מִשּׁוּם כָּךְ לֹא תִבְנֶה אֶתְהֶן גָּזִית. שֶׁאִם הוּא נִשְׁאָר בְּקַשְׁיוּתוֹ - כִּי חַרְבְּךְ הֵנַפְתָּ עָלֶיהָ וַתְּחַלֲלֶהָ. כְּלוֹמַר, אוֹתָהּ הַמִּילָה שֶׁנִּמּוֹל אֵינָהּ מוֹעִילָה לוֹ.</p>\n<p>מִשּׁוּם כָּךְ, אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמַּקְרִיב אֶת הַקָּרְבָּן הַזֶּה בְּשִׂמְחָה וּבְרָצוֹן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְצָרִיךְ לִשְׂמֹחַ בַּחֵלֶק הַזֶּה כָּל הַיּוֹם (ההוא), שֶׁכָּתוּב (שם ה) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנֵּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךְ אֹהֲבֵי שְׁמֶךְ.</p>\n<p>פָּתַח אַחֵר וְאָמַר, (בראשית יז) וַיְהִי אַבְרָם בֶּן תִּשְׁעִים שָׁנָה וְתֵשַׁע שָׁנִים וַיֵּרָא ה' וְגוֹ', אֲנִי אֵל שַׁדַּי הִתְהַלֵּךְ לְפָנַי וְגוֹ'. בַּפָּסוּק הַזֶּה יֵשׁ לְעַיֵּן בּוֹ, וְקָשֶׁה בְּכַמָּה דְרָכִים. וְכִי עַד עַתָּה לֹא הִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם אֶלָּא (עד) כָּעֵת, כְּשֶׁהִגִּיעַ לַיָּמִים הָאֵלֶּה, וַיֵּרָא ה' אֵלָיו וְלֹא קֹדֶם? וַהֲרֵי כָּתוּב וַיֹּאמֶר ה' אֶל אַבְרָם. וַה' אָמַר אֶל אַבְרָם. וַיֹּאמֶר לְאַבְרָם יָדוֹעַ תֵּדַע וְגוֹ', וְכָעֵת מוֹנֶה אֶת חֶשְׁבּוֹן הַיָּמִים, וּכְשֶׁמּוֹנֶה אוֹתָם, כָּתוּב וַיֵּרָא ה' אֶל אַבְרָם, נִשְׁמָע שֶׁעַד עַתָּה לֹא הִתְגַּלָּה עָלָיו! וְעוֹד, שֶׁכָּתוּב בֶּן תִּשְׁעִים שָׁנָה וְתֵשַׁע שָׁנִים. בַּתְּחִלָּה שָׁנָה, וְאַחַר כָּךְ שָׁנִים !:</p>\n<p>אֶלָּא כָּךְ שָׁנִינוּ, כָּל אוֹתָם הַיָּמִים לֹא כָתוּב וַיֵּרָא. מָה הַטַּעַם? אֶלָּא כָּל מַה שֶּׁהָיָה אָטוּם וְסָתוּם, (כך) לֹא הִתְגַּלָּה עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא כָּרָאוּי. כָּעֵת הִתְגַּלָּה אֵלָיו, שֶׁכָּתוּב וַיֵּרָא. מָה הַטַּעַם? מִשּׁוּם שֶׁרָצָה לְגַלּוֹת בּוֹ הָאוֹת הַזּוֹ, הַכֶּתֶר הַקָּדוֹשׁ.</p>\n<p>וְעוֹד, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא מִמֶּנּוּ זֶרַע קָדוֹשׁ, וְקָדוֹשׁ לֹא יִהְיֶה כְּשֶׁעֲדַיִן הוּא בְּבָשָׂר אָטוּם, אֶלָּא אָמַר, כָּעֵת שֶׁהוּא בֶּן תִּשְׁעִים וְתֵשַׁע שָׁנִים וְלִזְמַן קָרוֹב הוּא שֶׁיֵּצֵא מִמֶּנּוּ זֶרַע קָדוֹשׁ, שֶׁיִּהְיֶה הוּא קָדוֹשׁ בַּהַתְחָלָה, וְאַחַר כָּךְ יֵצֵא מִמֶּנּוּ זֶרַע קָדוֹשׁ. מִשּׁוּם כָּךְ מָנָה אֶת יָמָיו בָּזֶה, וְלֹא בְּכָל הַזְּמַנִּים הַלָּלוּ שֶׁבַּהַתְחָלָה.</p>\n<p>עוֹד, תִּשְׁעִים שָׁנָה - שֶׁכָּל יָמָיו הָרִאשׁוֹנִים לֹא הָיוּ שָׁנִים, אֶלָּא כְּשָׁנָה אַחַת, שֶׁלֹּא הָיוּ יָמָיו יָמִים. עַכְשָׁו שֶׁהִגִּיעַ לָזֶה, הֵם שָׁנִים וְלֹא שָׁנָה.</p>\n<p>וַיֹּאמֶר אֵלָיו אֲנִי אֵל שַׁדַּי. מַה מַּשְׁמִיעַ שֶׁעַד עַכְשָׁו לֹא אָמַר אֲנִי אֵל שַׁדַּי? אֶלָּא כָּךְ שָׁנִינוּ, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא כְּתָרִים תַּחְתּוֹנִים שֶׁאֵינָם קְדוֹשִׁים לְמַטָּה, וְכָל אוֹתָם שֶׁלֹּא נִמּוֹלִים, נִטְמָאִים בָּהֶם.</p>\n<p>וּרְשׁוּמִים בָּהֶם. וּמָה הָרִשּׁוּם שֶׁיֵּשׁ בָּהֶם? שֶׁנִּרְאֶה בָהֶם שִׁי\"ן דָּלֶ\"ת וְלֹא יוֹתֵר, וּמִשּׁוּם כָּךְ נִטְמָאִים בָּהֶם וְנִדְבָּקִים בָּהֶם. אַחַר שֶׁנִּמּוֹלִים יוֹצְאִים מֵאֵלּוּ, וְנִכְנָסִים לְכַנְפֵי הַשְּׁכִינָה, וּמִתְגַּלֶּה בָהֶם יוֹ\"ד, הָרֹשֶׁם הַקָּדוֹשׁ, אוֹת הַבְּרִית הַשָּׁלֵם, וְנִרְשָׁם בָּהֶם שַׁדַּ\"י, וְנִשְׁלָמִים בְּקִיּוּם שָׁלֵם, וְעַל כֵּן כָּתוּב בָּזֶה אֲנִי אֵל שַׁדַּי.</p>\n<p>הִתְהַלֵּךָ לְפָנַי וֶהְיֵה תָמִים. שָׁלֵם. שֶׁכָּעֵת אוֹת חֲסֵרָה בָּרֹשֶׁם שֶׁל שִׁי\"ן וְדָלֶ\"ת. מוֹל אֶת עַצְמְךְ, וֶהְיֵה שָׁלֵם בָּרֹשֶׁם שֶׁל יוֹ\"ד. וּמִי שֶׁהוּא בָּרֹשֶׁם הַזֶּה, רָאוּי לְהִתְבָּרֵךְ בַּשֵּׁם הַזֶּה, שֶׁכָּתוּב (בראשית כח) וְאֵל שַׁדַּי יְבָרֵךְ אוֹתְךְ.</p>\n<p>מַה זֶּה אֵל שַׁדַּי? הַהוּא שֶׁמִּמֶּנּוּ יוֹצְאוֹת הַבְּרָכוֹת, הוּא שֶׁשּׁוֹלֵט עַל כָּל הַכְּתָרִים הַתַּחְתּוֹנִים, וְהַכֹּל פּוֹחֲדִים מִיִּרְאָתוֹ וּמִזְדַּעְזְעִים. מִשּׁוּם כָּךְ, מִי שֶׁנִּמּוֹל, כָּל אוֹתָם שֶׁאֵינָם קְדוֹשִׁים מִתְרַחֲקִים מִמֶּנּוּ וְלֹא שׁוֹלְטִים בּוֹ, וְלֹא עוֹד, אֶלָּא שֶׁלֹּא יוֹרֵד לַגֵּיהִנֹּם, שֶׁכָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'. (כל אותם שנמולו נקראים צדיקים, ומשום כך לעולם יירשו ארץ, שאין יורש את הארץ הזו אלא ההוא שנקרא צדיק, אף כך, ועמך כלם צדיקים לעולם יירשו ארץ וגו')</p>\n<p>אָמַר רַבִּי אַבָּא, אַשְׁרֵיכֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, אַשְׁרֵי חֶלְקִי שֶׁבָּאתִי לִשְׁמֹעַ אֶת הַדְּבָרִים הַלָּלוּ מִפִּיכֶם. כֻּלְּכֶם קְדוֹשִׁים, כֻּלְּכֶם בְּנֵי הָאֱלוֹהַּ הַקָּדוֹשׁ. עֲלֵיכֶם כָּתוּב (שם מד) זֶה יֹאמַר לַה' אָנִי וְזֶה יִקְרָא בְשֵׁם יַעֲקֹב וְזֶה יִכְתֹּב יָדוֹ לַה' וּבְשֵׁם יִשְׂרָאֵל יְכַנֶּה. כָּל אֶחָד מִכֶּם אָחוּז וְקָשׁוּר בַּמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן, וְאַתֶּם גְּדוֹלִים מְמֻנִּים מָגִנִּים מֵאוֹתָהּ הָאָרֶץ שֶׁנִּקְרֵאת אֶרֶץ הַחַיִּים, שֶׁגְּדוֹלֶיהָ אוֹכְלִים מִן הַמָּן שֶׁל הַטַּל הַקָּדוֹשׁ.</p>\n<p>פָּתַח אַחֵר וְאָמַר, (קהלת י) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ. וְכָתוּב (שם) אֵי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נָעַר וְשָׂרַיִךְ בַּבֹּקֶר יֹאכֵלוּ. הַפְּסוּקִים הַלָּלוּ קָשִׁים הֲדָדִית, וְלֹא קָשִׁים. זֶהוּ שֶׁכָּתוּב אַשְׁרֵיךְ אֶרֶץ - זוֹ הָאָרֶץ שֶׁלְּמַעְלָה שֶׁשּׁוֹלֶטֶת עַל כָּל אוֹתָם הַחַיִּים שֶׁלְּמַעְלָה, וּמִשּׁוּם כָּךְ נִקְרֵאת אֶרֶץ הַחַיִּים, וְעָלֶיהָ כָּתוּב (דברים יא) אֶרֶץ אֲשֶׁר ה' אֱלֹהֶיךְ דֹּרֵשׁ אֹתָהּ תָּמִיד. וְכָתוּב אֶרֶץ אֲשֶׁר לֹא בְמִסְכֵּנֻת תֹּאכַל בָּהּ לֶחֶם לֹא תֶחְסַר כֹּל בָּהּ. לֹא תֶחְסַר כֹּל בָּהּ, בִּמְדֻיָּק. וְכָל כָּךְ לָמָּה? מִשּׁוּם שֶׁכָּתוּב שֶׁמַּלְכֵּךְ בֶּן חוֹרִים, זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (שמות ד) בְּנִי בְכֹרִי יִשְׂרָאֵל.</p>\n<p>בֶּן חוֹרִים, מַה זֶּה בֶּן חוֹרִים? כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כה) יוֹבֵל הִיא קֹדֶשׁ תִּהְיֶה לָכֶם, וְכָתוּב וּקְרָאתֶם דְּרוֹר בָּאָרֶץ, שֶׁהֲרֵי כָּל הַחֵרוּת בָּאָה מִן הַיּוֹבֵל, וּמִשּׁוּם כָּךְ בֶּן חוֹרִין. וְאִם תֹּאמַר, בֶּן חוֹרִין, וְלֹא כָתוּב בֶּן חֵרוּת - כָּךְ זֶה בְּוַדַּאי. בֶּן חֵרוּת הָיָה צָרִיךְ לִהְיוֹת!</p>\n<p>אֶלָּא בְּמִשְׁנָתֵנוּ הַסְּתוּמָה לָמַדְנוּ, כְּשֶׁמִּתְחַבְּרוֹת יוֹ\"ד בְּה', אָז כָּתוּב וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְאַל תֹּאמַר כְּשֶׁמִּתְחַבְּרִים, אֶלָּא וַדַּאי מִתְחַבְּרִים, וּמִשּׁוּם כָּךְ כָּתוּב בֶּן חוֹרִים. וְעַל כֵּן אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים, וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ - בְּשִׂמְחָה, בִּשְׁלֵמוּת וּבְרָצוֹן.</p>\n<p>אֵי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נָעַר - זוֹ הָאָרֶץ שֶׁלְּמַטָּה. שֶׁלָּמַדְנוּ, כָּל שְׁאָר אַרְצוֹת שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, נִתְּנוּ לִגְדוֹלִים מָגִנִּים שֶׁמְּמֻנִּים עֲלֵיהֶם. וּמֵעַל לְכֻלָּם הַהוּא שֶׁכָּתוּב בּוֹ (תהלים לז) נַעַר הָיִיתִי גַּם זָקַנְתִּי. וְלָמַדְנוּ, הַפָּסוּק הַזֶּה אָמַר אוֹתוֹ שָׂרוֹ שֶׁל עוֹלָם, וְעַל כֵּן כָּתוּב אֵי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נָעַר. אוֹי לָעוֹלָם שֶׁיּוֹנֵק מֵהַצַּד הַזֶּה. וּכְשֶׁיִּשְׂרָאֵל בַּגָּלוּת, יוֹנְקִים כְּמִי שֶׁיּוֹנֵק מֵרָשׁוּת אַחֶרֶת.</p>\n<p>וְשָׂרַיִךָ בַּבֹּקֶר יֹאכֵלוּ - וְלֹא בְּכָל הַיּוֹם. בַּבֹּקֶר - וְלֹא בִּזְמַן אַחֵר שֶׁל הַיּוֹם. שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁהַחַמָּה זוֹרַחַת וּבָאִים וְסוֹגְדִים לַשֶּׁמֶשׁ, הָרֹגֶז תָּלוּי בָּעוֹלָם. בִּשְׁעַת הַמִּנְחָה הָרֹגֶז תָּלוּי בָּעוֹלָם. מִי גָרַם אֶת זֶה? מִשּׁוּם שֶׁמַּלְכֵּךְ נָעַר, הַהוּא שֶׁנִּקְרָא נַעַר.</p>\n<p>וְאַתֶּם צַדִּיקֵי הָאֱמֶת, קְדוֹשִׁים עֶלְיוֹנִים, בְּנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, אֵין יוֹנְקִים מִן הַצַּד הַזֶּה, אֶלָּא מֵאוֹתוֹ הַמָּקוֹם הַקָּדוֹשׁ שֶׁלְּמַעְלָה. עֲלֵיכֶם כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם.</p>\n<p>פָּתַח רַבִּי אַבָּא וְאָמַר, (ישעיה ה) אָשִׁירָה נָּא לִידִידִי שִׁירַת דּוֹדִי לְכַרְמוֹ וְגוֹ', וַיְעַזְּקֵהוּ וַיְסַקְּלֵהוּ וְגוֹ'. בַּפְּסוּקִים הַלָּלוּ יֵשׁ לְהִתְבּוֹנֵן, לָמָּה כָּתוּב שִׁירָה? הָיָה צָרִיךְ לִהְיוֹת תּוֹכָחָה! לִידִידִי? הָיָה צָרִיךְ לִהְיוֹת לְדוֹדִי, כְּמוֹ שֶׁכָּתוּב שִׁירַת דּוֹדִי. כֶּרֶם הָיָה לִידִידִי בְּקֶרֶן בֶּן שָׁמֶן?</p>\n<p>הִסְתַּכַּלְתִּי בְּכָל הַתּוֹרָה וְלֹא מָצָאתִי מָקוֹם שֶׁנִּקְרָא בֶּן שָׁמֶן. אֶלָּא אֶת הַפְּסוּקִים הַלָּלוּ בֵּאֲרוּ הַחֲבֵרִים בְּכַמָּה צוּרוֹת, וְהַכֹּל יָפֶה וְכָךְ זֶה. אֲבָל אָשִׁירָה נָּא לִידִידִי - זֶה יִצְחָק, שֶׁהָיָה יָדִיד, וְנִקְרָא יָדִיד טֶרֶם שֶׁיָּצָא לָעוֹלָם.</p>\n<p>לָמָּה יָדִיד? שֶׁשָּׁנִינוּ, אַהֲבָה רַבָּה הָיְתָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא בּוֹ שֶׁלֹּא נַעֲשָׂה טֶרֶם שֶׁנִּמּוֹל אַבְרָהָם אָבִיו, וְנִקְרָא שָׁלֵם, וְנוֹסְפָה לוֹ הֵ\"א לְהַשְׁלִימוֹ, וְכֵן לְשָׂרָה הֲרֵי נִתְּנָה לָהּ הֵ\"א הַ את.</p>\n<p>כָּאן יֵשׁ לְהִתְבּוֹנֵן, ה' לְשָׂרָה זֶה יָפֶה, אֲבָל לְאַבְרָהָם לָמָּה הֵ\"א וְלֹא יוֹ\"ד? יוֹ\"ד הָיָה צָרִיךְ לִכְתֹּב, שֶׁהֲרֵי הוּא הָיָה זָכָר. אֶלָּא סוֹד עֶלְיוֹן הָיָה (הוא) סָתוּם אֶצְלֵנוּ אַבְרָהָם עָלָה לְמַעְלָה, וְנָטַל סוֹד מֵהֵ\"א הָעֶלְיוֹנָה שֶׁהִיא הָעוֹלָם שֶׁל הַזָּכָר. הֵ\"א הָעֶלְיוֹנָה וְהֵ\"א הַתַּחְתּוֹנָה, זוֹ תְּלוּיָה בַּזָּכָר וְזוֹ וַדַּאי בַּנְּקֵבָה. וּמִשּׁוּם כָּךְ אַבְרָהָם עָלָה בַּהֵ\"א שֶׁלְּמַעְלָה, וְשָׂרָה יָרְדָה בַּהֵ\"א שֶׁלְּמַטָּה.</p>\n<p>עוֹד, שֶׁכָּתוּב כֹּה יִהְיֶה זַרְעֶךְ, וְלָמַדְנוּ זַרְעֶךְ - זַרְעֲךְ מַמָּשׁ, שֶׁהָיָה מַתְחִיל לְהִכָּנֵס בַּבְּרִית הַזּוֹ. וּמִי שֶׁמַּתְחִיל לְהִכָּנֵס בַּבְּרִית הַזּוֹ - נִכְנָס. וּמִשּׁוּם כָּךְ הַגֵּר שֶׁמִּתְגַּיֵּר נִקְרָא גֵר צֶדֶק, מִשּׁוּם שֶׁלֹּא בָא מִגֶּזַע קָדוֹשׁ שֶׁנִּמּוֹלוּ. וְעַל כֵּן, מִי שֶׁנִּכְנָס בָּזֶה - שְׁמוֹ כָּזֶה:</p>\n<p>אַבְרָהָם. מִשּׁוּם כָּךְ כָּתוּב בּוֹ כֹּה יִהְיֶה זַרְעֶךְ, זַרְעֲךְ מַמָּשׁ, וְנִמְסַר לוֹ הֵ\"א. וְאִם לֹא נִמְסְרָה הֵ\"א לְשָׂרָה, הָיָה לוֹ לְאַבְרָהָם לְהוֹלִיד לְמַטָּה, כְּמוֹ שֶׁהַכֹּה הַזּוֹ מוֹלִידָה לְמַטָּה. אַחַר שֶׁנִּמְסְרָה לְשָׂרָה הֵ\"א, הִתְחַבְּרוּ שְׁתֵּי הֵהִי\"ן יַחַד וְהוֹלִידוּ לְמַעְלָה, וּמַה שֶּׁיָּצָא מֵהֶם הוּא יוֹ\"ד. מִשּׁוּם כָּךְ יוֹ\"ד אוֹת הָרֹאשׁ שֶׁל יִצְחָק, זָכָר. מִכָּאן מַתְחִיל הַזָּכָר לְהִתְפַּשֵּׁט, וְעַל כֵּן כָּתוּב (בראשית כא) כִּי בְיִצְחָק יִקָּרֵא לְךְ זָרַע. בְּיִצְחָק וְלֹא בְּךְ. יִצְחָק הוֹלִיד לְמַעְלָה, שֶׁכָּתוּב (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב, וְיַעֲקֹב הִשְׁלִים הַכֹּל.</p>\n<p>וְאִם תֹּאמַר, וְכִי אַבְרָהָם בָּזֶה נֶאֱחַז וְלֹא יוֹתֵר, וַהֲרֵי כָּתוּב חֶסֶד לְאַבְרָהָם? אֶלָּא חֶלְקוֹ כָּךְ הוּא, מִשּׁוּם שֶׁעָשָׂה חֶסֶד עִם בְּנֵי הָעוֹלָם. אֲבָל לְהוֹלִיד - כָּאן הוּא אָחוּז וּמִכָּאן מַתְחִיל, וְעַל כֵּן לֹא נִמּוֹל אַבְרָהָם אֶלָּא בֶּן תִּשְׁעִים וְתֵשַׁע שָׁנָה, וְסוֹד הַדָּבָר הֲרֵי יָדוּעַ, וּבֵאַרְנוּהוּ בְמִשְׁנָתֵנוּ.</p>\n<p>וּמִשּׁוּם כָּךְ יִצְחָק, הַדִּין הַקָּשֶׁה, יָצָא לֶאֱחֹז לְחֶלְקוֹ וּלְהוֹלִיד, וְנִקְרָא חֶסֶד, וְעַל כֵּן יַעֲקֹב הִשְׁלִים הַכֹּל מֵהַצַּד הַזֶּה וּמֵהַצַּד הַזֶּה. מִצַּד הָאֲחִיזָה אַבְרָהָם וְיִצְחָק לְחֶלְקָם לְמַעְלָה הִיא הַשְּׁלֵמוּת. מֵהַצַּד שֶׁנִּתַּן לָהֶם לְהוֹלִיד מִלְּמַטָּה לְמַעְלָה הִיא שְׁלֵמוּת. וְעַל כֵּן כָּתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר. בּוֹ נֶאֶחְזוּ הַגְּוָנִים מִמַּעְלָה וּמִמַּטָּה.</p>\n<p>וְעַל כֵּן כָּתוּב כָּאן שִׁירָה, שֶׁכָּתוּב (שם ה) אָשִׁירָה נָּא לִידִידִי. שִׁירָה וַדַּאי. שֶׁזֶּה נִקְרָא לְהוֹלִיד זָכָר, שֶׁהֲרֵי נִקְרָא יָדִיד טֶרֶם שֶׁיָּבֹא לָעוֹלָם.</p>\n<p>וְיֵשׁ אוֹמְרִים, (זה) אָשִׁירָה נָּא לִידִידִי - זֶה אַבְרָהָם, שֶׁנֶּאֱמַר (ירמיה יא) מַה לִּידִידִי בְּבֵיתִי. וְאַבְרָהָם יָרַשׁ יְרֻשָּׁה שֶׁל נַחֲלַת הַחֵלֶק הַזֶּה. אֲבָל (על) מַה שֶּׁאָמַרְנוּ שֶׁזֶּה יִצְחָק - כָּךְ זֶה.</p>\n<p>שִׁירַת דּוֹדִי לְכַרְמוֹ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּקְרָא דוֹדִי, שֶׁכָּתוּב (שיר ה) דּוֹדִי צַח וְאָדוֹם. יְדִידִי - אוֹחֵז בְּדוֹדִי, זָכָר, וּמִמֶּנּוּ נִטַּע כֶּרֵם, שֶׁכָּתוּב כֶּרֶם הָיָה לִידִידִי.</p>\n<p>בְּקֶֹרֶן בֶּן שָׁמֶן, מַה זֶּה בְּקֶרֶן בֶּן שָׁמֶן? אֶלָּא בַּמֶּה יָצָא הַכֶּרֶם הַזֶּה וּבַמֶּה נִטַּע? חָזַר וְאָמַר בְּקֶרֶן, מַה זֶּה קֶרֶן? שֶׁכָּתוּב (יהושע ו) בְּקֶרֶן הַיּוֹבֵל. בְּקֶרֶן הַיּוֹבֵל מַתְחִיל. וְהַקֶּרֶן הַזּוֹ אֲחוּזָה בְּאוֹתוֹ הַזָּכָר שֶׁנִּקְרָא בֶּן שָׁמֶן.</p>\n<p>מַה זֶּה בֶּן שָׁמֶן? כְּמוֹ שֶׁנֶּאֱמַר בֶּן חוֹרִים, וּשְׁנֵיהֶם דָּבָר אֶחָד. שֶׁמֶן, שֶׁמִּשָּׁם שׁוֹפֵעַ שֶׁמֶן וּגְדֻלָּה לְהַדְלִיק הַמְּאוֹרוֹת, וּמִשּׁוּם כָּךְ בֶּן שָׁמֶן. וְהַשֶּׁמֶן וְהַמִּשְׁחָה הַלָּלוּ שׁוֹפְעִים וְיוֹצְאִים וּמַדְלִיקִים מְאוֹרוֹת, עַד שֶׁנּוֹטֵל אוֹתוֹ וְכוֹנֵס אוֹתוֹ הַקֶּרֶן הַזֶּה. וְזֶה נִקְרָא קֶרֶן הַיּוֹבֵל. מִשּׁוּם כָּךְ אֵין מְשִׁיחַת הַמַּלְכוּת אֶלָּא בְּקֶרֶן, וְעַל כֵּן נִמְשְׁכָה מַלְכוּת דָּוִד, שֶׁנִּמְשַׁח בְּקֶרֶן וְנֶאֱחַז בּוֹ.</p>\n<p>וַיְעַזְּקֵהוּ וַיְסַלְּקֵהוּ - כַּטַּבַּעַת הַזּוֹ שֶׁמַּקִּיפָה אֶת כָּל הַצְּדָדִים. וַיְסַקְּלֵהוּ - שֶׁהֵסִיר מִמֶּנּוּ וּמֵחֶלְקוֹ אֶת כָּל אוֹתָם שָׂרִים גְּדוֹלִים, כָּל אוֹתָם הַמָּגִנִּים, כָּל אוֹתָם הַכְּתָרִים הַתַּחְתּוֹנִים. וְהוּא לָקַח לוֹ אֶת (הקרן) הַכֶּרֶם הַזֶּה לְחֶלְקוֹ, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>\n<p>וַיִּטָעֵהוּ שּׁרֵק - כְּמוֹ שֶׁנֶּאֱמַר (ירמיה ב) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת. כֻּלֹּ\"ה כָּתוּב בְּהֵ\"א. מִכָּאן הִתְחִיל אַבְרָהָם לְהוֹלִיד לְמַעְלָה, וּמִזֶּה יָצָא זֶרַע אֱמֶת. כֻּלֹּה זֶרַע אֱמֶת וַדַּאי. הַיְנוּ שֶׁכָּתוּב כֹּה יִהְיֶה זַרְעֶךְ, וְהַכֹּל דָּבָר אֶחָד. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁיָּרְשׁוּ אֶת הַיְרֻשָּׁה הַקְּדוֹשָׁה הַזּוֹ.</p>\n<p>סוֹף הַפָּסוּק (ישעיה ה) - וַיִּבֶן מִגְדָּל בְּתוֹכוֹ. מַה זֶּה מִגְדָּל? כְּמוֹ שֶׁנֶּאֱמַר (משלי יח) מִגְדַּל עֹז שֵׁם ה' בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. בּוֹ יָרוּץ צַדִּיק וַדַּאי.</p>\n<p>וְגַם יֶקֶב חָצֵב בּוֹ - זֶה הַשַּׁעַר שֶׁל הַצֶּדֶק, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. מַה מַּשְׁמִיעֵנוּ? שֶׁכָּל בֶּן יִשְׂרָאֵל שֶׁנִּמּוֹל, נִכְנָס בִּשְׁנֵיהֶם וְזוֹכֶה לִשְׁנֵיהֶם.</p>\n<p>וּמִי שֶׁמַּקְרִיב אֶת בְּנוֹ לַקָּרְבָּן הַזֶּה, מַכְנִיס אוֹתוֹ לַשֵּׁם הַקָּדוֹשׁ. וְעַל הָאוֹת הַזּוֹ מִתְקַיְּמִים שָׁמַיִם וָאָרֶץ, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. וּבַעַל הַהִלּוּלָא הַזֶּה זָכָה לַכֹּל, לִרְאוֹת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא פָּנִים בְּפָנִים בַּיּוֹם הַזֶּה.</p>\n<p>אַשְׁרֵי חֶלְקֵנוּ שֶׁזָּכִינוּ לַיּוֹם הַזֶּה, וְאַשְׁרֵי חֶלְקְךְ עִמָּנוּ. וְהַבֵּן הַזֶּה שֶׁנּוֹלַד לְךְ, קָרָאנוּ עָלָיו (ישעיה מג) כֹּל הַנִּקְרָא בִשְׁמִי וְגוֹ', יְצַרְתִּיו אַף עֲשִׂיתִיו. וְכָתוּב (שם נד) וְכָל בָּנַיִךְ לִמּוּדֵי ה' וְגוֹ'. לִוּוּ אֶת רַבִּי אַבָּא שְׁלֹשָׁה מִילִין.</p>\n<p>אָמְרוּ לוֹ, בַּעַל הַהִלּוּלָא הַזֶּה הַמְאָרֵחַ שֶׁלְּךְ זָכָה לְכָל זֶה מִשּׁוּם שֶׁקִּיֵּם אֶת קִיּוּם הַמִּצְוָה. אָמַר, מַה הִיא? אָמַר אוֹתוֹ הָאִישׁ, אִשְׁתִּי, אֵשֶׁת אָחִי הָיְתָה, וְהוּא מֵת בְּלִי בָנִים, וְנָשָׂאתִי אוֹתָהּ, וְזֶה הַבֵּן הָרִאשׁוֹן שֶׁהָיָה לִי מִמֶּנָּה, וְקָרָאתִי לוֹ בְּשֵׁם אָחִי שֶׁנִּפְטַר. אָמַר לוֹ, מִכָּאן וָהָלְאָה קְרָא לוֹ אִידִי, וְזֶה הוּא אִידִי בַּר יַעֲקֹב. בֵּרַךְ אוֹתָם רַבִּי אַבָּא וְהָלַךְ לְדַרְכּוֹ.</p>\n<p>כַּאֲשֶׁר בָּא, סִדֵּר הַדְּבָרִים לִפְנֵי רַבִּי אֶלְעָזָר, וּפָחַד לוֹמַר לְרַבִּי שִׁמְעוֹן. יוֹם אֶחָד הָיָה לִפְנֵי רַבִּי שִׁמְעוֹן, וְאָמַר רַבִּי שִׁמְעוֹן, מַהוּ שֶׁכָּתוּב וַיִּפֹּל אַבְרָם עַל פָּנָיו וַיְדַבֵּר אִתּוֹ אֱלֹהִים לֵאמֹר אֲנִי הִנֵּה בְרִיתִי אִתָּךְ? מַשְׁמָע שֶׁעַד שֶׁלֹּא נִמּוֹל, הָיָה נוֹפֵל עַל פָּנָיו וּמְדַבֵּר עִמּוֹ. אַחַר שֶׁנִּמּוֹל, עָמַד בְּקִיּוּמוֹ וְלֹא פָחַד. אֲנִי הִנֵּה בְרִיתִי אִתָּךְ, שֶׁמָּצָא אֶת עַצְמוֹ מָהוּל.</p>\n<p>אָמַר לוֹ רַבִּי אַבָּא, אִם נוֹחַ לִפְנֵי מַר שֶׁאֹמַר לְפָנָיו מֵאוֹתָם הַדְּבָרִים הַמְעֻלִּים שֶׁשָּׁמַעְתִּי בָּזֶה? אָמַר לוֹ, אֱמֹר. אָמַר לוֹ, אֲנִי פוֹחֵד שֶׁלֹּא יֵעָנְשׁוּ עַל יָדִי. אָמַר לוֹ, חַס וְשָׁלוֹם, (תהלים קיב) מִשְּׁמוּעָה רָעָה לֹא יִירָא נָכוֹן לִבִּי בָּטוּחַ בַּה'. סִפֵּר לוֹ הַמַּעֲשֶׂה, וְסִדֵּר לְפָנָיו אֶת כָּל אוֹתָם הַדְּבָרִים.</p>\n<p>אָמַר לוֹ, וְכִי כָּל הַדְּבָרִים הַמְעֻלִּים הַלָּלוּ הָיוּ טְמוּנִים אֶצְלְךְ וְלֹא אָמַרְתָּ אוֹתָם? גּוֹזְרַנִי עָלֶיךְ שֶׁכָּל שְׁלֹשִׁים הַיָּמִים הַלָּלוּ תִּלְמַד וְתִשְׁכַּח, וְלֹא כָתוּב (משלי ג) אַל תִּמְנַע טוֹב מִבְּעָלָיו בִּהְיוֹת לְאֵל יָדְךְ לַעֲשׂוֹת? וְכָךְ הָיָה. אָמַר, גּוֹזְרַנִי שֶׁבַּתּוֹרָה הַזּוֹ יִגְלוּ לְבָּבֶל (ויגלו בבבל) בֵּין הַחֲבֵרִים.</p>\n<p>חָלְשָׁה דַעְתּוֹ שֶׁל רַבִּי אַבָּא. יוֹם אֶחָד רָאָה אוֹתוֹ רַבִּי שִׁמְעוֹן, אָמַר לוֹ, דְּפוּס לִבְּךְ מָצוּי בְּפָנֶיךְ. אָמַר לוֹ, לֹא עַל שֶׁלִּי הוּא, אֶלָּא עַל שֶׁלָּהֶם! אָמַר לוֹ, חַס וְשָׁלוֹם שֶׁנֶּעֶנְשׁוּ, אֶלָּא מִשּׁוּם שֶׁדְּבָרִים הִתְגַּלּוּ בֵינֵיהֶם כָּל כָּךְ. יִגְלוּ לְבֵין הַחֲבֵרִים, וְיִלְמְדוּ אוֹתָם הַדְּרָכִים, (ומתמתקים) וְיִתְכַּסּוּ הַדְּבָרִים בְּתוֹכָם, שֶׁהֲרֵי אֵין הַדְּבָרִים מִתְגַּלִּים אֶלָּא בֵּינֵינוּ, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עִמָּנוּ, וְעַל יָדֵינוּ מִתְגַּלִּים הַדְּבָרִים.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּתוּב (ישעיה נח) אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךְ וְגוֹ'. עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַכְרִיז עַל בָּנָיו וְיֹאמַר, אָז יִבָּקַע כַּשַּׁחַר אוֹרֶךְ וַאֲרֻכָתְךְ מְהֵרָה תִצְמָח וְהָלַךְ לְפָנֶיךְ צִדְקֶךְ כְּבוֹד ה' יַאַסְפֶךְ.</p>"],[9522011216,"<p>רַבִּי חִיָּיא פָּתַח, (שיר ב) הַנִּצָּנִים נִרְאוּ בָאָרֶץ עֵת הַזָּמִיר הִגִּיעַ וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ. הַנִּצָּנִים נִרְאוּ בָאָרֶץ, כְּשֶׁבָּרָא הַקָּבָּ\"ה אֶת הָעוֹלָם, נָתַן בָּאָרֶץ כָּל הַכֹּחַ שֶׁרָאוּי לָהּ, וְהַכֹּל הָיָה בָּאָרֶץ, וְלֹא הוֹצִיאָה פֵרוֹת בָּעוֹלָם עַד שֶׁנִּבְרָא אָדָם. כֵּיוָן שֶׁנִּבְרָא אָדָם, הַכֹּל רָאוּי (ד\"א לצאת) בָּעוֹלָם, וְהָאָרֶץ גִּלְּתָה אֶת פֵּרוֹתֶיהָה וְכֹחָהּ שֶׁנִּפְקְדוּ בָהּ.</p>\n<p>כְּמוֹ זֶה הַשָּׁמַיִם לֹא נָתְנוּ כֹחוֹת לָאָרֶץ עַד שֶׁבָּא אָדָם. זֶהוּ שֶׁכָּתוּב (בראשית ב) וְכֹל שִׂיחַ הַשָּׂדֶה טֶרֶם יִהְיֶה בָאָרֶץ וְכָל עֵשֶׂב הַשָּׂדֶה טֶרֶם יִצְמָח כִּי לֹא הִמְטִיר ה' אֱלֹהִים עַל הָאָרֶץ וְאָדָם אַיִן לַעֲבֹד אֶת הָאֲדָמָה. נִסְתַּתְּרוּ בָהּ כָּל אוֹתָם תּוֹלָדוֹת וְלֹא הִתְגַּלּוּ, וְהַשָּׁמַיִם הִתְעַכְּבוּ, שֶׁלֹּא הִמְטִירוּ עַל הָאָרֶץ מִשּׁוּם שֶׁאָדָם אַיִן, שֶׁלֹּא נִמְצָא וְלֹא נִבְרָא, וְהַכֹּל הִתְעַכֵּב בִּגְלָלוֹ. כֵּיוָן שֶׁנִּרְאָה אָדָם, מִיָּד הַנִּצָּנִים נִרְאוּ בָאָרֶץ, וְכָל הַכֹּחוֹת שֶׁנִּסְתְּרוּ, הִתְגַּלּוּ וְנִתְּנוּ בָהּ.</p>\n<p>עֵת הַזָּמִיר הִגִּיעַ, שֶׁהִתְתַּקֵּן תִּקּוּן הַתִּשְׁבָּחוֹת לְזַמֵּר לִפְנֵי הַקָּבָּ\"ה מַה שֶּׁלֹּא נִמְצָא עַד שֶׁלֹּא נִבְרָא אָדָם. וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ, שֶׁהֲרֵי (זה) (כל) דָבָר שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (ד\"א שעשה) הַקָּבָּ\"ה שֶׁלֹּא נִמְצָא בָּעוֹלָם עַד שֶׁנִּבְרָא אָדָם. כֵּיוָן שֶׁנִּמְצָא אָדָם, הַכֹּל נִמְצָא.</p>\n<p>אַחַר שֶׁחָטָא, הַכֹּל הִסְתַּלֵּק מֵהָעוֹלָם וְהִתְקַלְּלָה הָאָרֶץ. זֶהוּ שֶׁכָּתוּב (בראשית ג) אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךְ וְגוֹ', וְכתוּב כִּי תַעֲבֹד אֶת הָאֲדָמָה לֹא תֹסֵף תֵּת כֹּחָהּ לָךְ וְגוֹ', וְכָתוּב וְקוֹץ וְדַרְדַּר תַּצְמִיחַ לָךְ.</p>\n<p>בָּא נֹחַ וְתִקֵּן קַרְדֻּמִּים וּפְצִירוֹת בָּעוֹלָם. אַחַר כָּךְ, וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה. בָּאוּ בְּנֵי הָעוֹלָם וְחָטְאוּ לִפְנֵי הַקָּבָּ\"ה, וְהִסְתַּלְּקוּ צִבְאוֹת הָאָרֶץ (של העולם) כְּמִקֹּדֶם, וְהָיוּ עוֹמְדִים עַד שֶׁבָּא אַבְרָהָם.</p>\n<p>כֵּיוָן שֶׁבָּא אַבְרָהָם (לעולם), מִיָּד הַנִּצָּנִים נִרְאוּ בָאָרֶץ, הִתְתַּקְּנוּ וְהִתְגַּלּוּ כָּל הַצְּבָאוֹת בָּאָרֶץ. עֵת הַזָּמִיר הִגִּיעַ, בְּשָׁעָה שֶׁאָמַר לוֹ הַקָּבָּ\"ה לָמוּל. כֵּיוָן שֶׁהִגִּיעַ אוֹתוֹ הַזְּמַן שֶׁבְּרִית נִמְצְאָה בּוֹ בְּאַבְרָהָם וְנִמּוֹל, אָז הִתְקַיֵּם בּוֹ כָּל הַפָּסוּק הַזֶּה, וְהִתְקַיֵּם הָעוֹלָם, וּדְבַר הַקָּבָּ\"ה הָיָה בְּהִתְגַּלּוּת בּוֹ. זֶהוּ שֶׁכָּתוּב וַיֵּרָא אֵלָיו ה'.</p>\n<p>רַבִּי אֶלְעָזָר פָּתַח הַפָּסוּק הַזֶּה (בשעה) אַחַר שֶׁנִּמּוֹל אַבְרָהָם. שֶׁעַד שֶׁלֹּא נִמּוֹל, לֹא דִבֵּר עִמּוֹ אֶלָּא מִתּוֹךְ דַּרְגָּה תַחְתּוֹנָה, וְהַדְּרָגוֹת הָעֶלְיוֹנוֹת לֹא הָיוּ קַיָּמוֹת עַל אוֹתָהּ הַדַּרְגָּה. כֵּיוָן שֶׁנִּמּוֹל, מִיָּד הַנִּצָּנִים נִרְאוּ בָאָרֶץ. אֵלּוּ הַדְּרָגוֹת הַתַּחְתּוֹנוֹת שֶׁהוֹצִיאָה וְהִתְקִינָה הַדַּרְגָּה הַתַּחְתּוֹנָה הַזּוֹ.</p>\n<p>עֵת הַזָּמִיר הִגִּיעַ - אֵלּוּ עַנְפֵי הָעָרְלָה. וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ - זֶהוּ קוֹל שֶׁיּוֹצֵא מִתּוֹךְ אוֹתוֹ פְּנִימִי שֶׁל הַכֹּל, וְאוֹתוֹ קוֹל נִשְׁמַע, וְזֶה קוֹל שֶׁגּוֹזֵר דָּבָר לְדַבֵּר וְעוֹשֶׂה לָהּ שְׁלֵמוּת.</p>\n<p>בֹּא רְאֵה שֶׁעַד שֶׁלֹּא נִמּוֹל אַבְרָהָם לֹא הָיְתָה עָלָיו אֶלָּא הַדַּרְגָּה הַזּוֹ כְּפִי שֶׁאָמַרְנוּ. כֵּיוָן (אחר) שֶׁנִּמּוֹל מַה כָּתוּב? וַיֵּרָא אֵלָיו ה'. לְמִי? שֶׁהֲרֵי לֹא כָתוּב וַיֵּרָא ה' אֶל אַבְרָם? שֶׁאִם לְאַבְרָם אָז מָה הַשֶּׁבַח כָּאן יוֹתֵר מִבַּהַתְחָלָה עַד שֶׁלֹּא נִמּוֹל שֶׁכָּתוּב וַיֵּרָא ה' אֶל אַבְרָם?</p>\n<p>אֶלָּא סוֹד נִסְתָּר הוּא. וַיֵּרָא אֵלָיו ה' - לְאוֹתָהּ דַּרְגָּה שֶׁדִּבְּרָה עִמּוֹ, מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָזֶה עַד שֶׁלֹּא נִמּוֹל. שֶׁכָּעֵת הִתְגַּלָּה הַקּוֹל וְהִתְחַבֵּר בַּדִּבּוּר כְּשֶׁדִּבֵּר עִמּוֹ.</p>\n<p>וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל. וְהוּא - וְלֹא גִלָּה מִי. אֶלָּא כָּאן גִּלָּה אֶת הַחָכְמָה שֶׁכָּל הַדְּרָגוֹת שְׁרוּיוֹת עַל הַדַּרְגָּה הַתַּחְתּוֹנָה הַזּוֹ אַחַר שֶׁנִּמּוֹל אַבְרָהָם. בֹּא רְאֵה, וַיֵּרָא אֵלָיו ה' - זֶהוּ הַסּוֹד שֶׁקּוֹל שֶׁנִּשְׁמַע שֶׁהִתְחַבֵּר בַּדִּבּוּר וּמִתְגַּלֶּה בּוֹ.</p>\n<p>וְהוּ\"א יֹשֵׁב פֶּתַח הָאֹהֶל - זֶהוּ הָעוֹלָם הָעֶלְיוֹן שֶׁעָמַד לְהָאִיר עָלָיו. כְּחֹם הַיּוֹם, שֶׁהֲרֵי הוּאַר הַיָּמִין, הַדַּרְגָּה שֶׁאַבְרָהָם נִדְבַּק בּוֹ. דָּבָר אַחֵר כְּחֹם הַיּוֹם - בְּשָׁעָה שֶׁמִּתְקָרֶבֶת דַּרְגָּה לְדַרְגָּה בִּתְשׁוּקָה שֶׁל זֶה כְּנֶגֶד זֶה.</p>\n<p>וַיֵּרָא אֵלָיו. אָמַר רַבִּי אַבָּא, עַד שֶׁלֹּא נִמּוֹל אַבְרָהָם, הָיָה אָטוּם. כֵּיוָן שֶׁנִּמּוֹל, הַכֹּל הִתְגַּלָּה, וְשָׁרְתָה עָלָיו שְׁכִינָה בִּשְׁלֵמוּת כָּרָאוּי. בֹּא רְאֵה, וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל. וְהוּא - זֶהוּ הָעוֹלָם הָעֶלְיוֹן שֶׁשּׁוֹרֶה עַל עוֹלָם הַתַּחְתּוֹן הַזֶּה. אֵימָתַי? כְּחֹם הַיּוֹם, בִּזְמַן שֶׁתְּשׁוּקָתוֹ שֶׁל צַדִּיק אֶחָד לִשְׁרוֹת בּוֹ.</p>\n<p>מִיָּד - וַיִּשָּׂא עֵינָיו וַיַּרְא וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים נִצָּבִים עָלָיו. מִי הֵם שְׁלֹשָׁה אֲנָשִׁים? אֵלּוּ אַבְרָהָם יִצְחָק וְיַעֲקֹב, שֶׁעוֹמְדִים עַל הַדַּרְגָּה הַזּוֹ, וּמֵהֶם הִיא יוֹנֶקֶת (יסוד העולם) וְנִזּוֹנֵית.</p>\n<p>וְאָז - וַיַּרְא וַיָּרָץ לִקְרָאתָם. שֶׁתְּשׁוּקַת הַדַּרְגָּה הַתַּחְתּוֹנָה הַזּוֹ לְהִתְחַבֵּר בָּהֶם וְחֶדְוָתָהּ לְהִמָּשֵׁךְ אַחֲרֵיהֶם. וַיִּשְׁתַּחוּ אָרְצָה, לְהַתְקִין לָהֶם כִּסֵּא.</p>\n<p>בֹּא רְאֵה, הַקָּבָּ\"ה עָשָׂה אֶת דָּוִד הַמֶּלֶךְ עַמּוּד אֶחָד מֵהַכִּסֵּא הָעֶלְיוֹן כְּמוֹ הָאָבוֹת. וְאַף עַל גַּב שֶׁהוּא כִּסֵּא אֲלֵיהֶם, אֲבָל בִּזְמַן שֶׁמִּתְחַבֵּר בָּהֶם הוּא עַמּוּד אֶחָד לְהִתְתַּקֵּן בַּכִּסֵּא הָעֶלְיוֹן, וּלְכָךְ נָטַל אֶת הַמַּלְכוּת בְּחֶבְרוֹן דָּוִד הַמֶּלֶךְ שֶׁבַע שָׁנִים לְהִתְחַבֵּר בָּהֶם, וַהֲרֵי נֶאֱמַר.</p>\n<p>וַיֵּרָא אֵלָיו ה' בְּאֵלֹנֵי מַמְרֵא. לָמָּה בְּאֵלֹנֵי מַמְרֵא וְלֹא בְמָקוֹם אַחֵר? אֶלָּא מִשּׁוּם שֶׁנָּתַן לוֹ עֵצָה עַל בְּרִית הַמִּילָה שֶׁלּוֹ. בְּשָׁעָה שֶׁאָמַר הַקָּבָּ\"ה לְאַבְרָהָם לְהִמּוֹל, הָלַךְ אַבְרָהָם לְהִמָּלֵךְ עִם חֲבֵרָיו. אָמַר לוֹ עָנֵר: אַתָּה בֶּן תִּשְׁעִים שָׁנָה, וְאַתָּה מֵעִיק לְעַצְמְךְ?</p>\n<p>אָמַר לוֹ מַמְרֵא: הֲזָכַרְתָּ אֶת הַיּוֹם שֶׁזָּרְקוּ אוֹתְךְ הַכַּשְׂדִּים לְתוֹךְ כִּבְשַׁן הָאֵשׁ, וְאוֹתוֹ רָעָב שֶׁעָבַר עַל הָעוֹלָם, שֶׁכָּתוּב (בראשית יב) וַיְהִי רָעָב בָּאָרֶץ וַיֵּרֶד אַבְרָם מִצְרָיְמָה, וְאוֹתָם מְלָכִים שֶׁרָדְפוּ אַחֲרֵיהֶם וְהִכִּיתָ אוֹתָם, וְהַקָּבָּ\"ה הִצִּיל אוֹתְךְ מֵהַכֹּל וְלֹא יָכֹל אִישׁ לַעֲשׂוֹת לְךְ רַע? קוּם וַעֲשֵׂה אֶת מִצְוַת רִבּוֹנְךְ! אָמַר לוֹ הַקָּבָּ\"ה: מַמְרֵא, אַתָּה נָתַתָּ לוֹ עֵצָה לְהִמּוֹל, חַיֶּיךְ אֵינִי מִתְגַּלֶּה עָלָיו אֶלָּא בַּפַּלְטֵרִין שֶׁלְּךְ. וְזֶהוּ שֶׁכָּתוּב בְּאֵלֹנֵי מַמְרֵא. (עד כאן התוספתא).</p>"],[9522011217,"<p>רַבּוֹתֵינוּ פָּתְחוּ בַּפָּסוּק הַזֶּה, (שיר א) לְרֵיחַ שְׁמָנֶיךְ טוֹבִים שֶׁמֶן תּוּרַק שְׁמֶךְ וְגוֹ'. שָׁנוּ רַבּוֹתֵינוּ, נְשָׁמָה זוֹ שֶׁל בֶּן הָאָדָם, בְּשָׁעָה שֶׁעוֹלָה מֵהָאָרֶץ לָרָקִיעַ וְעוֹמֶדֶת בְּאוֹתוֹ זהַר עֶלְיוֹן שֶׁאָמַרְנוּ, הַקָּבָּ\"ה מְבַקֵּר אוֹתָהּ.</p>\n<p>בֹּא תִשְׁמַע, אָמַר רַבִּי שִׁמְעוֹן בַּר יוֹחַאי, כָּל נִשְׁמַת הַצַּדִּיקִים, כֵּיוָן שֶׁעוֹמֶדֶת בִּמְקוֹם שְׁכִינַת הַכָּבוֹד, שֶׁרְאוּיָה לָשֶׁבֶת, הַקָּבָּ\"ה קוֹרֵא לָאָבוֹת וְאוֹמֵר לָהֶם: לְכוּ וּבַקְּרוּ אֶת פְּלוֹנִי הַצַּדִּיק שֶׁבָּא, וְהַקְדִּימוּ לוֹ שָׁלוֹם מִשְּׁמִי. וְהֵם אוֹמְרִים: רִבּוֹן הָעוֹלָם, לֹא רָאוּי לְאַבָּא לָלֶכֶת לִרְאוֹת אֶת הַבֵּן. הַבֵּן רָאוּי לִרְאוֹת וּלְהֵרָאוֹת וְלִִדְרוֹשׁ אֶת אָבִיו.</p>\n<p>וְהוּא קוֹרֵא לְיַעֲקֹב וְאוֹמֵר לוֹ: אַתָּה שֶׁהָיָה לְךְ צַעַר בָּנִים, לֵךְ וְקַבֵּל (למדו) פְּנֵי פְלוֹנִי הַצַּדִּיק שֶׁבָּא לְכָאן, וַאֲנִי אֵלֵךְ עִמְּךְ. זֶהוּ שֶׁכָּתוּב (תהלים כד) מְבַקְשֵׁי פָנֶיךְ יַעֲקֹב סֶלָה. לֹא נֶאֱמַר מְבַקֵּשׁ, אֶלָּא מְבַקְשֵׁי. אָמַר רַבִּי חִיָּיא, מֵרֹאשׁ הַפָּסוּק מַשְׁמָע, שֶׁכָּתוּב זֶה דּוֹר דֹּרְשָׁו וְגוֹ'.</p>\n<p>אָמַר רַבִּי יַעֲקֹב אָמַר רַבִּי חִיָּיא (נ\"א עקיבא), יַעֲקֹב אָבִינוּ הוּא כִּסֵּא הַכָּבוֹד. וְכֵן תָּנָא דְבֵי אֵלִיָּהוּ, יַעֲקֹב אָבִינוּ הוּא כִּסֵּא בִּפְנֵי עַצְמוֹ, שֶׁכַּתוּב (ויקרא כו) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב. בְּרִית כָּרַת הַקָּבָּ\"ה לְיַעֲקֹב לְבַדּוֹ יוֹתֵר מִכָּל אֲבוֹתָיו, שֶׁעָשָׂה לוֹ כִּסֵּא הַכָּבוֹד, פְּרָט מִן הָרִאשׁוֹן.</p>\n<p>רַבִּי אֱלִיעֶזֶר הָיָה יוֹשֵׁב וְהָיָה עוֹסֵק בַּתּוֹרָה. בָּא אֵלָיו רַבִּי עֲקִיבָא וְאָמַר לוֹ, בַּמֶּה מַר עוֹסֵק? אָמַר לוֹ, בַּפָּסוּק הַזֶּה שֶׁכָּתוּב (שמואל א ב) וְכִסֵּא כָבוֹד יַנְחִלֵם. מַהוּ כִּסֵּא כָבוֹד יַנְחִלֵם? זֶה יַעֲקֹב אָבִינוּ שֶׁעָשָׂה לוֹ כִּסֵּא כָבוֹד לְבַדּוֹ לְקַבֵּל תּוֹרָה בְּעַד נִשְׁמַת הַצַּדִּיק,</p>\n<p>וְהַקָּבָּ\"ה הוֹלֵךְ עִמּוֹ בְּכָל רֹאשׁ חֹדֶשׁ וְחֹדֶשׁ, וּכְשֶׁרוֹאָה הַנְּשָׁמָה אֶת כְּבוֹד הָאַסְפַּקְלַרְיָה שֶׁל שְׁכִינַת רִבּוֹנוֹ, מְבָרֶכֶת וּמִשְׁתַּחֲוָה לִפְנֵי הַקָּבָּ\"ה. וְזֶהוּ שֶׁכָּתוּב (תהלים קד) בָּרְכִי נַפְשִׁי אֶת ה'.</p>\n<p>אָמַר רַבִּי עֲקִיבָא, הַקָּבָּ\"ה עוֹמֵד עָלָיו, וְהַנְּשָׁמָה פּוֹתַחַת וְאוֹמֶרֶת: ה' אֱלֹהַי גָּדַלְתָּ מְּאֹד וְגוֹ' כָּל הַפָּרָשָׁה, עַד הַסִּיּוּם שֶׁאוֹמֵר יִתַּמּוּ חַטָּאִים וְגוֹ'. וְעוֹד אָמַר רַבִּי עֲקִיבָא, וְלֹא זוֹ בִּלְבַד, אֶלָּא מְשַׁבַּחַת אוֹתוֹ עַל הַגּוּף שֶׁנִּשְׁאָר בָּעוֹלָם הַזֶּה, וְאוֹמֵר (שם קג) בָּרְכִי נַפְשִׁי אֶת ה' וְכָל קְרָבַי וְגוֹ'.</p>\n<p>וְהַקָּבָּ\"ה הוֹלֵךְ. מִנַּיִן לָנוּ זֶה? מֵהַפָּסוּק הַזֶּה שֶׁכָּתוּב וַיֵּרָא אֵלָיו ה' בְּאֵלֹנֵי מַמְרֵא. זֶה יַעֲקֹב. מַה זֶּה מַמְרֵא? מִשּׁוּם שֶׁיָּרַשׁ מָאתַיִם עוֹלָמוֹת מֵעֵדֶן, וְהוּא כִסֵּא. אָמַר רַבִּי יִצְחָק, מַמְרֵא בְּגִימַטְרִיָּא מָאתַיִם שְׁמוֹנִים וְאַחַת הָיָה. מָאתַיִם שֶׁל עֵדֶן, שֶׁכָּתוּב (שיר ח) וּמָאתַיִם לְנֹטְרִים אֶת פִּרְיוֹ, וּשְׁמוֹנִים וְאַחַת שֶׁהוּא כִּסֵּא. וְלָכֵן נִקְרָא וַיֵּרָא אֵלָיו ה' בְּאֵלֹנֵי מַמְרֵא. וְעַל שֵׁם זֶה נִקְרָא מַמרֵא.</p>\n<p>אָמַר רַבִּי יְהוּדָה, מַה זֶּה בְּאֵלֹנֵי? רְצוֹנוֹ לוֹמַר חָזְקוֹ, זֶהוּ שֶׁכָּתוּב אֲבִיר יַעֲקֹב. וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל, זֶהוּ שֶׁכָּתוּב (תהלים טו) ה' מִי יָגוּר בְּאָהֳלֶךְ וְגוֹ'. כְּחֹם הַיּוֹם, שֶׁכָּתוּב (מלאכי ג) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ.</p>\n<p>אָמַר רַבִּי יוֹחָנָן בֶּן זַכַּאי, בְּאוֹתָהּ שָׁעָה הָלַךְ הַקָּבָּ\"ה, וּמִשּׁוּם שֶׁשּׁוֹמְעִים הָאָבוֹת, אַבְרָהָם יִצְחָק, שֶׁהַקָּבָּ\"ה הוֹלֵךְ אֵלָיו, תּוֹבְעִים מִיַּעֲקֹב לָלֶכֶת עִמָּם וּלְהַקְדִּים לוֹ שָׁלוֹם,</p>\n<p>וְהֵם עוֹמְדִים עָלָיו, מִמַּה שֶּׁכָּתוּב וַיִּשָּׂא עֵינָיו וַיַּרְא וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים נִצָּבִים עָלָיו. שְׁלֹשָׁה אֲנָשִׁים (שעומדים) אֵלּוּ הָאָבוֹת, אַבְרָהָם יִצְחָק וְיַעֲקֹב, שֶׁעוֹמְדִים עָלָיו וְרָאוּ מַעֲשִׂים טוֹבִים (שעשה) שֶׁעוֹשִׂים. וַיַּרְא וַיָּרָץ לִקְרָאתָם מִפֶּתַח הָאֹהֶל וַיִּשְׁתַּחוּ אַרְצָה, מִשּׁוּם שֶׁרָאָה שְׁכִינַת הַכָּבוֹד עִמָּם. זֶהוּ שֶׁכָּתוּב (שיר א) עַל כֵּן עֲלָמוֹת אֲהֵבוּךְ (אלו הן האבות).</p>\n<p>דָּבָר אַחֵר וַיֵּרָא אֵלָיו ה' בְּאֵלֹנֵי מַמְרֵא, רַבּוֹתֵינוּ פָּתְחוּ בַּפָּסוּק הַזֶּה בִּשְׁעַת פְּטִירָתוֹ שֶׁל אָדָם. שֶׁשָּׁנִינוּ, אָמַר רַבִּי יְהוּדָה, בִּשְׁעַת פְּטִירָתוֹ שֶׁל אָדָם הוּא יוֹם הַדִּין הַגָּדוֹל, שֶׁהַנְּשָׁמָה מִתְפָּרֶדֶת מִן הַגּוּף. וְלֹא נִפְטָר אָדָם מִן הָעוֹלָם עַד שֶׁרוֹאֶה אֶת הַשְּׁכִינָה. זֶהוּ שֶׁכָּתוּב (שמות לג) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי. וּבָאִים עִם הַשְּׁכִינָה שְׁלֹשָׁה מַלְאֲכֵי הַשָּׁרֵת לְקַבֵּל נִשְׁמָתוֹ שֶׁל צַדִּיק. זֶהוּ שֶׁכָּתוּב וַיֵּרָא אֵלָיו ה' וְגוֹ'. כְּחֹם הַיּוֹם - זֶה יוֹם הַדִּין הַבּוֹעֵר כַּתַּנּוּר לְהַפְרִיד אֶת הַנְּשָׁמָה מִן הַגּוּף.</p>\n<p>וַיִּשָּׂא עֵינָיו וַיַּרְא וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים, הַמְבַקְּרִים מַעֲשָׂיו מַה שֶּׁעָשָׂה, וְהוּא מוֹדֶה עֲלֵיהֶם בְּפִיו. וְכֵיוָן שֶׁהַנְּשָׁמָה רוֹאָה כָּךְ, יוֹצֵאת מִן הַגּוּף עַד פֶּתַח בֵּית הַבְּלִיעָה, וְעוֹמֶדֶת שָׁם עַד שֶׁמִּתְוַדָּה כָּל מַה שֶּׁעָשָׂה הַגּוּף עִמָּהּ בָּעוֹלָם הַזֶּה. וְאָז נִשְׁמַת הַצַּדִּיק הִיא שְׂמֵחָה בְּמַעֲשֶׂיהָ וּשְׂמֵחָה עַל פִּקְדוֹנָהּ. שֶׁשָּׁנִינוּ, אָמַר רַבִּי יִצְחָק, נִשְׁמָתוֹ שֶׁל צַדִּיק מִתְאַוָּה אֵימָתַי תֵּצֵא מִן הָעוֹלָם הַזֶּה שֶׁהוּא הֶבֶל כְּדֵי לְהִתְעַנֵּג בָּעוֹלָם הַבָּא.</p>"],[9522011218,"<p>שָׁנוּ רַבּוֹתֵינוּ, כְּשֶׁחָלָה רַבִּי אֱלִיעֶזֶר הַגָּדוֹל, אוֹתוֹ יוֹם עֶרֶב שַׁבָּת הָיָה, וְהוֹשִׁיב לִימִינוֹ אֶת הוֹרְקְנוּס בְּנוֹ, וְהָיָה מְגַלֶּה לוֹ עֲמֻקּוֹת וְנִסְתָּרוֹת, וְהוּא לֹא הָיָה מְקַבֵּל דָּבָר בְּדַעְתּוֹ שֶׁחָשַׁב שֶׁמְּטֹרָף בְּדַעְתּוֹ הָיָה. כֵּיוָן שֶׁרָאָה שֶׁדַּעַת אָבִיו מִתְיַשֶּׁבֶת עָלָיו, קִבֵּל מִמֶּנּוּ מֵאָה שְׁמוֹנִים וְתֵשַׁע סוֹדוֹת עֶלְיוֹנִים.</p>\n<p>כְּשֶׁהִגִּיעַ לְאַבְנֵי שַׁיִשׁ שֶׁמִּתְעָרְבִים בַּמַּיִם הָעֶלְיוֹנִים, בָּכָה רַבִּי אֱלִיעֶזֶר וּפָסַק לוֹמַר. אָמַר, עֲמֹד שָׁם בְּנִי. אָמַר לוֹ, אַבָּא, לָמָּה? אָמַר לוֹ, אֲנִי רוֹאֶה שֶׁאֲנִי מְמַהֵר לַחֲלֹף מִן הָעוֹלָם. אָמַר לוֹ, לֵךְ וֶאֱמֹר לְאִמְּךְ שֶׁתַּעֲלֶה אֶת הַתְּפִלִּין שֶׁלִּי לְמָקוֹם עֶלְיוֹן, וְאַחַר שֶׁאֶסְתַּלֵּק מִן הָעוֹלָם, וְאָבֹא לְכָאן כְּדֵי לִרְאוֹת אוֹתָם. לֹא תִבְכּוּ, שֶׁהֵם קְרוֹבִים עֶלְיוֹנִים וְלֹא תַחְתּוֹנִים, וְדַעַת בְּנֵי אָדָם לֹא מַשִּׂיגָה אוֹתָם.</p>\n<p>עֵד שֶׁהָיוּ יוֹשְׁבִים, נִכְנְסוּ חַכְמֵי הַדּוֹר לְבַקֵּר אוֹתָם, וְקִלֵּל אוֹתָם עַל שֶׁלֹּא בָאוּ לְשַׁמֵּשׁ אוֹתוֹ, שֶׁשָּׁנִינוּ, גְּדוֹלָה שִׁמּוּשָׁהּ יוֹתֵר מִלִּמּוּדָהּ. עַד שֶׁבָּא רַבִּי עֲקִיבָא, אָמַר לוֹ, עֲקִיבָא, עֲקִיבָא, לָמָּה לֹא בָאתָ לְשַׁמֵּשׁ אוֹתִי (שהרי באה העת להצרף)? אָמַר לוֹ, רַבִּי, לֹא הָיָה לִי פְּנַאי. רָתַח וְאָמַר, אֶתְמַהּ עָלֶיךְ אִם תָּמוּת מִיתַת עַצְמְךְ. קִלְּלוֹ שֶׁמִּיתָתוֹ תִּהְיֶה קָשָׁה מִכֻּלָּם.</p>\n<p>בָּכָה רַבִּי עֲקִיבָא וְאָמַר לוֹ, רַבִּי, תְּלַמֵּד אוֹתִי תּוֹרָה. פָּתַח פִּיו רַבִּי אֱלִיעֶזֶר בְּמַעֲשֵׂה מֶרְכָּבָה. בָּאָה אֵשׁ וְהִקִּיפָה אֶת שְׁנֵיהֶם. אָמְרוּ חֲכָמִים, נִשְׁמָע מִזֶּה שֶׁאֵין אָנוּ רְאוּיִים וּכְדָאִים לְכָךְ. יָצְאוּ לַפֶּתַח הַחִיצוֹן וְיָשְׁבוּ שָׁם. הָיָה מַה שֶּׁהָיָה, וְהָאֵשׁ הָלְכָה.</p>\n<p>וְלִמֵּד בְּבַהֶרֶת עַזָּה שְׁלֹשׁ מֵאוֹת הֲלָכוֹת פְּסוּקוֹת, וְלִמֵּד אוֹתוֹ מָאתַיִם וְשִׁשָּׁה עָשָּׂר טְעָמִים שֶׁל פְּסוּקֵי שִׁיר הַשִּׁירִים, וְהָיוּ עֵינֵי רַבִּי עֲקִיבָא זוֹלְגוֹת דְּמָעוֹת, וְחָזְרָה הָאֵשׁ כְּבַתְּחִלָּה. כְּשֶׁהִגִּיעַ לְפָסוּק (שיר ב) סַמְּכוּנִי בָּאֲשִׁישׁוֹת רַפְּדוּנִי בַּתַּפּוּחִים כִּי חוֹלַת אַהֲבָה אָנִי, לֹא יָכֹל רַבִּי עֲקִיבָא לִסְבֹּל, וְהֵרִים קוֹלוֹ בִּבְכִיָּה. וְהֵרִים קוֹלוֹ וְלֹא הָיָה מְדַבֵּר מִיִּרְאַת הַשְּׁכִינָה שֶׁהָיְתָה שָׁם.</p>\n<p>הוֹרָה לוֹ כָּל עֲמֻקּוֹת וְסוֹדוֹת עֶלְיוֹנִים שֶׁהָיוּ בְּשִׁיר הַשִּׁירִים, וְהִשְׁבִּיעוֹ שְׁבוּעָה שֶׁלֹּא יִשְׁתַּמֵּשׁ בְּשׁוּם פָּסוּק מִמֶּנּוּ, כְּדֵי שֶׁהַקָּבָּ\"ה לֹא יַחֲרִיב אֶת הָעוֹלָם בִּגְלָלוֹ, וְלֹא רוֹצֶה לְפָנָיו שֶׁהַבְּרִיּוֹת יִשְׁתַּמְּשׁוּ בוֹ מֵרֹב הַקְּדֻשָּׁה שֶׁיֵּשׁ בּוֹ. אַחַר יָצָא רַבִּי עֲקִיבָא וּבָכָה, וְנָבְעוּ עֵינָיו מַיִם, וְהָיָה אוֹמֵר, וַי רַבִּי! וַי רַבִּי! שֶׁהָעוֹלָם נִשְׁאָר יָתוֹם מִמְּךְ. נִכְנְסוּ אֵלָיו כָּל שְׁאָר הַחֲכָמִים, וְשָׁאֲלוּ אוֹתוֹ, וְהֵשִׁיב לָהֶם.</p>\n<p>הָיְתָה דְחוּקָה לוֹ (השעה) לְרַבִּי אֱלִיעֶזֶר. הוֹצִיא שְׁתֵּי זְרוֹעוֹתָיו וְשָׂם אוֹתָם עַל לִבּוֹ. פָּתַח וְאָמַר, אוֹי הָעוֹלָם, הָעוֹלָם הָעֶלְיוֹן חוֹזֵר לְהִתְכַּנֵּס וּלְהִגָּנֵז מִן הַתַּחְתּוֹן כָּל אוֹר וּמָאוֹר. אוֹי לָכֶם שְׁתֵּי זְרוֹעוֹת, אוֹי לָכֶם שְׁתֵּי תוֹרוֹת שֶׁיִּהְיוּ נִשְׁכָּחִים הַיּוֹם הַזֶּה מִן הָעוֹלָם. שֶׁאָמַר רַבִּי יִצְחָק, כָּל יְמֵי רַבִּי אֱלִיעֶזֶר הָיְתָה הַשְּׁמוּעָה מְאִירָה מִפִּיו כַּיּוֹם שֶׁנִּתְּנָה בְּהַר סִינַי.</p>\n<p>אָמַר, תּוֹרָה (למדתי וגמרא) הֵבַנְתִּי וְחָכְמָה לָמַדְתִּי וְשִׁמּוּשׁ עָשִׂיתִי, שֶׁאִלּוּ יִהְיוּ כָּל בְּנֵי אֱנוֹשׁ שֶׁל הָעוֹלָם סוֹפְרִים, לֹא יוּכְלוּ לִכְתֹּב, וְלֹא חָסְרוּ תַלְמִידַי מֵחָכְמָתִי אֶלָּא כְּמִכְחוֹל בְּעַיִן, וַאֲנִי מֵרַבּוֹתַי אֶלָּא כְּמִי שֶׁשּׁוֹתֶה בַּיָּם. וְלֹא הָיָה אֶלָּא לְהַחֲזִיק טוֹבָה לְרַבּוֹתָיו יוֹתֵר מִמֶּנּוּ.</p>\n<p>וְהָיוּ שׁוֹאֲלִים מִמֶּנּוּ בְּאוֹתוֹ סַנְדָּל שֶׁל יִבּוּם, עַד שֶׁיָּצְאָה נִשְׁמָתוֹ וְאָמַר טָהוֹר. וְלֹא הָיָה שָׁם רַבִּי עֲקִיבָא. כְּשֶׁיָּצְאָה הַשַּׁבָּת, מָצָא אוֹתוֹ רַבִּי עֲקִיבָא שֶׁמֵּת. קָרַע בִּגְדּוֹ וְשָׂרַט כָּל בְּשָׂרוֹ, וְדָם יָרַד וְנִמְשַׁךְ עַל זְקָנוֹ. הָיָה צוֹוֵחַ וּבוֹכֶה. יָצָא הַחוּצָה וְאָמַר: שָׁמַיִם שָׁמַיִם, אִמְרוּ לַשֶּׁמֶשׁ וְלַלְּבָנָה, שֶׁהָאוֹר שֶׁהָיָה מֵאִיר יוֹתֵר מֵהֶם הֲרֵי נֶחְשַׁךְ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בְּשָׁעָה שֶׁנִּשְׁמַת הַצַּדִּיק רוֹצָה לָצֵאת - שְׂמֵחָה, וְהַצַּדִּיק בָּטוּחַ בְּמִיתָתוֹ כְּדֵי לְקַבֵּל שְׂכָרוֹ. זֶהוּ שֶׁכָּתוּב וַיַּרְא וַיָּרָץ לִקְרָאתָם, בְּשִׂמְחָה לְקַבֵּל פְּנֵיהֶם. מֵאֵיזֶה מָקוֹם? מִפֶּתַח הָאֹהֶל, כְּמוֹ שֶׁאָמַרְנוּ. וַיִּשְׁתַּחוּ אָרְצָה - אֶל הַשְּׁכִינָה.</p>\n<p>רַבִּי יוֹחָנָן פָּתַח וְאָמַר, (שיר ב) עַד שֶׁיָּפוּחַ הַיּוֹם וְנָסוּ הַצְּלָלִים סֹב דְּמֵה לְךְ דוֹדִי לִצְבִי אוֹ לְעֹפֶר הָאַיָּלִים. עַד שֶׁיָּפוּחַ הַיּוֹם וְגוֹ' - זוֹ אַזְהָרָה לָאָדָם בְּעוֹדוֹ בָּעוֹלָם הַזֶּה שֶׁהוּא כְּהֶרֶף עַיִן. בּא רְאֵה מַה כָּתוּב, (קהלת ו) וְאִלּוּ חָיָה אֶלֶף שָׁנִים פַּעֲמַיִם וְגוֹ'. בְּיוֹם הַמִּיתָה, כָּל מַה שֶּׁחָיָה, נֶחְשָׁב כְּיוֹם אֶחָד אֶצְלוֹ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, נִשְׁמָתוֹ שֶׁל אָדָם מַתְרָה בּוֹ וְאוֹמֶרֶת עַד שֶׁיָּפוּחַ הַיּוֹם (ונסו הצללים), וְיִדְמֶה בְעֵינֶיךְ כְּהֶרֶף עַיִן בְּעוֹדְךְ בָּעוֹלָם הַזֶּה. וְנָסוּ הַצְּלָלִים, זֶהוּ שֶׁכָּתוּב (איוב ח) כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ. בְּבַקָּשָׁה מִמְּךְ, סֹב דְּמֵה לְךְ דוֹדִי לִצְבִי וְגוֹ'.</p>\n<p>דָּבָר אַחֵר עַד שֶׁיָּפוּחַ הַיּוֹם וְגוֹ' - אָמַר רַבִּי שִׁמְעוֹן בֶּן פַּזִּי, זוֹ אַזְהָרָה לָאָדָם בְּעוֹדוֹ בָּעוֹלָם הַזֶּה שֶׁהוּא כְּהֶרֶף עַיִן: מָה הַצְּבִי קַל בְּרַגְלָיו - אַף אַתָּה הֱיֵה קַל כַּצְּבִי אוֹ כְּעֹפֶר הָאַיָּלִים לַעֲשׂוֹת רְצוֹן בּוֹרַאֲךְ כְּדֵי שֶׁתִּנְחַל הָעוֹלָם הַבָּא, שֶׁהוּא הָרֵי בְשָׂמִים, הַנִּקְרָא הַר ה', הַר הַתַּעֲנוּג, הָהָר הַטּוֹב. ע\"כ מדרש הנעלם.</p>"],[9522011219,"<p>מֶמְשֶׁלֶת הַמֶּלֶךְ נִרְאֵית בִּשְׁלֹשָׁה גְוָנִים, גָּוֶן אֶחָד - מַרְאֶה שֶׁנִּרְאֶה לָעַיִן מֵרָחוֹק, וְאֵין הָעַיִן יְכוֹלָה לַעֲמֹד בַּבֵּרוּר שֶׁרוֹאָה, מִשּׁוּם שֶׁהוּא מֵרָחוֹק, עַד שֶׁנּוֹטֶלֶת הָעַיִן מַרְאֶה קָטָן בַּקִּמּוּץ שֶׁלָּהּ, וְעַל זֶה כָּתוּב (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי.</p>\n<p>גָּוֶן שֵׁנִי - מַרְאֶה שֶׁל הָעַיִן הַזֹּאת [נ\"א: של אחד] בַּסֵּתֶר שֶׁלָּהּ, שֶׁאֵין הַגָּוֶן הַזֶּה נִרְאֶה לָעַיִן, רַק בְּסֵתֶר קָטָן, שֶׁתּוֹפֵס וְלֹא עוֹמֵד בְּבֵרוּר, סוֹתֵם הָעַיִן וּפוֹתֵחַ מְעַט וְלוֹקֵחַ אוֹתוֹ הַמַּרְאֶה. וְהַגָּוֶן הַזֶּה [נ\"א: הגון וזה] צָרִיךְ לְפִתְרוֹן לַעֲמֹד עַל מַה שֶּׁלּוֹקַחַת הָעַיִן, וְעַל זֶה כָּתוּב (שם א) מָה אַתָּה רֹאֶה.</p>\n<p>הַגָּוֶן הַשְּׁלִישִׁי הוּא זֹהַר הָאַסְפַּקְלַרְיָה הַמְּאִירָה שֶׁלֹּא נִרְאֶה בוֹ כְּלָל, חוּץ מִגִּלְגּוּל הָעַיִן כַּאֲשֶׁר הוּא סָתוּם בִּסְתִימוּת וּמְגַלְגְּלִים לוֹ בְּגִלְגּוּל וְנִרְאֶה בַגִּלְגּוּל הַזֶּה אַסְפַּקְלַרְיָה הַמְּאִירָה. וְלֹא יָכוֹל לַעֲמֹד בְּאוֹתוֹ הַגָּוֶן, רַק שֶׁרוֹאֶה זהַר מֵאִיר בְּסֵתֶר הָעַיִן,</p>\n<p>וְעַל זֶה כָּתוּב (יחזקאל לז) הָיְתָה עָלַי יַד ה', (שם לג) [ויד ה' היתה עלי] וְיַד ה' עָלַי חֲזָקָה. וְכֻלָּם מְפֹרָשִׁים מִנְּבִיאֵי הָאֱמֶת, פְּרָט לְמֹשֶׁה הַנֶּאֱמָן הָעֶלְיוֹן שֶׁזָּכָה לְהִסְתַּכֵּל לְמַעְלָה בְּמַה שֶּׁלֹּא נִרְאֶה כְּלָל. עָלָיו כָּתוּב (במדבר יב) לֹא כֵן עַבְדִּי מֹשֶׁה וְגוֹ'.</p>\n<p>וַיֵּרָא אֵלָיו, נִרְאֲתָה וְנִתְגַּלְּתָה לִי הַשְּׁכִינָה תּוֹךְ אוֹתָן דְּרָגוֹת שֶׁהִתְחַבְּרוּ בְּצִדּוֹ, מִיכָאֵ\"ל לְצַד יָמִין, גַּבְרִיאֵ\"ל לְצַד שְׂמֹאל, רְפָאֵ\"ל לְפָנִים, אוֹרִיאֵ\"ל לְאָחוֹר, וְעַל זֶה נִגְלְתָה עָלָיו הַשְּׁכִינָה בָּאֲלוֹנִים [נ\"א: צלמים] הַלָּלוּ שֶׁל הָעוֹלָם, כְּדֵי לְהַרְאוֹת לִפְנֵיהֶם בְּרִית [ד\"א רשם ראשון] הַקֹּדֶשׁ שֶׁהָיְתָה בְּכָל הָעוֹלָם בְּסוֹד הָאֱמוּנָה.</p>\n<p>וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל. מַה זֶּה פֶּתַח הָאֹהֶל? זֶה הַמָּקוֹם שֶׁנִּקְרָא בְּרִית, סוֹד הָאֱמוּנָה. כְּחֹם הַיּוֹם, זֶה הַסּוֹד שֶׁנִּדְבַּק בּוֹ אַבְרָהָם, הַחֹזֶק שֶׁל צַד הַיָּמִין, הַדַּרְגָּה שֶׁלּוֹ.</p>\n<p>פֶּתַח הָאֹהֶל - סוֹד הַשַּׁעַר שֶׁל צֶדֶק פֶּתַח הָאֱמוּנָה, שֶׁאָז נִכְנַס בּוֹ אַבְרָהָם בְּאוֹתוֹ הָרֹשֶׁם הַקָּדוֹשׁ. כְּחֹם הַיּוֹם - זֶהוּ צַדִּיק, הַדַּרְגָּה שֶׁל חִבּוּר אֶחָד שֶׁנִּכְנָס בּוֹ מִי שֶׁנִּמּוֹל וְנִרְשַׁם בּוֹ הָרֹשֶׁם הַקָּדוֹשׁ, שֶׁהֲרֵי נִתְבַּטֵּל מִן הָעָרְלָה וְנִכְנַס בַּקִּיּוּם שֶׁל שְׁתֵּי הַדְּרָגוֹת הַלָּלוּ שֶׁהֵן סוֹד הָאֱמוּנָה.</p>\n<p>וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים וְגוֹ' - אֵלּוּ שְׁלֹשָׁה אֲנָשִׁים שְׁלוּחִים שֶׁמִּתְלַבְּשִׁים בָּאֲוִיר, וְיוֹרְדִים לָעוֹלָם הַזֶּה [ונראים] בְּמַרְאֶה שֶׁל בֶּן אָדָם, וְהַשְּׁלֹשָׁה הֵם כְּמוֹ שֶׁלְּמַעְלָה, מִשּׁוּם שֶׁהַקֶּשֶׁת לֹא נִרְאֵית אֶלָּא בִּשְׁלֹשָׁה גְוָנִים - לָבָן, אָדם וְיָרֹק, וְכָךְ הוּא בְּוַדַּאי.</p>\n<p>וּשְׁלשֶת הָאֲנָשִׁים הַלָּלוּ שְׁלֹשָׁה גְוָנִים. גָּוֶן לָבָן, גָּוֶן אָדם, גָּוֶן יָרֹק (רחמים). הַגָּוֶן הַלָּבָן זֶה מִיכָאֵ\"ל, שֶׁהוּא צַד הַיָּמִין. הַגָּוֶן הָאָדם זֶה גַּבְרִיאֵ\"ל, הַצַּד שֶׁל הַשְּׂמֹאל. הַגָּוֶן הַיָּרֹק זֶה רְפָאֵ\"ל. וְאֵלּוּ הֵם שְׁלֹשֶׁת גּוֹנֵי הַקֶּשֶׁת, שֶׁאֵין הַקֶּשֶׁת נִרְאֵית אֶלָּא עִמָּהֶם. וּמִשּׁוּם כָּךְ וַיֵּרָא אֵלָיו, גִּלּוּי שְׁכִינָה בִּשְׁלֹשֶׁת הַגְּוָנִים הַלָּלוּ.</p>\n<p>וְאֶת כֻּלָּם הִצְטָרְכוּ. אֶחָד לְרַפֵּא אֶת הַמִּילָה, וְזֶהוּ רְפָאֵל, בַּעַל הָרְפוּאוֹת. וְאֶחָד לְבַשֵּׂר אֶת שָׂרָה עַל הַבֵּן, וְזֶהוּ מִיכָאֵל, מִשּׁוּם שֶׁהוּא הִתְמַנָּה לַיָּמִין, וְכָל הַטּוֹבוֹת וְהַבְּרָכוֹת שֶׁבְּיָדוֹ נִמְסְרוּ מִצַּד הַיָּמִין.</p>\n<p>וְאֶחָד לַהֲפֹךְ אֶת סְדוֹם, וְזֶהוּ גַבְרִיאֵל שֶׁהוּא לִשְׂמֹאל, וְהוּא מְמֻנֶּה עַל כָּל הַדִּינִים שֶׁל הָעוֹלָם מִצַּד (הדין) הַשְּׂמֹאל לָדוּן וְלַעֲשׂוֹת עַל יְדֵי מַלְאַךְ הַמָּוֶת, שֶׁהוּא בַּעַל הַהֶרֶג שֶׁל בֵּית הַמֶּלֶךְ.</p>\n<p>וְכֻלָּם עָשׂוּ שְׁלִיחוּתָם, וְכָל אֶחָד וְאֶחָד כָּרָאוּי לוֹ. וְהַמַּלְאָךְ גַּבְרִיאֵ\"ל בִּשְׁלִיחוּת לַנְּשָׁמָה הַקְּדוֹשָׁה, וּמַלְאַךְ הַמָּוֶת בִּשְׁלִיחוּתוֹ לַנֶּפֶשׁ שֶׁל הַיֵּצֶר הָרָע. וְעִם כָּל זֶה הַנְּשָׁמָה הַקְּדוֹשָׁה לֹא יוֹצֵאת עַד שֶׁרוֹאָה שְׁכִינָה.</p>\n<p>כְּשֶׁרָאָה אוֹתָם מְחֻבָּרִים כְּאֶחָד, אָז רָאָה שְׁכִינָה [כמו זה] בִּגְוָנֶיהָ וְהִשְׁתַּחֲוָה, שֶׁכָּתוּב (בראשית לג) וַיִּשְׁתַּחוּ אָרְצָה, כְּמוֹ אֵצֶל יַעֲקֹב שֶׁנֶּאֱמַר (שם מז) וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה, לַשְּׁכִינָה.</p>\n<p>וּלְגַבֵּי הַשְּׁכִינָה אָמַר בְּשֵׁם אדנ\"י, וּלְגַבֵּי הַצַּדִּיק אָדוֹ\"ן, שֶׁהֲרֵי אָז נִקְרָא אֲדוֹן כָּל הָאָרֶץ כְּשֶׁמּוּאֶרֶת מִצַּדִּיק וּמוּאֶרֶת בִּגְוָנֶיהָ, שֶׁהֲרֵי מִשּׁוּם [זהו כזה אז] זֶה נִשְׁלָם לְמַעְלָה.</p>\n<p>מִכָּאן שֶׁמַּרְאֶה שֶׁלְּמַטָּה מוֹשֵׁךְ הַמְשָׁכָה מִלְמַעְלָה, שֶׁהֲרֵי הַגְּוָנִים הַלָּלוּ מוֹשְׁכִים הַמְשָׁכָה מִלְמַעְלָה מֵאוֹתָם מְקוֹרוֹת עֶלְיוֹנִים. אדנ\"י מוֹשֵׁךְ מִלְמַעְלָה בִּשְׁלֹשֶׁת הַגְּוָנִים הַלָּלוּ שֶׁמִּתְלַבֵּשׁ בָּהֶם, וּבָהֶם נוֹטֶלֶת כָּל מַה שֶׁנּוֹטֶלֶת מִלְמַעְלָה.</p>\n<p>וּמִשּׁוּם שֶׁהֵם חִבּוּר שֶׁלָּהּ וְתוֹמְכִים שֶׁלָּהּ בַּכֹּל, נֶאֱמַר שֵׁם אדנ\"י, שֶׁהֲרֵי שֵׁם זֶה הִתְגַּלָּה לוֹ כָּלוּל בְּסוֹדוֹת עֶלְיוֹנִים, הִתְגַּלָּה לוֹ בְּגִלּוּי מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָכֵן כְּשֶׁלֹּא הָיָה מָהוּל. וְעַד שֶׁנִּמּוֹל, לֹא רצָה הַקָּבָּ\"ה לְהוֹצִיא מִמֶּנּוּ קָדוֹשׁ. כֵּיוָן שֶׁנִּמּוֹל, מִיָּד יָצָא מִמֶּנּוּ הַזֶּרַע הַקָּדוֹשׁ.</p>\n<p>וְלָכֵן הִתְגַּלְּתָה עָלָיו שְׁכִינָה בְּאוֹתָן דְּרָגוֹת קְדוֹשׁוֹת. (דניאל יב) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזֹהַר הָרָקִיעַ. זֹהַ\"ר זוֹהֵר שֶׁזּוֹהֲרִים בִּדְלֵקוּת שֶׁל זֹהַר. זֹהַ\"ר שֶׁמֵּאִיר שֶׁמַּדְלִיק וְנוֹצֵץ לְכַמָּה צְדָדִים.</p>\n<p>זֹהַ\"ר עוֹלֶה וְיוֹרֵד. זהַ\"ר נוֹצֵץ לְכָל עֵבֶר. זֹהַ\"ר שׁוֹפֵעַ וְיוֹצֵא. זֹהַ\"ר שֶׁלֹּא פוֹסֵק לְעוֹלָמִים. זֹהַ\"ר שֶׁעוֹשֶׂה תוֹלָדוֹת.</p>\n<p>זֹהַ\"ר טָמִיר וְגָנוּז, הִתְנוֹצְצוּת שֶׁל כָּל הַנִּיצוֹצִים וְכָל הַדְּרָגוֹת בּוֹ. יוֹצֵא וְטָמִיר. נִסְתָּר וְגָלוּי. נִרְאֶה וְלֹא נִרְאֶה. [זה\"ר] סֵפֶר זֶה מַעְיַן הַבְּאֵר, יוֹצֵא בַּיּוֹם, נִסְתָּר בַּלַּיְלָה, מִשְׁתַּעֲשֵׁעַ בַּחֲצוֹת הַלַּיְלָה בַּתּוֹלָדוֹת שֶׁהוֹצִיא.</p>\n<p>זֹהַ\"ר שֶׁזּוֹהֵר וּמֵאֵיר לַכֹּל, הַכְּלָל שֶׁל הַתּוֹרָה, וְזֶהוּ שֶׁנִּרְאֶה, וְכָל הַגְּוָנִים נִסְתָּרִים בּוֹ וְנִקְרָא בַּשֵּׁם שֶׁל אדנ\"י. שְׁלֹשָׁה גְוָנִים נִרְאִים לְמַטָּה מֵאֵלּוּ שְׁלֹשֶׁת הַגְּוָנִים שֶׁלְּמַעְלָה. מֵאֵלּוּ הָעֶלְיוֹנִים הַכֹּל נִמְשָׁךְ [לגבי זהר] [אותם העליונים, זהר] שֶׁלֹּא נִרְאֶה, וְנוֹצֵץ בִּשְׁנֵים עָשָׂר נִצְנוּצִים וּזְהָרִים שֶׁנּוֹצְצִים מִמֶּנּוּ. שְׁלֹשָׁה עָשָׂר הֵם בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ וְגוֹ', הַסּוֹד שֶׁל אֵין סוֹף נִקְרָא יהו\"ה.</p>\n<p>כַּאֲשֶׁר מִתְחַבֵּר זֹהַר תַּחְתּוֹן אדנ\"י בְּזֹהַר עֶלְיוֹן יהו\"ה, נַעֲשֶׂה שֵׁם נִסְתָּר שֶׁבּוֹ יוֹדְעִים נְבִיאֵי הָאֱמֶת וּמִסְתַּכְּלִים לְתוֹךְ הַ הַר הָעֶלְיוֹן, וְזֶה יְאֲהֹדוָנָהֵי, מַרְאוֹת טְמִירִים [חיות טמירות], שֶׁכָּתוּב (יחזקאל א) כְּעֵין הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ.</p>\n<p>מִשְׁנָה, עֶלְיוֹנִים גְּבוֹהִים טוֹבִים שֶׁל הַיָּמִין, תֵּשַׁע נְקֻדּוֹת שֶׁל הַתּוֹרָה יוֹצְאוֹת וְנֶחְלָקִים בָּאוֹתִיּוֹת, וְהָאוֹתִיּוֹת בָּהֶם נוֹסְעוֹת, [מטלטלים] מַסְעוֹתָיו דַּקִּיקִים בְּסוֹדוֹת. [היכל] חוֹלְקִים, אֵלּוּ תִּשְׁעַת הַשַּׁלִּיטִים עַל הָאוֹתִיּוֹת, הָאוֹתִיּוֹת הִתְפַּשְּׁטוּ מֵהֶם. נִשְׁאֲרוּ נְקוּדִים לְהַכְנִיסָם לָהֶם. לֹא נוֹסְעִים רַק כְּשֶׁאֵלֶּה יוֹצְאִים.</p>\n<p>הֵם בַּסּוֹד שֶׁל אֵין סוֹף. כָּל הָאוֹתִיּוֹת [נוסעות] מֻסָּעוֹת בַּסּוֹד שֶׁל אֵין סוֹף. כְּמוֹ שֶׁהֵם נוֹשְׂאִים אוֹתָם, כָּךְ הֵם נוֹסְעִים. אֵלּוּ הַנִּסְתָּרִים אוֹתִיּוֹת גְּלוּיוֹת וְלֹא גְלוּיוֹת. אֵלּוּ טְמִירִים עַל מַה שֶּׁשּׁוֹרוֹת הָאוֹתִיּוֹת.</p>\n<p>תִּשְׁעָה שֵׁמוֹת חֲקוּקוֹת עִם עֲשָׂרָה, וְהָרִאשׁוֹן אֶהְיֶה. [יו\"ד ה\"א] אֶהְיֶ\"ה אֲשֶׁר אֶהְיֶ\"ה, יהו\"ה, אֵ\"ל, אֱלֹהִי\"ם, יהו\"ה, צְבָאוֹת, אָדוֹ\"ן, שַׁדַּ\"י. [ומהשם הזה יו\"ד ה\"א וא\"ו ה\"א מתפשט כ\"ב אותיות, וסוד השם מנצפ\"ך הרי כ\"ז אותיות, וזהו סוד יהו\"ה אלהינ\"ו יהו\"ה אחד, יהו\"ה אלהינו יהו\"ה הרי י\"ד אותיות, אחד סוד י\"ג אותיות, ומהם יתפשטו רמ\"ח אברים, שם בן מ\"ב ושם בן ע\"ב מנצפ\"ך חמשה גבורות, וממנו יתפשט הסוד של חמשים שערי בינה, ומהם יתפשטו ע\"ב, הרי רמ\"ח איברים עם יי' אלהיכם אמת].</p>\n<p>אֵלֶּה הֵם עֲשָׂרָה שֵׁמוֹת חֲקוּקִים בְּצִדֵּיהֶם, וְכָל הַשֵּׁמוֹת הַלָּלוּ נֶחְקְקוּ מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵבָרִים וְנִכְנָסִים בַּאֲרוֹן הַבְּרִית הָאֶחָד, וּמִיהוּ? הַשֵּׁם שֶׁנִּקְרָא אדנ\"י. וְזֶה [ד\"א סוד] הִתְגַּלָּה עַכְשָׁו לְאַבְרָהָם. [נ\"א: יהו\"ה צבאו\"ת, ונ\"א א\"ל אדנ\"י].</p>\n<p>מִיכָאֵל שֵׁם הַיָּמִין שֶׁאוֹחֵז וּמְשַׁמֵּשׁ אֶת הַשֵּׁם הַזֶּה יוֹתֵר מֵאוֹתָם הָאֲחֵרִים. בְּכָל מָקוֹם שֶׁסּוֹד הַשֵּׁם הַזֶּה שָׁם - מִיכָאֵל שָׁם. אִם הִסְתַּלֵּק מִיכָאֵל הַזֶּה - מִסְתַּלֵּק אֱלֹהִים עִם שַׁדַּי.</p>\n<p>בַּהַתְחָלָה שְׁלֹשָׁה אֲנָשִׁים, וְהִתְגַּלְּמוּ בְּצִיּוּר שֶׁל אֲוִיר וְהָיוּ אוֹכְלִים, אוֹכְלִים וַדַּאי, שֶׁהָאֵשׁ שֶׁלָּהֶם אוֹכֶלֶת וּמְכַלָּה הַכֹּל וְעוֹשִׂים נַחַת רוּחַ לְאַבְרָהָם. הֵם אֵשׁ וַדַּאי, וְאוֹתָהּ הָאֵשׁ מִתְכַּסָּה בְּצִיּוּר שֶׁל אֲוִיר וְלֹא נִרְאֵית. וְאוֹתוֹ מַאֲכָל אֵשׁ לוֹהֶטֶת וְאוֹכֶלֶת אוֹתוֹ, וְאַבְרָהָם מְקַבֵּל נַחַת רוּחַ מזֶּה.</p>\n<p>כֵּיון שֶׁהִסְתַּלְּקָה הַשְּׁכִינָה מַה כָּתוּב? וַיַּעַל אֱלֹהִים מֵעַל אַבְרָהָם. מִיָּד מִסְתַּלֵּק עִמּוֹ מִיכָאֵל, שֶׁכָּתוּב וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדמָה וְגוֹ'. שְׁלֹשָׁה כָּתוּב בַּהַתְחָלָה, וְעַכְשָׁו שְׁנַיִם. אֶלָּא מִיכָאֵל שֶׁהוּא יָמִין הִסְתַּלֵּק עִם הַשְּׁכִינָה.</p>\n<p>הַמַּלְאָךָ שֶׁנִּרְאָה לְמָנוֹחַ יָרַד וְהִתְגַּלֵּם [לו] בָּאֲוִיר וְנִרְאָה לוֹ, וְזֶהוּ אוֹרִיאֵל. מַה שֶּׁלֹּא יָרַד עִם אֵלּוּ לְאַבְרָהָם - יָרַד כָּאן לְבַדּוֹ לְבַשֵּׂר לְמָנוֹחַ שֶׁבָּא מִדָּן.</p>\n<p>וּמִשּׁוּם שֶׁלֹּא חָשׁוּב כְּמוֹ אַבְרָהָם, לֹא כָתוּב שֶׁאָכַל, שֶׁהֲרֵי כָּתוּב (שופטים יג) אִם תַּעְצְרֵנִי לֹא אֹכַל בְּלַחְמֶךְ. וְכָתוּב, וַיְהִי בַעֲלוֹת הַלַּהַב מֵעַל הַמִּזְבֵּחַ, וַיַּעַל מַלְאַךְ ה' בְּלַהַב הַמִּזְבֵּחַ וְגוֹ'. וְכָאן וַיַּעַל אֱלֹהִים מֵעַל אַבְרָהָם. מִשּׁוּם שֶׁבּוֹ הִסְתַּלֵּק מִיכָאֵל, וְנִשְׁאֲרוּ רְפָאֵל וְגַבְרִיאֵל.</p>\n<p>וַעָלֵיהֶם כָּתוּב שְׁנֵי הַמַּלְאָכִים סְדמָה. בָּעֶרֶב - בְּשָׁעָה שֶׁהַדִּין תָּלוּי עַל הָעוֹלָם. אַחַר כָּךְ הִסְתַּלֵּק אֶחָד, וְנִמְצָא שֶׁגַּבְרִיאֵל לְבַדּוֹ. בִּזְכוּת אַבְרָהָם נִצַּל לוֹט, וְהוּא אַף כָּךְ זָכָה בָהֶם, וְעַל זֶה בָּאוּ אֵלָיו. (ע\"כ ס\"ת).</p>"],[9522011220,"<p>רַבִּי אַבָּא פָּתַח וְאָמַר, (תהלים כד) מִי יַעֲלֶה בְהַר ה' וּמִי יָקוּם בִּמְקוֹם קָדְשׁוֹ. בּא רְאֵה, כָּל בְּנֵי הָעוֹלָם לֹא רוֹאִים עַל מָה עוֹמְדִים בָּעוֹלָם, וְהַיָּמִים הוֹלְכִים וְעוֹלִים וְעוֹמְדִים לִפְנֵי הַקָּבָּ\"ה כָּל אוֹתָם יָמִים שֶׁבְּנֵי אָדָם עוֹמְדִים בָּהֶם בָּעוֹלָם הַזֶּה, שֶׁהֲרֵי כֻּלָּם נִבְרְאוּ וְכֻלָּם עוֹמְדִים לְמַעְלָה. וּמִנַּיִן לָנוּ שֶׁנִּבְרְאוּ? שֶׁכָּתוּב (שם קלט) יָמִים יֻצָּרוּ.</p>\n<p>וּכְשֶׁמַּגִּיעִים הַיָּמִים לְהֵעָלוֹת מִן הָעוֹלָם הַזֶּה, כֻּלָּם קְרֵבִים לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן. זֶהוּ שֶׁכָּתוּב (מלכים א ב) וַיִּקְרְבוּ יְמֵי דָוִד לָמוּת. וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת.</p>\n<p>מִשּׁוּם שֶׁכַּאֲשֶׁר בֶּן אָדָם הוּא בָּעוֹלָם הַזֶּה, אֵינוֹ מַשְׁגִּיחַ וְלֹא מִתְבּוֹנֵן עַל מַה הוּא עוֹמֵד, אֶלָּא כָּל יוֹם וָיוֹם חוֹשֵׁב כְּאִלּוּ הוּא הוֹלֵךְ בְּרֵיקָנוּת, שֶׁהֲרֵי כְּשֶׁהַנְּשָׁמָה יוֹצֵאת מִן הָעוֹלָם הַזֶּה, לֹא יוֹדַעַת לְאֵיזוֹ דֶרֶךְ מַעֲלִים אוֹתָהּ. שֶׁהֲרֵי הַדֶּרֶךְ לַעֲלוֹת לְמַעְלָה לְמָקוֹם שֶׁאוֹר הַנְּשָׁמוֹת הָעֶלְיוֹנוֹת מְאִירוֹת, לֹא נִתָּן לְכָל הַנְּשָׁמוֹת, שֶׁהֲרֵי כְּמוֹ שֶׁהוּא מַמְשִׁיךְ עָלָיו בָּעוֹלָם הַזֶּה, כָּךְ נִמְשָׁךְ לְאַחַר שֶׁיּוֹצֵא מִמֶּנּוּ.</p>\n<p>בֹּא רְאֵה, אִם בֶּן אָדָם נִמְשָׁךְ אַחַר הַקָּבָּ\"ה וּתְשׁוּקָתוֹ אַחֲרָיו בָּעוֹלָם הַזֶּה, אַחֲרֵי זֶה כְּשֶׁיּוֹצֵא מִמֶּנּוּ, הוּא נִמְשָׁךְ אַחֲרָיו, וְנוֹתְנִים לוֹ דֶּרֶךְ לַעֲלוֹת לְמַעְלָה אַחַר אוֹתָהּ מְשִׁיכָה שֶׁנִּמְשָׁךְ בְּרָצוֹן כָּל יוֹם בָּעוֹלָם הַזֶּה.</p>\n<p>אָמַר רַבִּי אַבָּא, יוֹם אֶחָד נִפְגַּשְׁתִּי בְּעִיר אַחַת מֵאוֹתָם שֶׁהָיוּ מִן בְּנֵי קֶדֶם, וְאָמְרוּ לִי מֵאוֹתָהּ חָכְמָה שֶׁהָיוּ יוֹדְעִים מִיָּמִים רִאשׁוֹנִים, וְהָיוּ מוֹצְאִים סְפָרִים שֶׁל הַחָכְמָה שֶׁלָּהֶם, וְקֵרְבוּ לִי סֵפֶר אֶחָד,</p>\n<p>וְהָיָה כָּתוּב בּוֹ, שֶׁכְּמוֹ שֶׁהָרָצוֹן שֶׁל הָאָדָם מִתְכַּוֵּן בּוֹ בָּעוֹלָם הַזֶּה, כָּךְ מַמְשִׁיךְ עָלָיו רוּחַ מִלְמַעְלָה כְּמוֹ אוֹתוֹ הָרָצוֹן שֶׁנִּדְבָּק בּוֹ. אִם רְצוֹנוֹ הִתְכַּוֵּן לְדָבָר עֶלְיוֹן קָדוֹשׁ, הוּא מַמְשִׁיךְ אוֹתוֹ הַדָּבָר מִלְמַעְלָה לְמַטָּה אֵלָיו.</p>\n<p>וְאִם רְצוֹנוֹ לְהִתְדַּבֵּק בַּצַּד הָאַחֵר וּמִתְכַּוֵּן בּוֹ, הוּא מַמְשִׁיךְ אֶת אוֹתוֹ הַדָּבָר מִלְמַעְלָה לְמַטָּה אֵלָיו. וְהָיוּ אוֹמְרִים שֶׁעִקַּר הַדָּבָר תָּלוּי בְּדִבּוּרִים וּבְמַעֲשֶׂה וּבְרָצוֹן לְהִתְדַּבֵּק, וּבָזֶה נִמְשָׁךְ מִלְמַעְלָה לְמַטָּה אוֹתוֹ הַצַּד שֶׁנִּדְבָּק בּוֹ.</p>\n<p>וּמָצָאנוּ בוֹ כָּל אוֹתָם מַעֲשִׂים וַעֲבוֹדוֹת הַכּוֹכָבִים וְהַמַּזָּלוֹת וּדְבָרִים שֶׁהִצְטָרְכוּ לָהֶם, וְאֵיךְ הָרָצוֹן לְהִתְכַּוֵּן בָּהֶם כְּדֵי לִמְשֹׁךְ אוֹתָם אֲלֵיהֶם.</p>\n<p>כְּמוֹ זֶה מִי שֶׁרוֹצֶה לְהִדָּבֵק לְמַעְלָה בְּרוּחַ הַקֹּדֶשׁ, שֶׁהֲרֵי בְּמַעֲשֶׂה וּבְדִבּוּרִים וּבִרְצוֹן הַלֵּב לְכַוֵּן בְּאוֹתוֹ הַדָּבָר תָּלוּי הַדָּבָר לִמְשֹׁךְ אוֹתוֹ אֵלָיו מִלְמַעְלָה לְמַטָּה וּלְהִדָּבֵק בְּאוֹתוֹ הַדָּבָר.</p>\n<p>וְהָיוּ אוֹמְרִים, כְּמוֹ שֶׁבֶּן אָדָם נִמְשַׁךְ בָּעוֹלָם הַזֶּה - כָּךְ גַּם מוֹשְׁכִים אוֹתוֹ כְּשֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה. וּבַמֶּה שֶׁנִּדְבַּק בָּעוֹלָם הַזֶּה וְנִמְשַׁךְ אַחֲרָיו - כָּךְ נִדְבָּק בְּאוֹתוֹ הָעוֹלָם. אִם בְּקֹדֶשׁ - בְּקֹדֶשׁ, וְאִם בְּטֻמְאָה - בְּטֻמְאָה.</p>\n<p>אִם בְּקֹדֶשׁ, מוֹשְׁכִים אוֹתוֹ לְאוֹתוֹ הַצַּד וְנִדְבָּק בּוֹ לְמַעְלָה וְנַעֲשֶׂה מְמֻנֶּה שַׁמָּשׁ לְשַׁמֵּשׁ לִפְנֵי הַקָּבָּ\"ה בֵּין אוֹתָם שְׁאָר מַלְאָכִים. כְּמוֹ שֶׁכָּךְ נִדְבָּק לְמַעְלָה וְעוֹמֵד בֵּין אוֹתָם קְדוֹשִׁים, שֶׁכָּתוּב (זכריה ג) וְנָתַתִּי לְךְ מַהְלְכִים בֵּין הָעֹמְדִים הָאֵלֶּה.</p>\n<p>כָּךָ גַּם כְּמוֹ זֶה. אִם בְּטֻמְאָה, מוֹשְׁכִים אוֹתוֹ לְאוֹתוֹ הַצַּד וְנַעֲשֶׂה כְּאֶחָד מֵהֶם לְהִדָּבֵק עִמָּם, וְהֵם נִקְרָאִים נִזְקֵי בְּנֵי אָדָם. וּבְאוֹתָהּ שָׁעָה שֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה, לוֹקְחִים אוֹתוֹ וְשׁוֹאֲבִים אוֹתוֹ לַגֵּיהִנֹּם בְּאוֹתוֹ מָקוֹם שֶׁדָּנִים אֶת בְּנֵי הַטֻּמְאָה שֶׁטִּמְאוּ עַצְמָם וְרוּחָם, וְאַחַר כָּךְ נִדְבָּק בָּהֶם, וְהוּא מַזִּיק כְּאֶחָד מֵאוֹתָם מַזִּיקֵי הָעוֹלָם.</p>\n<p>אָמַרְתִּי לָהֶם, בָּנַי, דָּבָר זֶה קָרוֹב לְדִבְרֵי תוֹרָה, אֲבָל יֵשׁ לָכֶם לְהִתְרַחֵק (מתוך) מֵאוֹתָם הַסְּפָרִים (הללו) כְּדֵי שֶׁלֹּא יִסְטֶה לִבְּכֶם לָעֲבוֹדוֹת הַלָּלוּ וּלְכָל אוֹתָם הַצְּדָדִים שֶׁאָמַר כָּאן שֶׁמָּא חַס וְשָׁלוֹם (לא) תִּסְטוּ מֵאַחַר עֲבוֹדַת הַקָּבָּ\"ה,</p>\n<p>שֶׁהֲרֵי כָּל הַסְּפָרִים הַלָּלוּ מַטְעִים אֶת בְּנֵי הָאָדָם, מִשּׁוּם שֶׁבְּנֵי קֶדֶם הָיוּ חֲכָמִים, וִירֻשַּׁת הַחָכְמָה הַזּוֹ יָרְשׁוּ מֵאַבְרָהָם שֶׁנָּתַן לִבְנֵי הַפִּילַגְשִׁים, שֶׁכָּתוּב (בראשית כה) וְלִבְנֵי הַפִּילַגְשִׁים אֲשֶׁר לְאַבְרָהָם נָתַן אַבְרָהָם מַתָּנֹת וַיְשַׁלְּחֵם מֵעַל יִצְחָק בְּנוֹ בְּעוֹדֶנּוּ חַי קֵדְמָה אֶל אֶרֶץ קֶדֶם. וְאַחַר כָּךְ נִמְשְׁכוּ בְּאוֹתָהּ חָכְמָה לְכַמָּה צְדָדִים.</p>\n<p>אֲבָל זֶרַע יִצְחָק, חֶלְקוֹ שֶׁל יַעֲקֹב, לֹא כָּךְ, שֶׁכָּתוּב (שם) וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק. זֶהוּ חֵלֶק הַקָּדוֹשׁ שֶׁל הָאֱמוּנָה שֶׁבָּהּ נִדְבַּק אַבְרָהָם וְיָצָא מֵאוֹתוֹ גוֹרָל וּמֵאוֹתוֹ הַצַּד. מַה כָּתוּב בְּיַעֲקֹב? (שם כח) וְהִנֵּה ה' נִצָּב עָלָיו, וְכָתוּב וְאַתָּה יַעֲקֹב עַבְדִּי וְגוֹ'. מִשּׁוּם כָּךְ צָרִיךְ הָאָדָם לְהִמָּשֵׁךְ אַחַר הַקָּבָּ\"ה וּלְהִדָּבֵק בּוֹ תָּמִיד, שֶׁכָּתוּב (דברים י) וּבוֹ תִדְבָּק.</p>\n<p>בֹּא רְאֵה, (תהלים כד) מִי יַעֲלֶה בְּהַר ה' וְגוֹ'. אַחַר כָּךְ חָזַר וּפֵרַשׁ, נְקִי כַפַּיִם. שֶׁלֹּא עוֹשֶׂה בְיָדָיו צֶלֶם, וְלֹא מַחֲזִיק עִמָּהֶם בְּמַה שֶּׁלֹּא צָרִיךְ. וְעוֹד, שֶׁלֹּא נִטְמָא בָהֶם וְלֹא מְטַמֵּא בָהֶם אֶת הַגּוּף כְּמוֹ אוֹתָם שֶׁמְּטַמְּאִים אֶת עַצְמָם בַּיָּדַיִם לְהִטָּמֵא, וְזֶה הוּא נְקִי כַפַּיִם וּבַר לֵבָב, כְּמוֹ זֶה שֶׁלֹּא מוֹשֵׁךְ אֶת רְצוֹנוֹ וְלִבּוֹ לַצַּד הָאַחֵר אֶלָּא לְהִמָּשֵׁךְ אַחַר עֲבוֹדַת הַקָּבָּ\"ה.</p>\n<p>אֲשֶׁר לֹא נָשָׂא לַשָּׁוְא נַפְשׁוֹ. כָּתוּב נַפְשׁוֹ וְנִקְרָא נַפְשִׁי, וַהֲרֵי פֵּרְשׁוּהָ, נַפְשִׁי - זוֹ נֶפֶשׁ דָּוִד, צַד הָאֱמוּנָה. נַפְשׁוֹ - זוֹ נֶפֶשׁ הָאָדָם מַמָּשׁ. מִשּׁוּם שֶׁכַּאֲשֶׁר יָצָא מִן הָעוֹלָם הַזֶּה וְנַפְשׁוֹ תִּתְעַלֶּה בְּמַעֲשִׂים שֶׁכְּשֵׁרִים, עַל מַה שֶּׁיִּתְקַיֵּם בָּהֶם לָלֶכֶת בֵּין כָּל אוֹתָם הַקְּדוֹשִׁים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קטז) אֶתְהַלֵּךְ לִפְנֵי ה' בְּאַרְצוֹת הַחַיִּים. וּמִשּׁוּם שֶׁלֹּא נָשָׂא לַשָּׁוְא נַפְשִׁי, יִשָּׂא בְרָכָה מֵאֵת ה' וְגוֹ'.</p>"],[9522011221,"<p>בֹּא רְאֵה, אַחַר שֶׁנִּמּוֹל אַבְרָהָם, הָיָה יוֹשֵׁב וְכוֹאֵב, וְהַקָּבָּ\"ה שָׁלַח אֵלָיו שְׁלֹשָׁה מַלְאָכִים בְּגִלּוּי לְהַקְדִּים לוֹ שָׁלוֹם. וְאִם תֹּאמַר, שֶׁהֲרֵי בְּנִגְלֶה וְכִי מִי יָכוֹל לִרְאוֹת מַלְאָכִים, וַהֲרֵי כָּתוּב (שם קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת וְגוֹ'?</p>\n<p>אֶלָּא וַדַּאי שֶׁרָאָה אוֹתָם שֶׁיָּרְדוּ לָאָרֶץ כְּמוֹ בְּנֵי אָדָם. וְלֹא יִקְשֶׁה לְךְ זֶה, שֶׁהֲרֵי הֵם וַדַּאי רוּחוֹת קְדוֹשׁוֹת, וּבְשָׁעָה שֶׁיּוֹרְדִים לָעוֹלָם, מִתְלַבְּשִׁים בַּאֲוִירִים וּבִיסוֹדוֹת שֶׁל גְּלָמִים, וְנִרְאִים לִבְנֵי אָדָם מַמָּשׁ כְּמַרְאֵה דְמוּתָם.</p>\n<p>וּבֹא וּרְאֵה, אַבְרָהָם רָאָה אוֹתָם כְּמַרְאֵה בְּנֵי אָדָם, וְאַף עַל גַּב שֶׁהָיָה כּוֹאֵב מִן הַמִּילָה, יָצָא וְרָץ אַחֲרֵיהֶם כְּדֵי לֹא לִגְרֹעַ (מה) שֶׁהָיָה עוֹשֶׂה מִקֹּדֶם לָכֵן.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי שֶׁרָאָה אוֹתָם כְּמַרְאֶה שֶׁל מַלְאָכִים, מִמַּה שֶּׁכָּתוּב וַיֹּאמַר אֲדנָי, בְּאָלֶ\"ף דָּלֶ\"ת הַשְּׁכִינָה הָיְתָה בָּאָה, וְאֵלּוּ הָיוּ עַמּוּדִים שֶׁלָּהּ וְכִסֵּא אֵלֶיהָ, מִשּׁוּם שֶׁהֵם שְׁלֹשֶׁת הַגְּוָנִים שֶׁתַּחְתֶּיהָ.</p>\n<p>וְרָאָה כָּעֵת מִשּׁוּם שֶׁנִּמּוֹל מַה שֶּׁלֹּא רָאָה מִקֹּדֶם לָזֶה עַד שֶׁלֹּא נִמּוֹל. בַּתְּחִלָּה לֹא הָיָה יוֹדֵעַ, אֶלָּא שֶׁהֵם בְּנֵי אָדָם. אַחַר כָּךְ יָדַע שֶׁאוֹתָם מַלְאָכִים קְדוֹשִׁים הֵם וּבָאוּ אֵלָיו בִּשְׁלִיחוּת, בְּשָׁעָה שֶׁאָמְרוּ לוֹ אַיֵּ\"ה שָׂרָה אִשְׁתְּךְ וּבִשְּׂרוּ לוֹ בְּשׂוֹרַת יִצְחָק.</p>\n<p>אֵלָיו - הָאוֹתִיּוֹת נְקוּדוֹת אַיּ\"וֹ, וְסִימַן אַיּ\"וֹ רֶמֶז לְמַה שֶּׁלְּמַעְלָה, רֶמֶז לַקָּבָּ\"ה. וַיֹּאמֶר הִנֵּה בָאֹהֶל. כָּתוּב כָּאן הִנֵּה בָאֹהֶל, וְכָתוּב שָׁם (ישעיה לג) אֹהֶל בַּל יִצְעָן וְגוֹ'. בֹּא רְאֵה, כֵּיוָן שֶׁנָּקוּד אַיּ\"וֹ, לָמָּה כָּתוּב אַחַר כָּךְ אַיֵּה? אֶלָּא מִשּׁוּם שֶׁחִבּוּר שֶׁל זָכָר וּנְקֵבָה כְּאֶחָד סוֹד הָאֱמוּנָה. אָז אָמַר וַיֹּאמֶר הִנֵּה בָאֹהֶל. שָׁם הוּא הַקֶּשֶׁר שֶׁל הַכֹּל וְשָׁם הוּא נִמְצָא (ויאמר הנה באהל). אַיֵּה וְגוֹ'. וְכִי לֹא יָדְעוּ הַמַּלְאָכִים הָעֶלְיוֹנִים שֶׁשָּׂרָה הִנֵּה בָאֹהֶל? לָמָּה כָּתוּב אַיֵּה? אֶלָּא שֶׁלֹּא יוֹדְעִים בָּעוֹלָם הַזֶּה אֶלָּא מַה שֶּׁנִּמְסָר לָהֶם לָדַעַת.</p>\n<p>בֹּא רְאֵה, (שמות יב) וְעָבַרְתִּי בְּאֶרֶץ מִצְרַיִם אֲנִי ה'. וְכִי כַּמָּה שְׁלִיחִים וּמַלְאָכִים יֵשׁ לַקָּבָּ\"ה? אֶלָּא מִשּׁוּם שֶׁהֵם לֹא הָיוּ יוֹדְעִים בֵּין טִפָּה שֶׁל בְּכוֹר לְאוֹתָהּ שֶׁלֹּא שֶׁל בְּכוֹר פְּרָט לַקָּבָּ\"ה לְבַדּוֹ.</p>\n<p>כְּמוֹ זֶה (יחזקאל ט) וְהִתְוִיתָ תָּו עַל מִצְחוֹת הָאֲנָשִׁים. וְלָמָּה צְרִיכִים? אֶלָּא מִשּׁוּם שֶׁהֵם לֹא יוֹדְעִים אֶלָּא רַק מַה שֶּׁנִּמְסָר לָהֶם לָדַעַת (יודעים), כְּמוֹ כָּל הַדְּבָרִים הַלָּלוּ שֶׁעָתִיד הַקָּבָּ\"ה לְהָבִיא עַל הָעוֹלָם. וּמָה הַטַּעַם? מִשּׁוּם שֶׁהַקָּבָּ\"ה מַעֲבִיר כְּרוּז בְּכָל הָרְקִיעִים בְּאוֹתוֹ דָבָר שֶׁעָתִיד לְהָבִיא עַל הָעוֹלָם.</p>\n<p>כְּגוֹן זֶה בְּשָׁעָה שֶׁהַמַּשְׁחִית נִמְצָא בָעוֹלָם, צָרִיךְ בֶּן אָדָם לְהִסְתַּתֵּר בְּבֵיתוֹ וְלֹא יִהְיֶה נִרְאֶה בַּשּׁוּק כְּדֵי שֶׁלֹּא יֻשְׁחַת, כְּמוֹ שֶׁנֶּאֱמַר (שמות יב) וְאַתֶּם לֹא תֵצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר. מֵאֵלּוּ שֶׁיָּכוֹל לְהִסְתַּתֵּר כֵּן, אֲבָל מִלִּפְנֵי הַקָּבָּ\"ה לֹא (ס\"א יכול) צָרִיךְ לְהִסְתַּתֵּר. מַה כָּתוּב? (ירמיה כג) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם ה'.</p>\n<p>אַיֵּה שָׂרָה אִשְׁתְּךְ, שֶׁלֹּא רָצוּ לוֹמַר לְפָנֶיהָ. כֵּיוָן שֶׁאָמַר הִנֵּה בָאֹהֶל, מִיָּד - וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה וְהִנֵּה בֵן לְשָׂרָה אִשְׁתֶּךְ וְגוֹ' בּא רְאֵה דֶּרֶךְ אֶרֶץ, שֶׁעַד שֶׁלֹּא הִזְמִין אַבְרָהָם לִפְנֵיהֶם לֶאֱכֹל, לֹא אָמְרוּ לוֹ דָּבָר, כְּדֵי שֶׁלֹּא יֵרָאֶה שֶׁמִּשּׁוּם אוֹתָהּ בְּשׂוֹרָה הִזְמִין אוֹתָם לֶאֱכֹל. אַחַר שֶׁכָּתוּב וַיֹּאכְלוּ, אָז אָמְרוּ לוֹ אוֹתָהּ בְּשׂוֹרָה.</p>\n<p>וַיֹּאכְלוּ,? , וְכִי תַעֲלֶה עַל דַּעְתְּךְ שֶׁמַּלְאָכִים עֶלְיוֹנִים אוֹכְלִים? אֶלָּא בִּשְׁבִיל כְּבוֹדוֹ שֶׁל אַבְרָהָם נִרְאֶה כָּךְ. אָמַר רַבִּי אֶלְעָזָר, וַיֹּאכְלוּ וַדַּאי, מִשּׁוּם שֶׁהֵם אֵשׁ אוֹכֶלֶת אֵשׁ וְלֹא נִרְאִים, וְכָל מַה שֶּׁנָּתַן לָהֶם אַבְרָהָם אָכְלוּ, מִשּׁוּם שֶׁמִּצַּד אַבְרָהָם אוֹכְלִים לְמַעְלָה (שאוכלים מאותו צד שלמעלה).</p>\n<p>בֹּא רְאֵה, כָּל מַה שֶּׁאָכַל אַבְרָהָם, הוּא אָכַל בְּטָהֳרָה, וְלָכֵן הִקְרִיב לִפְנֵיהֶם וְאָכְלוּ, וְאַבְרָהָם שָׁמַר בְּבֵיתוֹ טֻמְאָה וְטָהֳרָה שֶׁאֲפִלּוּ בֶּן אָדָם שֶׁהוּא טָמֵא (לא יכל להתקרב לביתו, אז ידע אברהם שזה טמא הוא, ועשה) (לא היה משמש בביתו, עד שעשה) לוֹ טְבִילָה, אוֹ עָשָׂה לוֹ לִשְׁמֹר שִׁבְעָה יָמִים כָּרָאוּי לוֹ בְּבֵיתוֹ, וְכָךְ זֶה בְּוַדַּאי.</p>\n<p>בֹּא רְאֵה, כָּתוּב (דברים כג) אִישׁ אֲשֶׁר לֹא יִהְיֶה טָהוֹר מִקְּרֵה לָיְלָה וְגוֹ'. מַה תַּקָּנָתוֹ? וְהָיָה לִפְנוֹת עֶרֶב יִרְחַץ בַּמָּיִם. אֵרְעָה בּוֹ טֻמְאָה אַחֶרֶת, כְּמוֹ זִיבָה (טמאת צרעת או נדה) אוֹ טֻמְאַת נִדָּה שֶׁהָיוּ שְׁתֵּי טֻמְאוֹת, לֹא מַסְפִּיק לוֹ בְּאוֹתָהּ טְבִילָה (משום) בֵּין שֶׁאֵרַע לוֹ קֶרִי קֹדֶם שֶׁקִּבֵּל טֻמְאָה אַחֶרֶת (משום) בֵּין שֶׁאֵרַע לוֹ אַחַר כָּךְ.</p>\n<p>וְאַבְרָהָם וְשָׂרָה הָיוּ מְתַקְּנִים טְבִילָה לְכֻלָּם, הוּא לַגְּבָרִים וְהִיא לַנָּשִׁים. מָה הַטַּעַם עָסַק אַבְרָהָם לְטַהֵר בְּנֵי אָדָם? מִשּׁוּם שֶׁהוּא טָהוֹר וְנִקְרָא טָהוֹר, שֶׁכָּתוּב (איוב יד) מִי יִתֵּן טָהוֹר מִטָּמֵא לֹא אֶחָד. טָהוֹר - זֶה אַבְרָהָם שֶׁיָּצָא מִתֶּרַח.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, כְּדֵי לְתַקֵּן אֶת אוֹתָהּ הַדַּרְגָּה שֶׁל אַבְרָהָם, וּמַהִי? מַיִ\"ם (חסד). לָכֵן הִתְקִין לְטַהֵר בְּנֵי הָעוֹלָם בְּמַיִם. וּבְשָׁעָה שֶׁהִזְמִין אֶת הַמַּלְאָכִים, בְּרֵאשִׁית דְּבָרָיו מַה כָּתוּב? יֻקַּח נָא מְעַט מַיִם, כְּדֵי לְהִתְחַזֵּק בְּאוֹתָהּ דַּרְגָּה שֶׁהַמַּיִם שְׁרוּיִים בָּהּ,</p>\n<p>וּמִשּׁוּם כָּךְ הָיָה מְטַהֵר אֶת כָּל בְּנֵי הָאָדָם מֵהַכֹּל. מְטַהֵר אוֹתָם מִצַּד שֶׁל עֲבוֹדָה זָרָה, וּמְטַהֵר אוֹתָם מִצַּד הַטֻּמְאָה. וּכְמוֹ שֶׁהוּא מְטַהֵר אֶת הָאֲנָשִׁים, כָּךְ גַּם שָׂרָה מְטַהֶרֶת אֶת הַנָּשִׁים, וְנִמְצָא שֶׁכָּל מִי שֶׁבָּא אֲלֵיהֶם טְהוֹרִים מֵהַכֹּל.</p>\n<p>בֹּא רְאֵה שֶׁאַבְרָהָם נָטַע אִילָן בְּכָל מָקוֹם שֶׁדִּיּוּרוֹ שָׁם, וְלֹא הָיָה עוֹלֶה בְּכָל מָקוֹם כָּרָאוּי, פְּרָט לְשָׁעָה שֶׁדִּיּוּרוֹ הָיָה בְּאֶרֶץ כְּנַעַן, וּבְאוֹתוֹ אִילָן הָיָה יוֹדֵעַ מִי שֶׁנֶּאֱחָז בַּקָּבָּ\"ה וּמִי שֶׁנֶּאֱחָז בַּעֲבוֹדָה זָרָה.</p>\n<p>מִי שֶׁנֶּאֱחָז בַּקָּבָּ\"ה, הָיָה הָאִילָן פּוֹרֵשׂ עֲנָפָיו וּמְכַסֶּה עַל רֹאשׁוֹ וְעוֹשֶׂה עָלָיו צֵל נָאֶה. וּמִי שֶׁנֶּאֱחָז בַּצֵּל שֶׁל עֲבוֹדָה זָרָה, אוֹתוֹ הָאִילָן הָיָה מִתְעַלֶּה, וַעֲנָפָיו הָיוּ עוֹלִים לְמַעְלָה. אָז הָיָה יוֹדֵעַ אַבְרָהָם וּמַזְהִיר אוֹתוֹ, וְלֹא זָז מִשָּׁם עַד שֶׁנֶּאֱחַז בֶּאֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וְכָךְ מִי שֶׁהוּא טָהוֹר (ד\"א כך) מְקַבֵּל אוֹתוֹ הָאִילָן, וּמִי שֶׁהוּא טָמֵא אֵינוֹ מְקַבֵּל אוֹתוֹ. אָז יָדַע אַבְרָהָם וְהָיָה מְטַהֵר אוֹתָם בְּמַיִם.</p>\n<p>וּמַעָיַין מַיִם הָיָה תַּחַת אוֹתוֹ אִילָן, וּמִי שֶׁצָּרִיךְ טְבִילָה מִיָּד הַמַּיִם עוֹלִים אֵלָיו, וְעוֹלִים עַנְפֵי הָאִילָן, אָז יָדַע אַבְרָהָם שֶׁהוּא טָמֵא וְצָרִיךְ מִיָּד טְבִילָה. וְאִם לֹא, יָבְשׁוּ הַמַּיִם, וְאָז יָדַע שֶׁרוֹצֶה לְהִטָּמֵא וּלְהִשָּׁמֵר שִׁבְעָה יָמִים.</p>\n<p>וּבֹא וּרְאֵה, שֶׁאֲפִלּוּ בְּשָׁעָה שֶׁהִזְמִין אֶת הַמַּלְאָכִים אָמַר לָהֶם וְהִשָּׁעֲנוּ תַּחַת הָעֵץ כְּדֵי לִרְאוֹת וְלִבְדּק אוֹתָם, וּבְאוֹתוֹ אִילָן הָיָה בּוֹדֵק אֶת כָּל בְּנֵי הָעוֹלָם. וְהַסּוֹד (כנגד) מִשּׁוּם הַקָּדוֹשׁ בָּרוּךְ הוּא (עשה) אָמַר שֶׁהוּא עֵץ הַחַיִּים לַכֹּל, וְלָכֵן וְהִשָּׁעֲנוּ תַּחַת הָעֵץ, וְלֹא תַחַת עֲבוֹדָה זָרָה.</p>\n<p>וּבֹא וּרְאֵה, כְּשֶׁחָטָא אָדָם, הוּא חָטָא בְּעֵץ הַדַּעַת טוֹב וָרָע, שֶׁכָּתוּב וּמֵעֵץ הַדַּעַת וְגוֹ', וְהוּא חָטָא בּוֹ וְגָרַם מָוֶת לָעוֹלָם. מַה כָּתוּב? וְעַתָּה פֶּן יִשְׁלַח יָדוֹ וְלָקַח גַּם מֵעֵץ הַחַיִּים וְגוֹ' (וגרם מות לכל בני העולם); וּכְשֶׁבָּא אַבְרָהָם, הִתְקִין אֶת הָעוֹלָם עִם אִילָן אַחֵר, שֶׁהוּא עֵץ הַחַיִּים, וְהוֹדִיעַ אֶת הָאֱמוּנָה לְכָל בְּנֵי הָעוֹלָם.</p>\n<p>אָמַר רַבִּי חִיָּיא אָמַר רַב, אִם הָיִינוּ מִסְתַּכְּלִים בַּפָּרָשָׁה הַזּוֹ - נִסְתַּכֵּל בְּחָכְמָה אִם עִנְיַן הַנְּשָׁמָה הִיא אֵין רֹאשָׁהּ סוֹפָהּ וְאֵין סוֹפָהּ רֹאשָׁהּ, וְאִם הָעִנְיָן לִפְטִירַת הָאָדָם מִן הָעוֹלָם הִיא, נִסְתֹּר אֶת כָּל הַפָּרָשָׁה אוֹ נַעֲמִיד אֶת הַפָּרָשָׁה בָּזֶה אוֹ בָזֶה. מַה זֶּה יֻקַּח נָא מְעַט מַיִם וְרַחֲצוּ רַגְלֵיכֶם וְגוֹ', וְאֶקְחָה פַת לֶחֶם וְגוֹ', וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה אֶל שָׂרָה וְגוֹ', וְאֶל הַבָּקָר רָץ אַבְרָהָם וְגוֹ', וַיִּקַּח חֶמְאָה וְחָלָב וְגוֹ'.</p>\n<p>כְּשֶׁבָּא רַב דִּימֵי, אָמַר, לֹא מָצְאָה הַנְּשָׁמָה תּוֹעֶלֶת לַגּוּף אִלְמָלֵא מַה שֶּׁרָמַז בְּכָאן רֶמֶז הַקָּרְבָּנוֹת. בָּטְלוּ הַקָּרְבָּנוֹת - לֹא בָטְלָה הַתּוֹרָה. זֶה שֶׁלֹּא מִתְעַסֵּק בְּקָרְבָּנוֹת, שֶׁיַּעֲסֹק בַּתּוֹרָה וְיוֹעִיל לוֹ יוֹתֵר.</p>\n<p>שֶׁאָמַר רַבִּי יוֹחָנָן, כְּשֶׁפֵּרַשׁ הַקָּבָּ\"ה הַקָּרְבָּנוֹת, אָמַר מֹשֶׁה: רִבּוֹנוֹ שֶׁל עוֹלָם, תִּינַח בִּזְמַן שֶׁיִּהְיוּ יִשְׂרָאֵל עַל אַדְמָתָם, כֵּיוָן שֶׁיִּגְלוּ מֵעַל אַדְמָתָם מַה יַּעֲשׂוּ? אָמַר לוֹ: מֹשֶׁה, יַעַסְקוּ בַּתּוֹרָה, וַאֲנִי מוֹחֵל לָהֶם בִּשְׁבִילָהּ יוֹתֵר מִכָּל הַקָּרְבָּנוֹת שֶׁבָּעוֹלָם, שֶׁנֶּאֱמַר (ויקרא ז) זאת התורה לעלה למנחה וגו'. כְּלוֹמַר, זאת הַתּוֹרָה בִּשְׁבִיל עוֹלָה, בִּשְׁבִיל מִנְחָה, בִּשְׁבִיל חַטָּאת, בִּשְׁבִיל אָשָׁם.</p>\n<p>אָמַר רַבִּי כְּרוּסְפְּדַאי, זֶה מִי שֶׁמַּזְכִּיר בְּפִיו בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת עִנְיַן הַקָּרְבָּנוֹת וְתִקְרֻבְתָּם וִיכַוֵּן בָּהֶם, בְּרִית כְּרוּתָה הִיא שֶׁאוֹתָם הַמַּלְאָכִים הַמַּזְכִּירִים חֶטְאוֹ כְּדֵי לְהָרַע לוֹ, שֶׁלֹּא יְכוֹלִים לַעֲשׂוֹת לוֹ אֶלָּא רַק טוֹב.</p>\n<p>וּמִי יוֹכִיחַ? פָּרָשָׁה זוֹ תּוֹכִיחַ! שֶׁכֵּיוָן שֶׁאָמַר וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים נִצָּבִים עָלָיו, מַה זֶּה עָלָיו? לְעַיֵּן בְּדִינוֹ. כֵּיוָן שֶׁרוֹאָה נִשְׁמַת הַצַּדִּיק כָּךְ, מַה כָּתוּב? וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה וְגוֹ'. מַה זֶּה הָאֹהֱלָה? בֵּית הַמִּדְרָשׁ. וּמַהוּ אוֹמֵר? מַהֲרִי שְׁלֹשׁ סְאִים, עִנְיַן הַקָּרְבָּנוֹת, וְהַנְּשָׁמָה מִתְכַּוֶּנֶת בָּהֶם. זֶהוּ שֶׁכָּתוּב וְאֶל הַבָּקָר רָץ אַבְרָהָם. וְאָז נוֹחַ לָהֶם וְלֹא יְכוֹלִים לְהָרַע לוֹ.</p>\n<p>רַבִּי פִּנְחָס פָּתַח פָּסוּק שֶׁכָּתוּב (במדבר יז) וְהִנֵּה הֵחֵל הַנֶּגֶף בָּעָם, וְכָתוּב וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְגוֹ', וְכָתוּב וַתֵּעָצַר הַמַּגֵּפָה. כָּתוּב כָּאן מַהֵר, וְכָתוּב שָׁם מַהֲרִי שְׁלֹשׁ סְאִים. מַה לְּהַלָּן קָרְבָּן לְהִנָּצֵל, אַף כָּאן קָרְבָּן לְהִנָּצֵל.</p>\n<p>אָמַר רַבִּי פִּנְחָס, פַּעַם אַחַת הָיִיתִי מְהַלֵּךְ בַּדֶּרֶךְ וּפָגַשְׁתִּי אֶת אֵלִיָּהוּ. אָמַרְתִּי לוֹ, יֹאמַר לִי מַר דָּבָר שֶׁמּוֹעִיל לַבְּרִיּוֹת. אָמַר לוֹ, בְּרִית גָּזַר הַקָּבָּ\"ה, וְנִכְנְסוּ לְפָנָיו כָּל הַמַּלְאָכִים שֶׁמְּמֻנִּים לְהַזְכִּיר חֲטָאֵי הָאָדָם, שֶׁבִּזְמַן שֶׁיַּזְכִּירוּ בְּנֵי אָדָם הַקָּרְבָּנוֹת שֶׁצִּוָּה מֹשֶׁה, וּמְכַוֵּן לִבּוֹ וּרְצוֹנוֹ בָהֶם - שֶׁכֻּלָּם יַזְכִּירוּ אוֹתוֹ לְטוֹב.</p>\n<p>וְעוֹד, בִּזְמַן שֶׁיֶּאֱרַע מָוֶת בִּבְנֵי אָדָם, הַבְּרִית נִגְזְרָה, וְהַכָּרוֹז עוֹבֵר עַל כָּל חֵילוֹת הַשָּׁמַיִם, דְּאִם יַעֲלוּ בָנָיו בָּאָרֶץ בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת וְיֹאמְרוּ בִּרְצוֹן נֶפֶשׁ וָלֵב עִנְיָנִים שֶׁל קְטֹרֶת בְּשָׂמִים שֶׁהָיוּ לָהֶם לְיִשְׂרָאֵל, שֶׁיִּתְבַּטֵּל הַמָּוֶת מֵהֶם.</p>\n<p>אָמַר רַבִּי יִצְחָק, בּא רְאֵה מַה כָּתוּב, וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְתֶן עָלֶיהָ אֵשׁ מֵעַל הַמִּזְבֵּחַ וְשִׂים קְטֹרֶת. אָמַר לוֹ אַהֲרֹן, לָמָּה? כִּי יָצָא הַקֶּצֶף מִלִּפְנֵי ה' וְגוֹ'. מַה כָּתוּב? וַיָּרָץ אֶל תּוֹךְ הַקָּהָל וְהִנֵּה הֵחֵל הַנֶּגֶף בָּעָם. וְכָתוּב וַיַּעֲמֹד בֵּין הַמֵּתִים וּבֵין הַחַיִּים וַתֵּעָצַר הַמַּגֵּפָה. וְלֹא יָכֹל מַלְאָךְ שֶׁל חַבָּלָה לִשְׁלֹט וְנִתְבַּטֵּל הַמָּוֶת.</p>\n<p>רַבִּי אַחָא הָלַךְ לִכְפַר טַרְשָׁא, בָּא אֵצֶל הַמְאָרֵחַ שֶׁלּוֹ. לָחֲשׁוּ עָלָיו כָּל בְּנֵי הָעִיר. אָמְרוּ, אָדָם גָּדוֹל בָּא לְכָאן, נֵלֵךְ אֵלָיו. בָּאוּ אֶצְלוֹ. אָמְרוּ לוֹ, לֹא חוֹשֵׁשׁ עַל אֲבֵדתֶינוּ? אָמַר לָהֶם, מַהוּ? אָמְרוּ לוֹ שֶׁיֵּשׁ שִׁבְעָה יָמִים שֶׁיֵּשׁ מָוֶת בָּעִיר, וְכָל יוֹם מִתְחַזֵּק וְלֹא מִתְבַּטֵּל.</p>\n<p>אָמַר לָהֶם, נֵלֵךְ לְבֵית הַכְּנֶסֶת וּנְבַקֵּשׁ רַחֲמִים מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. עַד שֶׁהָיוּ הוֹלְכִים, בָּאוּ וְאָמְרוּ, פְּלוֹנִי וּפְלוֹנִי מֵתוּ, וּפְלוֹנִי וּפְלוֹנִי נוֹטִים לָמוּת. אָמַר לָהֶם רַבִּי אַחָא, אֵין עֵת לַעֲמֹד כָּךְ, שֶׁהַשָּׁעָה דְחוּקָה.</p>\n<p>אֲבָל תַּפְרִישׁוּ מִכֶּם אַרְבָּעִים בְּנֵי אָדָם מֵאֵלּוּ הַיּוֹתֵר זַכָּאִים. עֲשָׂרָה עֲשָׂרָה לְאַרְבָּעָה חֲלָקִים, וַאֲנִי עִמָּכֶם, עֲשָׂרָה לִקְצֵה הָעִיר וַעֲשָׂרָה לִקְצֵה הָעִיר, וְכֵן לְאַרְבַּע קַצְווֹת הָעִיר, וְאִמְרוּ בְּנֶפֶשׁ חֲפֵצָה עִנְיָן שֶׁל קְטֹרֶת הַסַּמִּים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְמֹשֶׁה, וְעִנְיָן שֶׁל הַקָּרְבָּנוֹת אִתּוֹ.</p>\n<p>עָשׂוּ כָּךְ שָׁלֹשׁ פְּעָמִים וְעָבְרוּ בְּכָל הָעִיר לְאַרְבַּע קְצָווֹת וְהָיוּ אוֹמְרִים כֵּן. לְבַסּוֹף אָמַר לָהֶם, נֵלֵךְ לְאֵלּוּ שֶׁנּוֹטִים לָמוּת, וְתַפְרִישׁוּ מִכֶּם לְבָתֵּיהֶם וְתֹאמְרוּ כָּךְ, וְכַאֲשֶׁר תְּסַיְּמוּ, תֹּאמְרוּ אֵלּוּ הַפְּסוּקִים, וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְתֵן עָלֶיהָ אֵשׁ וְגוֹ', וַיִּקַּח אַהֲרֹן וְגוֹ', וַיַּעֲמֹד בֵּין הַמֵּתִים וְגוֹ'. וְכֵן עָשׂוּ וְהִתְבַּטֵּל מֵהֶם (המות).</p>\n<p>שָׁמְעוּ אוֹתוֹ קוֹל שֶׁאוֹמֵר: סוֹדֵי הַסּוֹדוֹת, הָרִאשׁוֹנִים הִנְחִילוּהָ לָנֶצַח, שֶׁהֲרֵי דִּין הַשָּׁמַיִם לֹא שׁוֹרֶה כָּאן, שֶׁהֲרֵי יוֹדְעִים לְבַטְּלוֹ. חָלַשׁ לִבּוֹ שֶׁל רַבִּי אָחָא וְיָשַׁן. שָׁמַע שֶׁאוֹמְרִים לוֹ: כְּמוֹ שֶׁעָשִׂיתָ אֶת זֶה - תַּעֲשֶׂה אֶת זֶה. לֵךְ אֱמֹר לָהֶם שֶׁיַּחְזְרוּ בִּתְשׁוּבָה, שֶׁרְשָׁעִים הֵם לְפָנַי. קָם וְהֶחֱזִירָם בִּתְשׁוּבָה שְׁלֵמָה, וְקִבְּלוּ עֲלֵיהֶם שֶׁלֹּא יִתְבַּטְּלוּ מֵהַתּוֹרָה לְעוֹלָם, וְהֶחְלִיפוּ אֶת שֵׁם הָעִיר, וְקָרְאוּ לָא מָתָא מַחְסֵיָא.</p>\n<p>אָמַר רַבִּי יְהוּדָה, לֹא דַי לָהֶם לַצַּדִּיקִים שֶׁמְּבַטְּלִים אֶת הַגְּזֵרָה, אֶלָּא לְאַחַר כֵּן שֶׁמְּבָרְכִים לָהֶם, תֵּדַע לְךְ שֶׁכֵּן הוּא. דְּכֵיוָן שֶׁהַנְּשָׁמָה אוֹמֶרֶת לַגּוּף מַהֲרִי שְׁלֹשׁ סְאִים וְגוֹ' וְכָל אוֹתוֹ הָעִנְיָן וּמְבַטֵּל אֶת הַדִּין - מַה כָּתוּב? וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה. הֲרֵי בְּרָכָה.</p>\n<p>כֵּיוָן שֶׁרוֹאִים אוֹתָהּ הַמַּלְאָכִים שֶׁזֶּה לָקַח עֵצָה לְנַפְשׁוֹ - מָה עוֹשִׂים? הוֹלְכִים אֵצֶל הָרְשָׁעִים לְעַיֵּן בְּדִינָם וְלַעֲשׂוֹת בָּהֶם מִשְׁפָּט. זֶהוּ שֶׁכָּתוּב וַיָּקֻמוּ מִשָּׁם הָאֲנָשִׁים וַיַּשְׁקִפוּ עַל פְּנֵי סְדם, לִמְקוֹם הָרְשָׁעִים, לַעֲשׂוֹת בָּהֶם מִשְׁפָּט.</p>\n<p>זֶה הוּא שֶׁאָמַר רַבִּי יְהוּדָה, כָּךְ דַּרְכּוֹ שֶׁל צַדִּיק: כֵּיוָן שֶׁרוֹאֶה שֶׁמְּעַיְּנִים בְּדִינוֹ, אֵינוֹ מִתְאַחֵר לָשׁוּב וּלְהִתְפַּלֵּל וּלְהַקְרִיב (על) חֶלְבּוֹ וְדָמוֹ לִפְנֵי צוּרוֹ, עַד שֶׁמִּסְתַּלְּקִים בַּעֲלֵי הַדִּין מִמֶּנּוּ.</p>\n<p>שֶׁכֵּיוָן שֶׁאָמַר וַיִּשָּׂא עֵינָיו וַיַּרְא וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים נִצָּבִים עָלָיו - מַה כָּתוּב בַּנְּשָׁמָה? וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה אֶל שָׂרָה. בְּחִפָּזוֹן וּבִמְהִירוּת בְּלֹא שׁוּם הַעְכָּבָה. מִיָּד מְמַהֶרֶת הַנְּשָׁמָה אֵצֶל הַגּוּף לְהַחֲזִירוֹ לְמוּטָב וּלְבַקֵּשׁ בְּמַה שֶּׁיִּתְכַּפֵּר לוֹ, עַד שֶׁמִּסְתַּלְּקִים מִמֶּנּוּ בַּעֲלֵי הַדִּין.</p>\n<p>רַבִּי אֱלִיעֶזֶר אוֹמֵר, מַהוּ שֶׁאָמַר וְאַבְרָהָם וְשָׂרָה זְקֵנִים בָּאִים בַּיָּמִים חָדַל לִהְיוֹת לְשָׂרָה אֹרַח כַּנָּשִׁים? אֶלָּא, כֵּיוָן שֶׁהַנְּשָׁמָה עוֹמֶדֶת בְּמַעֲלָתָהּ, וְהַגּוּף נִשְׁאָר בָּאָרֶץ מִכַּמָּה שָׁנִים, בָּאִים בַּיָּמִים שָׁנִים וְיָמִים הַרְבֵּה וְחָדַל לָצֵאת וְלָבֹא וְלַעֲבֹר אֹרַח כִּשְׁאָר כָּל אָדָם. נִתְבַּשֵּׂר לְהַחֲיוֹת הַגּוּף.</p>\n<p>מַהוּ אוֹמֵר אַחֲרֵי בְלוֹתִי הָיְתָה לִּי עֶדְנָה? אַחֲרֵי בְלוֹתִי בֶּעָפָר מֵהַיּוֹם כַּמָּה שָׁנִים, הָיְתָה לִּי עֶדְנָה וְחִדּוּשׁ. וַאדנִי זָקֵן, שֶׁהַיּוֹם כַּמָּה שָׁנִים שֶׁיָּצָאת מִמֶּנּוּ וְלֹא הִפְקִידַנִי.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר, הֲיִפָּלֵא מֵה' דָּבָר לַמּוֹעֵד. מַהוּ לַמּוֹעֵד? אוֹתוֹ הַיָּדוּעַ אֶצְלִי לְהַחֲיוֹת מֵתִים. וּלְשָׂרָה בֵן, מְלַמֵּד שֶׁיִּתְחַדֵּשׁ כְּבֶן שָׁלֹשׁ שָׁנִים.</p>\n<p>אָמַר רַבִּי יְהוּדָה בְּרַבִּי סִימוֹן, כֵּיוָן שֶׁהַנְּשָׁמָה נִזּוֹנֵית מִזִּיוָהּ שֶׁל מַעְלָה, הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר לְאוֹתוֹ הַמַּלְאָךְ הַנִּקְרָא דוּמָ\"ה: לֵךְ וּבַשֵּׂר לְגוּף פְּלוֹנִי שֶׁאֲנִי עָתִיד לְהַחֲיוֹתוֹ למּוֹעֵד שֶׁאֲנִי אֲחַיֶּה אֶת הַצַּדִּיקִים לֶעָתִיד לָבֹא. וְהוּא מֵשִׁיב: אַחֲרֵי בְלוֹתִי הָיְתָה לִּי עֶדְנָה? אַחֲרֵי בְלוֹתִי בֶּעָפָר וְשָׁכַנְתִּי בָּאֲדָמָה, וְאָכַל בְּשָׂרִי רִמָּה וְגוּשׁ עָפָר, תִּהְיֶה לִי חִדּוּשׁ?</p>\n<p>הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר לַנְּשָׁמָה: זֶהוּ שֶׁכָּתוּב וַיֹּאמֶר ה' אֶל אַבְרָהָם וְגוֹ' הֲיִפָּלֵא מֵה' דָּבָר!? לַמּוֹעֵד הַיָּדוּעַ אֶצְלִי לְהַחֲיוֹת אֶת הַמֵּתִים אָשׁוּב אֵלֶיךְ אוֹתוֹ הַגּוּף שֶׁהוּא קָדוֹשׁ מְחֻדָּשׁ כְּבָרִאשׁוֹנָה לִהְיוֹתְכֶם מַלְאָכִים קְדוֹשִׁים, וְאוֹתוֹ הַיּוֹם עָתִיד לְפָנַי לִשְׂמֹחַ בָּהֶם. זֶהוּ שֶׁכָּתוּב (תהלים קד) יְהִי כְבוֹד ה' לְעוֹלָם יִשְׂמַח ה' בְּמַעֲשָׂיו. (ע\"כ מדרש הנעלם)</p>"],[9522011222,"<p>וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה. אָמַר רַבִּי יִצְחָק, שׁוֹב אָשׁוּב - שׁוֹב יָשׁוּב הָיָה צָרִיךְ לִכְתֹּב, שֶׁהֲרֵי הַמַּפְתֵּחַ הַזֶּה לִפְקֹד הָעֲקָרוֹת הוּא בְּיַד הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא בְּיַד שָׁלִיחַ אַחֵר,</p>\n<p>כְּמוֹ שֶׁשָּׁנִינוּ, שָׁלֹשׁ מַפְתְּחוֹת הֵם שֶׁלֹּא נִמְסְרוּ בְּיַד שָׁלִיחַ: שֶׁל חַיָּה, וּתְחִיַּת הַמֵּתִים, וּגְשָׁמִים. וְהוֹאִיל וְלֹא נִמְסְרוּ בְּיַד שָׁלִיחַ, לָמָּה כָּתוּב שׁוֹב אָשׁוּב? אֶלָּא וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהָיָה עוֹמֵד עֲלֵיהֶם אָמַר (לו) הַדָּבָר, לָכֵן כָּתוּב וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךְ.</p>\n<p>וּבֹא וּרְאֵה, בְּכָל מָקוֹם שֶׁכָּתוּב וַיֹּאמֶר סְתָם אוֹ וַיִּקְרָא סְתָם, הוּא מַלְאַךְ הַבְּרִית וְלֹא אַחֵר. וַיֹּאמֶר - שֶׁכָּתוּב (שמות טו) וַיֹּאמֶר אִם שָׁמֹעַ תִּשְׁמַע וְגוֹ'. וַיֹּאמֶר, וְלֹא אָמַר מִיהוּ. וַיִּקְרָא - שֶׁכָּתוּב (ויקרא א) וַיִּקְרָא אֶל מֹשֶׁה, וְלֹא אָמַר מִי הָיָה. אָמַר - שֶׁכָּתוּב (שמות כד) וְאֶל מֹשֶׁה אָמַר וְגוֹ', וְלֹא אָמַר מִי הָיָה. (אף כך שכתוב שוב אשוב, ויאמר סתם, ולא אמר מי היה,) אֶלָּא בְּכָל אֵלֶּה מַלְאָךְ שֶׁל הַבְּרִית הָיָה, וְהַכֹּל נֶאֱמַר בַּקָּבָּ\"ה. וְלָכֵן כָּתוּב וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךְ וְגוֹ', וְהִנֵּה בֵן וְגוֹ'.</p>"],[9522011223,"<p>וְהִנֵּה בֵן לְשָׂרָה אִשְׁתְּךְ. מָה הַטַּעַם לֹא כָתוּב וְהִנֵּה בֵן לְךְ? אֶלָּא כְּדֵי שֶׁלֹּא יַחְשֹׁב שֶׁהוּא מֵהָגָר כְּמוֹ בָּרִאשׁוֹנָה. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (מלאכי א) בֵּן יְכַבֵּד אָב וְעֶבֶד אֲדנָיו. בֵּן יְכַבֵּד אָב - זֶה יִצְחָק אֶת אַבְרָהָם.</p>\n<p>מָתַי כִּבֵּד אוֹתוֹ? בְּשָׁעָה שֶׁעָקַד אוֹתוֹ עַל גַּבֵּי הַמִּזְבֵּחַ וְרָצָה לְהַקְרִיבוֹ לְקָרְבָּן. וְיִצְחָק בֶּן שְׁלֹשִׁים וְשֶׁבַע שָׁנִים הָיָה, וְאַבְרָהָם הָיָה זָקֵן, שֶׁאִלּוּ הָיָה בּוֹעֵט (בו) בְּרֶגֶל אַחַת לֹא הָיָה יָכוֹל לַעֲמֹד לְפָנָיו, וְהוּא כִבֵּד אוֹתוֹ אֶת אָבִיו, וְעָקַד אוֹתוֹ כְּמוֹ תַיִשׁ כְּדֵי לַעֲשׂוֹת רְצוֹן אָבִיו.</p>\n<p>וְעָבֶד אֲדנָיו - זֶה אֱלִיעֶזֶר לְאַבְרָהָם, כְּשֶׁשָּׁלַח אוֹתוֹ לְחָרָן וְעָשָׂה כָּל רְצוֹנוֹ שֶׁל אַבְרָהָם וְכִבְּדוֹ, כְּמוֹ שֶׁכָּתוּב (בראשית כד) וַה' בֵּרַךְ אֶת אֲדנִי וְגוֹ', וְכָתוּב (שם) וַיֹּאמַר עֶבֶד אַבְרָהָם אָנֹכִי, כְּדֵי לְכַבֵּד אֶת אַבְרָהָם.</p>\n<p>שֶׁהֲרֵי בֶּן אָדָם שֶׁהָיָה מֵבִיא כֶסֶף וְזָהָב וַאֲבָנִים יְקָרוֹת וּגְמַלִּים, וְהוּא כָּרָאוּי, נָאֶה לְמַרְאֶה, לֹא אָמַר שֶׁהוּא אוֹהֵב אַבְרָהָם אוֹ קָרוֹב שֶׁלּוֹ, אֶלָּא אָמַר עֶבֶד אַבְרָהָם אָנֹכִי, כְּדֵי לְהַעֲלוֹת אֶת שֶׁבַח אַבְרָהָם וּלְכַבְּדוֹ בְּעֵינֵיהֶם.</p>\n<p>וְעַל כֵּן בֵּן יְכַבֵּד אָב וְעֶבֶד אֲדנָיו. וְאַתֶּם יִשְׂרָאֵל בָּנַי, קָלוֹן בְּעֵינֵיכֶם לוֹמַר שֶׁאֲנִי אֲבִיכֶם אוֹ שֶׁאַתֶּם עֲבָדִים שֶׁלִּי? וְאִם אָב אָנִי אַיֵּה כְבוֹדִי וְגוֹ'. מִשּׁוּם כָּךְ וְהִנֵּה בֵן. זֶהוּ בֵּן וַדַּאי, וְלֹא יִשְׁמָעֵאל. זֶהוּ בֵּן שֶׁכִּבֵּד אֶת אָבִיו כָּרָאוּי.</p>\n<p>וְהִנֵּה בֵן לְשָׂרָה אִשְׁתְּךְ. בֵן לְשָׂרָה - שֶׁבִּגְלָלוֹ מֵתָה, שֶׁבִּגְלָלוֹ כָּאֲבָה נַפְשָׁה עַד שֶׁיָּצְאָה מִמֶּנָּה. וְהִנֵּה בֵן לְשָׂרָה - לְהִתְעַלּוֹת בִּגְלָלוֹ בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב בְּדִין עַל הָעוֹלָם. שֶׁאָז וַה' פָּקַד אֶת שָׂרָה וְגוֹ', שֶׁהֲרֵי מַזְכִּירִים אֶת שָׂרָה מִשּׁוּם יִצְחָק, וְעַל זֶה הוּא בֵּן לְשָׂרָה (זה אמרו המלאכים). וְהִנֵּה בֵן לְשָׂרָה. (זה) שֶׁהֲרֵי הַנְּקֵבָה לוֹקַחַת (את) הַבֵּן מֵהַזָּכָר.</p>\n<p>וְשָׂרָה שּמַעַת פֶּתַח הָאֹהֶל וְהוּא אַחֲרָיו. מַה זֶּה וְהוּא אַחֲרָיו? וְהִיא אַחֲרָיו צָרִיךְ לוֹ! אֶלָּא סוֹד הוּא, וְשָׂרָה שּמַעַת מַה שֶּׁהָיָה אוֹמֵר (פתח האהל, זה הקדוש ברוך הוא, והוא אחריו מי שהיה אומר) פֶּתַח הָאֹהֶל, זוֹ הַדַּרְגָּה הַתַּחְתּוֹנָה, פֶּתַח הָאֱמוּנָה. וְהוּא אַחֲרָיו - (זה) שֶׁהוֹדָה לוֹ הַדַּרְגָּה הָעֶלְיוֹנָה (נ\"א: פתח האהל והוא אחריו זה הקדוש ברוך הוא, פתח האהל זו הדרגה התחתונה, והוא אחריו זו הדרגה העליונה). מִיּוֹם שֶׁהָיְתָה שָׂרָה בָּעוֹלָם לֹא שָׁמְעָה דְּבַר הַקָּדוֹשׁ בָּרוּךְ הוּא פְּרָט לְאוֹתָהּ שָׁעָה.</p>\n<p>דָּבָר אַחֵר - שֶׁהָיְתָה יוֹשֶׁבֶת שָׂרָה פֶּתַח הָאֹהֶל כְּדֵי לִשְׁמֹעַ הַדְּבָרִים, וְהִיא שָׁמְעָה הַדָּבָר הַזֶּה שֶׁהִתְבַּשֵּׂר בּוֹ אַבְרָהָם. (דבר אחר) וְהוּא אַחֲרָיו - אַבְרָהָם שֶׁהָיָה יוֹשֵׁב מֵאֲחוֹרֵי הַשְּׁכִינָה.</p>\n<p>וְאַבְרָהָם וְשָׂרָה זְקֵנִים בָּאִים בַּיָּמִים. מַה זֶּה בָּאִים בַּיָּמִים? הַשִּׁעוּרִים שֶׁל הַיָּמִים שֶׁאָז נִרְאוּ לָהֶם, הָאֶחָד מֵאָה וְהָאֶחָד תִּשְׁעִים, נִכְנְסוּ בַיָּמִים הַשִּׁעוּר שֶׁל הַיָּמִים כָּרָאוּי. בָּאִים בַּיָּמִים, כְּמוֹ שֶׁנֶּאֱמַר כִּי בָא הַיּוֹם, שֶׁהֶעֱרִיב הַיּוֹם לְהִכָּנֵס.</p>\n<p>חָדַל לִהְיוֹת לְשָׂרָה אֹרַח כַּנָּשִׁים. וְאוֹתָהּ שָׁעָה רָאֲתָה עַצְמָהּ בְּעִדּוּן אַחֵר, וְלָכֵן אָמְרָה וַאדֹנִי זָקֵן, שֶׁהֲרֵי הוּא לֹא כְדַאי לְהוֹלִיד כִּי הוּא זָקֵן.</p>"],[9522011224,"<p>רַבִּי יְהוּדָה פָּתַח, (משלי לא) נוֹדַע בַּשְּׁעָרִים בַּעְלָהּ בְּשִׁבְתּוֹ עִם זִקְנֵי אָרֶץ. בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַלֶּה בִּכְבוֹדוֹ שֶׁהוּא גָנוּז וְנִסְתָּר בְּעִלּוּי רַב. לֹא הָיָה בָּעוֹלָם וְלֹא הָיָה מֵהַיּוֹם שֶׁנִּבְרָא הָעוֹלָם שֶׁיָּכוֹל לַעֲמֹד עַל חָכְמָתוֹ וְלֹא יָכוֹל לַעֲמֹד בּוֹ.</p>\n<p>מִשּׁוּם כִּי הוּא גָנוּז וְנִסְתָּר וְהִתְעַלָּה לְמַעְלָה לְמַעְלָה, וְכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים לֹא יְכוֹלִים לְהִתְדַּבֵּק עַד שֶׁכֻּלָּם אוֹמְרִים (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. הַתַּחְתּוֹנִים אוֹמְרִים שֶׁהוּא לְמַעְלָה, שֶׁכָּתוּב (תהלים קיג) עַל הַשָּׁמַיִם כְּבוֹדוֹ. הָעֶלְיוֹנִים אוֹמְרִים שֶׁהוּא לְמַטָּה, שֶׁכָּתוּב (שם נז) עַל כָּל הָאָרֶץ כְּבוֹדֶךְ. עַד שֶׁכֻּלָּם, עֶלְיוֹנִים וְתַחְתּוֹנִים, אוֹמְרִים בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ, כִּי לֹא נוֹדַע וְלֹא הָיָה מִי שֶׁיָּכוֹל לַעֲמֹד עִמּוֹ, וְאַתָּה אוֹמֵר נוֹדָע בַּשְּׁעָרִים בַּעְלָהּ?</p>\n<p>אֶלָּא וַדַּאי נוֹדָע בַּשְּׁעָרִים בַּעְלָהּ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא נוֹדָע וְנִדְבָּק לְפִי מַה שֶּׁמְּשַׁעֵר בְּלִבּוֹ כָּל אֶחָד כַּמָּה שֶׁיָּכוֹל לְהִדָּבֵק בָּרוּחַ שֶׁל הַחָכְמָה. וּלְפִי מַה שֶּׁמְּשַׁעֵר בְּלִבּוֹ, כָּךְ נוֹדָע בְּלִבּוֹ, וְלָכֵן נוֹדָע בַּשְּׁעָרִים - בְּאוֹתָם הַשְּׁעָרִים. אֲבָל שֶׁנּוֹדָע כָּרָאוּי אֵין מִי שֶׁיָּכוֹל לְהִדָּבֵק וְלָדַעַת אוֹתוֹ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, נוֹדָע בַּשְּׁעָרִים בַּעְלָהּ, אֵיזֶה שְׁעָרִים? כְּמוֹ שֶׁנֶּאֱמַר (תהלים כד) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְהִנָּשְׂאוּ פִּתְחֵי עוֹלָם. וּמִשּׁוּם הַשְּׁעָרִים הַלָּלוּ, שֶׁהֵם דְּרָגוֹת עֶלְיוֹנוֹת, בִּגְלָלָם נוֹדָע הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאִם לֹא - לֹא יְכוֹלִים לְהִתְדַּבֵּק בּוֹ.</p>\n<p>בֹּא רְאֵה, הֲרֵי נִשְׁמַת הָאָדָם אֵין הוּא (אין) מִי שֶׁיָּכוֹל לָדַעַת אוֹתָהּ, אֶלָּא עַל יְדֵי אֶבְרֵי הַגּוּף, וְהֵם הַדְּרָגוֹת שֶׁעוֹשׂוֹת אֻמָּנוּת הַנְּשָׁמָה. מִשּׁוּם כָּךְ נוֹדָע וְלֹא נוֹדָע. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹדָע וְלֹא נוֹדָע, מִשּׁוּם שֶׁהוּא נְשָׁמָה לִנְשָׁמָה, רוּחַ לְרוּחַ, גָּנוּז וְטָמִיר מִן הַכֹּל. אֲבָל בְּאוֹתָם הַשְּׁעָרִים, שֶׁהֵם פְּתָחִים לַנְּשָׁמָה, נוֹדָע הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>בֹּא רְאֵה, יֵשׁ פֶּתַח לְפֶתַח וְדַרְגָּה לְדַרְגָּה, וּמֵהֶם יָדוּעַ כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. פֶּתַח הָאֹהֶל - זֶהוּ פֶּתַח שֶׁל צֶדֶק, כְּמוֹ שֶׁנֶּאֱמַר (שם קיח) פִּתְח\"וּ לִ\"י שַׁעֲרֵ\"י צֶדֶ\"ק וְגוֹ'. זֶהוּ פֶּתַח רִאשׁוֹן לְהִכָּנֵס בּוֹ, וּבַפֶּתַח הַזֶּה נִרְאִים כָּל שְׁאָר הַפְּתָחִים הָעֶלְיוֹנִים. מִי שֶׁזּוֹכֶה לָזֶה (לפתח), זוֹכֶה לָדַעַת אוֹתוֹ וּבְכָל שְׁאָר הַפְּתָחִים, מִשּׁוּם שֶׁכֻּלָּם שׁוֹרִים עָלָיו.</p>\n<p>וְעַכְשָׁו שֶׁפֶּתַח זֶה לֹא נוֹדָע, מִשּׁוּם שֶׁיִּשְׂרָאֵל בַּגָּלוּת וְכָל הַפְּתָחִים הִסְתַּלְּקוּ מִמֶּנּוּ וְלֹא יְכוֹלִים לָדַעַת וְלִדְבּק. אֲבָל בִּזְמַן שֶׁיִּשְׂרָאֵל יֵצְאוּ מִן הַגָּלוּת, עֲתִידוֹת כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת לִשְׁרוֹת עָלָיו כָּרָאוּי.</p>\n<p>וְאָז יָדְעוּ בְּנֵי הָעוֹלָם חָכְמָה עֶלְיוֹנָה נִכְבָּדָה מַה שֶּׁלֹּא הָיוּ יוֹדְעִים מִקֹּדֶם לָזֶה, שֶׁכָּתוּב (ישעיה יא) וְנָחָה עָלָיו רוּחַ ה' רוּחַ חָכְמָה וּבִינָה רוּחַ עֵצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת ה'. כֻּלָּם עֲתִידִים לִשְׁרוֹת עַל הַפֶּתַח הַתַּחְתּוֹן הַזֶּה, שֶׁהוּא פֶּתַח הָאֹהֶל, וְכֻלָּם עֲתִידִים לִשְׁרוֹת עַל מֶלֶךְ הַמָּשִׁיחַ כְּדֵי לָדוּן הָעוֹלָם, שֶׁכָּתוּב וְשָׁפַט בְּצֶדֶק דַּלִּים וְגוֹ'.</p>\n<p>מִשּׁוּם כָּךְ, כְּשֶׁהִתְבַּשֵּׂר אַבְרָהָם, הַדַּרְגָּה הַזּוֹ הָיְתָה אוֹמֶרֶת כְּמוֹ שֶׁנִּתְבָּאֵר שֶׁכָּתוּב שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה. וַיֹּאמֶר - לֹא כָּתוּב מִי הָיָה, וְזֶהוּ פֶּתַח הָאֹהֶל. וְעַל זֶה וְשָׂרָה שּמַעַת דַּרְגָּה זוֹ שֶׁהָיְתָה מְדַבֶּרֶת עִמּוֹ מַה שֶּׁלֹּא הָיְתָה שׁוֹמַעַת מִקֹּדֶם לָזֶה, שֶׁכָּתוּב וְשָׂרָה שּמַעַת פֶּתַח הָאֹהֶל, שֶׁהָיְתָה מְבַשֶּׂרֶת וְאוֹמֶרֶת שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה וְהִנֵּה בֵן לְשָׂרָה אִשְׁתְּךְ.</p>\n<p>בֹּא רְאֵה כַּמָּה חֲבִיבוּת הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם, שֶׁהֲרֵי לֹא יָצָא מִמֶּנּוּ יִצְחָק עַד שֶׁנִּמּוֹל. אַחַר שֶׁנִּמּוֹל הִתְבַּשֵּׂר עַל יִצְחָק, מִשּׁוּם שֶׁאָז הוּא זֶרַע קָדוֹשׁ, וְטֶרֶם שֶׁנִּמּוֹל אֵינוֹ זֶרַע קָדוֹשׁ, וְאָז הוּא כְּמוֹ שֶׁכָּתוּב (בראשית א) אֲשֶׁר זַרְעוֹ בוֹ לְמִינֵהוּ.</p>\n<p>וּבֹא וּרְאֵה, טֶרֶם שֶׁנִּמּוֹל אַבְרָהָם זַרְעוֹ לֹא הָיָה קָדוֹשׁ, מִשּׁוּם שֶׁיָּצָא מִתּוֹךְ עָרְלָה וְהִדְבַּק בָּעָרְלָה לְמַטָּה. אַחַר שֶׁנִּמּוֹל, יָצָא אוֹתוֹ הַזֶּרַע בְּתוֹךְ הַקְּדֻשָּׁה, וְנִדְבַּק בַּקְּדֻשָּׁה שֶׁלְּמַעְלָה וְהוֹלִיד לְמַעְלָה, וְנִדְבַּק אַבְרָהָם בְּדַרְגָּתוֹ כָּרָאוּי. בֹּא רְאֵה, כְּשֶׁהוֹלִיד אַבְרָהָם אֶת יִצְחָק, יָצָא קָדוֹשׁ כָּרָאוּי. וְאֵלּוּ (ודאי) הַמַּיִם שֶּׁהָרוּ וְהוֹלִידוּ חֹשֶׁךְ.</p>\n<p>רַבִּי אֶלְעָזָר שָׁאַל יוֹם אֶחָד אֶת רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, זֶה שֶׁקָּרָא לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא יִצְחָק, שֶׁכָּתוּב וְקָרָאתָ אֶת שְׁמוֹ יִצְחָק, לָמָּה? שֶׁהֲרֵי נִרְאֶה שֶׁעַד שֶׁלֹּא יָצָא לָעוֹלָם קָרָא לוֹ יִצְחָק?</p>\n<p>אָמַר לוֹ, הֲרֵי נֶאֱמַר שֶׁאֵשׁ לוֹקַחַת מַיִם, שֶׁהֲרֵי הַמַּיִם בָּאִים מִצַּד שֶׁל הַגְּבוּרָה, וְעוֹד (נ\"א: ובא תשאל מהלוים) (שאל אותו) הַלְוִיִּם שֶׁהֵם מְשַׂמְּחִים לְאוֹתוֹ הַצַּד בִּכְלֵי זֶמֶר וְתִשְׁבָּחוֹת כְּנֶגֶד הַצַּד הַזֶּה, מִשּׁוּם כָּךְ יִצְחָק הוּא חֶדְוָה, מִשּׁוּם שֶׁהוּא בָּא מֵאוֹתוֹ צַד וְנִדְבָּק בּוֹ.</p>\n<p>בֹּא רְאֵה, יִצְחָק צְחוֹק, חֶדְוָה שֶׁמַּחֲלִיפָה מַיִם בְּאֵשׁ וְאֵשׁ בְּמַיִם, וְעַל זֶה נִקְרָא כָּךְ. וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לוֹ כָּךְ בְּטֶרֶם יָצָא לָעוֹלָם בְּשֵׁם זֶה וְהוֹדִיעַ לְאַבְרָהָם.</p>\n<p>וּבֹא וּרְאֵה, בְּכָל הָאֲחֵרִים הִשְׁאִיר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לִקְרֹא לָהֶם שֵׁמוֹת, וַאֲפִלּוּ נָשִׁים הָיוּ קוֹרְאוֹת לִבְנֵיהֶן שֵׁמוֹת, אֲבָל כָּאן לֹא הִשְׁאִיר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאִמּוֹ לִקְרֹא לוֹ שֵׁם, אֶלָּא לְאַבְרָהָם, שֶׁכָּתוּב וְקָרָאתָ אֶת שְׁמוֹ יִצְחָק. אַתָּה וְלֹא אַחֵר. כְּדֵי לְהַחֲלִיף מַיִם בְּאֵשׁ וְאֵשׁ בְּמַיִם לְהַכְלִילוֹ בְּצִדּוֹ.</p>"],[9522011225,"<p>כֵּיוָן שֶׁהִתְבַּשֵּׂר אַבְרָהָם בְּיִצְחָק, מַה כָּתוּב? וַיָּקֻמוּ מִשָּׁם הָאֲנָשִׁים וַיַּשְׁקִפוּ עַל פְּנֵי סְדם. רַבִּי אֶלְעָזָר אָמַר, בֹּא רְאֵה כַּמָּה נוֹהֵג הַקָּדוֹשׁ בָּרוּךְ הוּא טוֹבָה עִם כָּל הַבְּרִיּוֹת, וְכָל שֶׁכֵּן לְאוֹתָם שֶׁהוֹלְכִים בִּדְרָכָיו, שֶׁאֲפִלּוּ בִּזְמַן שֶׁרוֹצֶה לָדוּן אֶת הָעוֹלָם, הוּא גוֹרֵם לְמִי שֶׁאוֹהֵב אוֹתוֹ לִזְכּוֹת בַּדָּבָר עַד שֶׁלֹּא יָבא אוֹתוֹ הַדִּין לָעוֹלָם.</p>\n<p>שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֵב אֶת הָאָדָם, שׁוֹלֵחַ לוֹ דּוֹרוֹן, וּמִיהוּ? הֶעָנִי, כְּדֵי לִזְכּוֹת בּוֹ. וְכֵיוָן שֶׁזּוֹכֶה בּוֹ, הוּא מוֹשֵׁךְ עָלָיו חוּט אֶחָד שֶׁל חֶסֶד שֶׁנִּמְשָׁךְ מִצַּד הַיָּמִין וּפוֹרֵס עַל רֹאשׁוֹ וְרוֹשֵׁם אוֹתוֹ, כְּדֵי שֶׁכְּשֶׁיָּבֹא הַדִּין לָעוֹלָם, אוֹתוֹ הַמַּשְׁחִית יִזָּהֵר בּוֹ, וּמֵרִים עֵינָיו וְרוֹאֶה אוֹתוֹ הָרֹשֶׁם, וְאָז מִסְתַּלֵּק מִמֶּנּוּ וְנִזְהָר עָלָיו. מִשּׁוּם כָּךְ מַקְדִּים הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַה שֶּׁיִּזְכֶּה.</p>\n<p>וּבֹא וּרְאֵה, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָבִיא דִין עַל סְדם, זִכָּה קֹדֶם אֶת אַבְרָהָם וְשָׁלַח לוֹ דּוֹרוֹן לִזְכּוֹת עִמָּהֶם כְּדֵי לְהַצִּיל אֶת לוֹט בֶּן אָחִיו מִשָּׁם. זֶהוּ שֶׁכָּתוּב וַיִּזְכֹּר אֱלֹהִים אֶת אַבְרָהָם וַיְשַׁלַּח אֶת לוֹט מִתּוֹךְ הַהֲפֵכָה, וְלֹא כָתוּב וַיִּזְכֹּר אֱלֹהִים אֶת לוֹט, שֶׁהֲרֵי בִּזְכוּת אַבְרָהָם נִצַּל. וּמַה זֶּה וַיִּזְכֹּר? שֶׁזָּכַר אוֹתוֹ מַה שֶּׁזָּכָה קֹדֶם עִם אוֹתָם שְׁלֹשֶׁת הַמַּלְאָכִים.</p>\n<p>כְּמוֹ זֶה, בֶּן אָדָם שֶׁזּוֹכֶה בִּצְדָקָה עִם בְּנֵי אָדָם, בְּשָׁעָה שֶׁדִּין שָׁרוּי בָּעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא זוֹכֵר לוֹ אֶת אוֹתָהּ הַצְּדָקָה שֶׁעָשָׂה. מִשּׁוּם שֶׁבְּכָל שָׁעָה שֶׁזּוֹכֶה בֶּן אָדָם, כָּךְ נִכְתָב עָלָיו לְמַעְלָה. וַאֲפִלּוּ בְּשָׁעָה שֶׁדִּין שׁוֹרֶה עָלָיו, הַקָּדוֹשׁ בָּרוּךְ הוּא זוֹכֵר אֶת אוֹתוֹ הַטּוֹב שֶׁעָשָׂה וְזָכָה עִם בְּנֵי אָדָם, כְּמוֹ שֶׁנֶּאֱמַר (משלי יא) וּצְדָקָה תַּצִּיל מִמָּוֶת. מִשּׁוּם כָּךְ הִקְדִּים הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם, כְּדֵי שֶׁיִּזְכֶּה וְיַצִּיל אֶת לוֹט.</p>\n<p>וַיַּשְׁקִפוּ עַל פְּנֵי סְדם. בֹּא רְאֵה, וַיָּקֻמוּ הָאֲנָשִׁים מִשָּׁם, מֵאוֹתָהּ סְעוּדָה שֶׁתִּקֵּן לָהֶם אַבְרָהָם וְזָכָה בָהֶם. אַף עַל גַּב שֶׁהָיוּ מַלְאָכִים, זָכָה בָהֶם. וְכָל אוֹתוֹ מַאֲכָל לֹא נִשְׁאַר מִמֶּנּוּ כְּלוּם, מִשּׁוּם אַבְרָהָם, וּלְזַכּוֹתוֹ, שֶׁהֲרֵי כָּתוּב וַיֹּאכֵלוּ, בָּאֵשׁ שֶׁלָּהֶם נֶאֱכַל.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי שְׁלֹשָׁה מַלְאָכִים הָיוּ? זֶה אֵ\"שׁ וְזֶה מַיִ\"ם וְזֶה רוּ\"חַ. אֶלָּא כָּל אֶחָד וְאֶחָד כָּלוּל בַּחֲבֵרוֹ, וּמִשּׁוּם כָּךְ וַיֹּאכֵלוּ. כְּמוֹ זֶה (שמות כד) וַיֶּחֱזוּ אֶת הָאֱלֹהִים וַיֹּאכְלוּ וַיִּשְׁתּוּ. אֲכִילָה וַדָּאִית הֵם אָכְלוּ, שֶׁנִּזּוֹנוּ מֵהַשְּׁכִינָה. אַף כָּאן וַיֹּאכֵלוּ - גָּרְמוּ (נ\"א: נרמז רמז) לְהִזּוֹן (ממנו) מֵאוֹתוֹ הַצַּד שֶׁאַבְרָהָם נִדְבַּק בּוֹ, וּמִשּׁוּם כָּךְ לֹא הִשְׁאִירוּ כְלוּם מִמַּה שֶּׁנָּתַן לָהֶם אַבְרָהָם.</p>\n<p>כְּמוֹ כֵן צָרִיךְ הָאָדָם לִשְׁתוֹת מֵאוֹתָהּ כּוֹס שֶׁל בְּרָכָה כְּדֵי שֶׁיִּזְכֶּה לְאוֹתָהּ בְּרָכָה שֶׁלְּמַעְלָה, אַף הֵם אָכְלוּ מִמַּה שֶּׁתִּקֵּן לָהֶם אַבְרָהָם כְּדֵי שֶׁיִּזְכּוּ לְהִזּוֹן מֵהַצַּד שֶׁל אַבְרָהָם, שֶׁהֲרֵי מֵאוֹתוֹ צַד יוֹצֵא מָזוֹן לְכָל הַמַּלְאָכִים הָעֶלְיוֹנִים.</p>\n<p>וַיַּשְׁקִפוּ, הִתְעוֹרְרוּת שֶׁל רַחֲמִים לְהַצִּיל אֶת לוֹט. כָּתוּב כָּאן וַיַּשְׁקִפוּ, וְכָתוּב שָׁם (דברים כו) הַשְׁקִיפָה מִמְּעוֹן קָדְשֶׁךְ. מַה לְּהַלָּן לְרַחֲמִים - אַף כָּאן לְרַחֲמִים.</p>\n<p>וְאַבְרָהָם הֹלֵךְ עִמָּם לְשַׁלְּחָם, לַעֲשׂוֹת לָהֶם לְוָיָה. אָמַר רַבִּי יֵיסָא, אִם תֹּאמַר שֶׁאַבְרָהָם יָדַע שֶׁהֵם מַלְאָכִים, לָמָּה עָשָׂה לָהֶם לְוָיָה? אֶלָּא, אָמַר רַבִּי אֶלְעָזָר, אַף עַל גַּב שֶׁיָּדַע (רגיל היה לעשות לכל בני האדם שמזמנים עמו לעשות להם לויה). (מה שהיה רגיל לעשות עם בני אדם עשה בהם ולוה אותם), מִשּׁוּם שֶׁכָּךְ צָרִיךְ לָאָדָם לַעֲשׂוֹת לְוָיָה לָאוֹרְחִים, שֶׁהֲרֵי הַכֹּל תָּלוּי בָּזֶה.</p>\n<p>וּבְעוֹד שֶׁהוּא הָיָה הוֹלֵךְ עִמָּם, הִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶל אַבְרָהָם, שֶׁכָּתוּב וַה' אָמָר הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם אֲשֶׁר אֲנִי עֹשֶׂה. וַה' - הוּא וּבֵית דִּינוֹ, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה הוֹלֵךְ עִמָּם.</p>\n<p>בֹּא רְאֵה, כְּשֶׁבֶּן אָדָם עוֹשֶׂה לְוָיָה (לאדם) לַחֲבֵרוֹ, הוּא מוֹשֵׁךְ אֶת הַשְּׁכִינָה לְהִתְחַבֵּר עִמּוֹ וְלָלֶכֶת עִמּוֹ בַּדֶּרֶךְ לְהַצִּילוֹ, וְלָכֵן צָרִיךְ אָדָם לְלַוּוֹת אֶת הָאוֹרֵחַ כְּדֵי לְחַבֵּר עִמּוֹ שְׁכִינָה וּמוֹשֵׁךְ עָלָיו לְהִתְחַבֵּר עִמּוֹ.</p>"],[9522011226,"<p>מִשּׁוּם כָּךְ, וַה' אָמָר הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם אֲשֶׁר אֲנִי עֹשֶׂה. רַבִּי חִיָּיא פָּתַח, (עמוס ג) כִּי לֹא יַעֲשֶׂה ה' אֱלֹהִים דָּבָר כִּי אִם גָּלָה סוֹדוֹ אֶל עֲבָדָיו הַנְּבִיאִים. אַשְׁרֵיהֶם צַדִּיקֵי הָעוֹלָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם, וְכָל מַה שֶּׁהוּא עוֹשֶׂה בָּרָקִיעַ וְעָתִיד לַעֲשׂוֹת בָּעוֹלָם - עַל יְדֵי הַצַּדִּיקִים עוֹשֶׂה אוֹתוֹ, וְלֹא מְכַסֶּה מֵהֶם כְּלוּם לְעוֹלָמִים,</p>\n<p>כִּי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְשַׁתֵּף עִמּוֹ אֶת (הצדיקים שלא יהיה פתחון פה לרשעים בכל מה שהוא עושה, בא ראה, הכל מגלה הקדוש ברוך הוא) לַצַּדִּיקִים, מִשּׁוּם שֶׁהֵם בָּאִים וּמַזְהִירִים אֶת בְּנֵי הָאָדָם לָשׁוּב מֵחֲטָאֵיהֶם וְלֹא יֵעָנְשׁוּ מִתּוֹךְ הַדִּין הָעֶלְיוֹן וְלֹא יִהְיֶה לָהֶם פִּתְחוֹן פֶּה אֵלָיו. מִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹדִיעַ לָהֶם הַסּוֹד שֶׁהוּא עוֹשֶׂה בָהֶם הַדִּין. וְעוֹד, כְּדֵי שֶׁלֹּא יֹאמְרוּ שֶׁהֲרֵי בְּלִי דִין עָשָׂה בָהֶם דִּין.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אוֹי לָרְשָׁעִים שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים וְלֹא יוֹדְעִים לְהִשָּׁמֵר מֵחֲטָאֵיהֶם. וּמָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁכָּל מַעֲשָׂיו אֱמֶת וּדְרָכָיו דִּין אֵינוֹ עוֹשֶׂה כָּל מַה שֶּׁעוֹשֶׂה בָּעוֹלָם עַד שֶׁמְּגַלֶּה לַצַּדִּיקִים כְּדֵי שֶׁלֹּא יִהְיֶה לָהֶם פִּתְחוֹן פֶּה לִבְנֵי אָדָם, אֵצֶל בְּנֵי אָדָם לֹא כָּל שֶׁכֵּן שֶׁיֵּשׁ לָהֶם לַעֲשׂוֹת דִּבְרֵיהֶם שֶׁלֹּא יְדַבְּרוּ בְּנֵי אָדָם לָשׁוֹן הָרָע בָּהֶם. וְכֵן כָּתוּב (במדבר לב) וִהְיִיתֶם נְקִיִּים מֵה' וּמִיִּשְׂרָאֵל.</p>\n<p>וְיֵשׁ לָהֶם לַעֲשׂוֹת שֶׁלֹּא יִהְיֶה לָהֶם פִּתְחוֹן פֶּה לִבְנֵי אָדָם, וְיַתְרוּ בָהֶם אִם הֵם חוֹטְאִים וְלֹא מַשְׁגִּיחִים לְהִשָּׁמֵר, שֶׁלֹּא תִהְיֶה לְמִדַּת הַדִּין שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא פִּתְחוֹן פֶּה אֲלֵיהֶם, וּבַמֶּה? בִּתְשׁוּבָה וּמַעֲשִׂים כְּשֵׁרִים.</p>\n<p>בֹּא רְאֵה, וַה' אָמָר הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם. אָמַר רַבִּי יְהוּדָה, הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן אֶת כָּל הָאָרֶץ לְאַבְרָהָם לִהְיוֹת לוֹ נַחֲלַת יְרֻשָּׁה לְעוֹלָמִים, שֶׁכָּתוּב כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רֹאֶה לְךְ אֶתְּנֶנָּה וְגוֹ', וְכָתוּב שָׂא נָא עֵינֶיךְ וּרְאֵה. וּלְאַחַר מִכֵּן הִצְטָרֵךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲקֹר אֶת הַמְּקוֹמוֹת הַלָּלוּ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּבָר נָתַתִּי אֶת הָאָרֶץ לְאַבְרָהָם, וְהוּא אָב לַכֹּל, שֶׁכָּתוּב כִּי אַב הֲמוֹן גּוֹיִם נְתַתִּיךְ, וְלֹא נָאֶה לִי לִמְחוֹת בָּנִים בְּלִי לְהוֹדִיעַ לַאֲבִיהֶם שֶׁקָּרָאתִי לוֹ אַבְרָהָם אֹהֲבִי, וּמִשּׁוּם כָּךְ צָרִיךְ לְהוֹדִיעוֹ, מִשּׁוּם כָּךְ (אמר) וַה' אָמָר הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם אֲשֶׁר אֲנִי עֹשֶׂה.</p>\n<p>אָמַר רַבִּי אַבָּא, בֹּא רְאֵה עַנְוְתָנוּתוֹ שֶׁל אַבְרָהָם, שֶׁאַף עַל גַּב שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא זַעֲקַת סְדם וַעֲמֹרָה כִּי רָבָּה, וְעִם כָּל זֶה שֶׁהֶאֱרִיךְ עִמּוֹ וְהוֹדִיעַ לוֹ שֶׁרוֹצֶה לַעֲשׂוֹת דִּין בִּסְדם, לֹא בִקֵּשׁ מִמֶּנּוּ לְהַצִּיל אֶת לוֹט וְלֹא יַעֲשֶׂה בּוֹ דִּין. מָה הַטַּעַם בִּשְׁבִיל? שֶׁלֹּא לִתְבּעַ שָׂכָר מִמַּעֲשָׂיו.</p>\n<p>וְעַל זֶה שָׁלַח הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת לוֹט וְהִצִּילוֹ מִשּׁוּם אַבְרָהָם, שֶׁכָּתוּב וַיִּזְכֹּר אֱלֹהִים אֶת אַבְרָהָם וַיְשַׁלַּח אֶת לוֹט מִתּוֹךְ הַהֲפֵכָה וְגוֹ'.</p>\n<p>מַה זֶּה אֲשֶׁר יָשַׁב בָּהֵן לוֹט? הֲרֵי נֶאֱמַר, אֲבָל מִשּׁוּם שֶׁכֻּלָּם רְשָׁעִים וְלֹא נִמְצָא (ביניהם) מִכֻּלָּם שֶׁיֵּשׁ לוֹ דְּבַר זְכוּת פְּרָט לְלוֹט. מִכָּאן לָמַדְנוּ, שֶׁבְּכָל מָקוֹם שֶׁדָּרִים בּוֹ רְשָׁעִים הוּא חָרֵב.</p>\n<p>אֲשֶׁר יָשַׁב בָּהֵן לוֹט, וְכִי בְּכֻלָּם יָשַׁב לוֹט? אֶלָּא בִּגְלָלוֹ הָיוּ מְיֻשָּׁבִים וְלֹא חָרְבוּ. וְאִם תֹּאמַר בִּזְכוּתוֹ - לֹא! אֶלָּא בִּזְכוּת אַבְרָהָם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה שֶׁשִּׁמּוּשׁ שֶׁאָדָם עוֹשֶׂה לְצַדִּיק, אוֹתוֹ שִׁמּוּשׁ מֵגֵן עָלָיו בָּעוֹלָם, וְלֹא עוֹד, אֶלָּא שֶׁאַף עַל גַּב שֶׁהוּא רָשָׁע, לוֹמֵד מִדְּרָכָיו וְעוֹשֶׂה אוֹתָם.</p>\n<p>בֹּא רְאֵה, שֶׁהֲרֵי מִשּׁוּם שֶׁהִתְחַבֵּר לוֹט עִם אַבְרָהָם - אַף עַל גַּב שֶׁלֹּא לָמַד כָּל מַעֲשָׂיו, לָמַד לַעֲשׂוֹת חֶסֶד עִם הַבְּרִיּוֹת כְּמוֹ שֶׁהָיָה עוֹשֶׂה אַבְרָהָם, וְזֶהוּ שֶׁהָיָה מְיַשֵּׁב אֶת כָּל אוֹתָן הֶעָרִים כָּל אוֹתוֹ זְמַן שֶׁהָיוּ מְיֻשָּׁבִים אַחַר שֶׁנִּכְנַס לוֹט בֵּינֵיהֶם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בּא רְאֵה שֶׁשְּׁכִינָה לֹא זָזָה מֵאַבְרָהָם בְּאוֹתָהּ שָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ (באותו זמן שהקדוש ברוך הוא עמו). אָמַר לוֹ רַבִּי אֶלְעָזָר, וַהֲרֵי שְׁכִינָה הָיְתָה מְדַבֶּרֶת עִמּוֹ, שֶׁהֲרֵי (בדרגה) זוֹ הִתְגַּלָּה אֵלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (שמות ו) וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי. אָמַר לוֹ, כָּךְ זֶה וַדַּאי.</p>\n<p>וּבֹא וּרְאֵה מַה כָּתוּב, וַיֹּאמֶר ה' זַעֲקַת סְדם וַעֲמֹרָה כִּי רָבָּה. בַּהַתְחָלָה וַה' אָמָר, וּלְבַסּוֹף וַיֹּאמֶר ה' זַעֲקַת סְדם וַעֲמֹרָה וְגוֹ'. זוֹהִי הַדַּרְגָּה הָעֶלְיוֹנָה שֶׁהִתְגַּלְּתָה לוֹ עַל הַדַּרְגָּה הַתַּחְתּוֹנָה.</p>\n<p>וַה' אָמָר הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם וְגוֹ'. מַה כָּתוּב לְמַעְלָה? וַיָּקֻמוּ מִשָּׁם הָאֲנָשִׁים וַיַּשְׁקִפוּ עַל פְּנֵי סְדם, לַעֲשׂוֹת דִּין בָּרְשָׁעִים. מַה כָּתוּב אַחֲרָיו? הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם.</p>\n<p>אָמַר רַב חַסְדָּא, אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִין בָּרְשָׁעִים עַד שֶׁנִּמְלָךְ בְּנִשְׁמָתָם שֶׁל צַדִּיקִים. זֶהוּ שֶׁכָּתוּב (איוב ד) מִנִּשְׁמַת אֱלוֹהַּ יאבֵדוּ. וְכָתוּב הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: כְּלוּם יֵשׁ לִי לַעֲשׂוֹת דִּין בָּרְשָׁעִים עַד שֶׁאֶמָּלֵךְ בְּנִשְׁמוֹת הַצַּדִּיקִים. וְאוֹמֵר לָהֶם: הָרְשָׁעִים חָטְאוּ לְפָנַי, אֶעֱשֶׂה בָהֶם דִּין, שֶׁכָּתוּב וַיֹּאמֶר ה' זַעֲקַת סְדם וַעֲמֹרָה כִּי רָבָּה וְחַטָּאתָם וְגוֹ'.</p>\n<p>אָמַר רַבִּי אַבָּהוּ, הַנְּשָׁמָה עוֹמֶדֶת בִּמְקוֹמָהּ, וְהִיא יְרֵאָה לְהִתְקָרֵב אֵלָיו וְלוֹמַר לְפָנָיו כְּלוּם, עַד שֶׁיֹּאמַר לְמטטרו\"ן שֶׁיַּגִּישֶׁנָּה לְפָניו וְתֹאמַר מַה שֶּׁרָצְתָה. זֶהוּ שֶׁכָּתוּב וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר הַאַף תִּסְפֶּה צַדִּיק עִם רָשָׁע וְגוֹ', חָלִילָה לְּךְ וְגוֹ'.</p>\n<p>אוּלַי יֵשׁ חֲמִשִּׁים צַדִּיקִם וְגוֹ'. הַנְּשָׁמָה פּוֹתַחַת וְאוֹמֶרֶת: רִבּוֹנוֹ שֶׁל עוֹלָם, שֶׁמָּא נִתְעַסְּקוּ בַּחֲמִשִּׁים פָּרָשִׁיּוֹת שֶׁל תּוֹרָה, וְאַף עַל פִּי שֶׁלֹּא נִתְעַסְּקוּ לִשְׁמָהּ, שָׂכָר יֵשׁ לָהֶם לָעוֹלָם הַבָּא וְלֹא יִכָּנְסוּ לַגֵּיהִנֹּם. מַה כָּתוּב אַחֲרָיו? וַיֹּאמֶר ה' אִם אֶמְצָא בִסְדֹם חֲמִשִּׁים צַדִּיקִים וְגוֹ'.</p>\n<p>וַהֲרֵי (שנינו), אוֹתָן פָּרָשִׁיּוֹת יְתֵרוֹת חֲמִשִּׁים וְשָׁלֹשׁ הָיוּ. אֶלָּא, אָמַר רַבִּי אַבָּהוּ, חֲמִשָּׁה סְפָרִים הֵם בַּתּוֹרָה, וּבְכָל אֶחָד וְאֶחָד נִכְלָלִים עֲשֶׂרֶת הַדִּבְּרוֹת עֲשָׂרָה מַאֲמָרוֹת שֶׁבָּהֶם נִבְרָא הָעוֹלָם. חֲשֹׁב עֲשָׂרָה בְּכָל אֶחָד מֵהֶם - הוּא חֲמִשִּׁים.</p>\n<p>עוֹד פּוֹתַחַת הַנְּשָׁמָה וְאוֹמֶרֶת: רִבּוֹנוֹ שֶׁל עוֹלָם, אַף עַל פִּי שֶׁלֹּא נִתְעַסְּקוּ בַּתּוֹרָה, שֶׁמָּא קִבְּלוּ עָנְשָׁם עַל מַה שֶּׁחָטְאוּ בְּבֵית דִּין וְנִתְכַּפֵּר לָהֶם, שֶׁנֶּאֱמַר (דברים כה) אַרְבָּעִים יַכֶּנּוּ לֹא יֹסִיף. וּמִמַּה שֶּׁנִּתְבַּיְּשׁוּ לִפְנֵיהֶם, דַּיָּם לְהִתְכַּפֵּר (לפניהם) לָהֶם שֶׁלֹּא יִכָּנְסוּ לַגֵּיהִנֹּם. מַה כָּתוּב אַחֲרָיו? לֹא אֶעֱשֶׂה בַּעֲבוּר הָאַרְבָּעִים.</p>\n<p>עוֹד פּוֹתַחַת וְאוֹמֶרֶת: אוּלַי יֵשׁ שָׁם שְׁלֹשִׁים? אוּלַי יֵשׁ בֵּינֵיהֶם צַדִּיקִים שֶׁהִשִּׂיגוּ שְׁלֹשִׁים מַעֲלוֹת הָרְמוּזִים בְּפָסוּק (יחזקאל א) וַיְהִי בִּשְׁלֹשִׁים שָׁנָה, וְהֵם כְּלוּלִים בְּל\"ב נְתִיבוֹת, שֶׁהֵם כ\"ב אוֹתִיּוֹת וְי' סְפִירוֹת, לִפְעָמִים הֵם כְּלוּלִים לִשְׁמֹנָה.</p>\n<p>עוֹד פּוֹתַחַת וְאוֹמֶרֶת: אוּלַי יִמָּצְאוּן שָׁם עֶשְׂרִים, שֶׁמָּא יְגַדְּלוּ בָנִים לְתַלְמוּד תּוֹרָה וְיֵשׁ לָהֶם שָׂכָר לַעֲשֶׂרֶת הַדִּבְּרוֹת שְׁתֵּי פְעָמִים בְּכָל יוֹם, שֶׁאָמַר רַבִּי יִצְחָק, כָּל הַמְגַדֵּל בְּנוֹ לְתַלְמוּד תּוֹרָה וּמוֹלִיכוֹ לְבֵית רַבּוֹ בַּבֹּקֶר וּבָעֶרֶב, מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ קִיֵּם (עליו) הַתּוֹרָה שְׁתֵּי פְעָמִים בְּכָל יוֹם. מַה כָּתוּב? וַיֹּאמֶר לֹא אַשְׁחִית בַּעֲבוּר הָעֶשְׂרִים.</p>\n<p>עוֹד פּוֹתַחַת וְאוֹמֶרֶת: אוּלַי יִמָּצְאוּן שָׁם עֲשָׂרָה. אוֹמֶרֶת: רִבּוֹנוֹ שֶׁל עוֹלָם, שֶׁמָּא הָיוּ מֵאוֹתָם הָעֲשָׂרָה הָרִאשׁוֹנִים שֶׁל בֵּית הַכְּנֶסֶת שֶׁנּוֹטֵל שָׂכָר כְּנֶגֶד כֻּלָּם שֶׁבָּאִים אַחֲרֵיהֶם. מַה כָּתוּב (בו)? וַיֹּאמֶר לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה.</p>\n<p>כָּל זֶה יֵשׁ לְנִשְׁמַת הַצַּדִּיק לוֹמַר עַל הָרְשָׁעִים. כֵּיוָן שֶׁלֹּא נִמְצָא בְיָדָם כְּלוּם, מַה כָּתוּב? וַיֵּלֶךְ ה' כַּאֲשֶׁר כִּלָּה לְדַבֵּר אֶל אַבְרָהָם וְאַבְרָהָם שָׁב לִמְקֹמוֹ. מַהוּ לִמְקֹמוֹ? לִמְקוֹם מַעֲלָתוֹ הַיְדוּעָה.</p>\n<p>אָמַר רַבִּי, מִצְוָה לוֹ לָאָדָם לְהִתְפַּלֵּל עַל הָרְשָׁעִים כְּדֵי שֶׁיַּחְזְרוּ לְמוּטָב וְלֹא יִכָּנְסוּ לַגֵּיהִנֹּם, שֶׁכָּתוּב (תהלים לה) וַאֲנִי בַּחֲלוֹתָם לְבוּשִׁי שָׂק וְגוֹ'. וְאָמַר רַבִּי, אָסוּר לוֹ לָאָדָם לְהִתְפַּלֵּל עַל הָרְשָׁעִים שֶׁיִּסְתַּלְּקוּ מִן הָעוֹלָם, שֶׁאִלְמָלֵא סִלְּקוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְתֶרַח מִן הָעוֹלָם כְּשֶׁהָיָה עוֹבֵד עֲבוֹדָה זָרָה, לֹא בָא אַבְרָהָם אָבִינוּ לָעוֹלָם, וְשִׁבְטֵי יִשְׂרָאֵל לֹא הָיוּ, וְהַמֶּלֶךְ דָּוִד וּמֶלֶךְ הַמָּשִׁיחַ, וְהַתּוֹרָה לֹא נִתְּנָה, וְכָל אוֹתָם הַצַּדִּיקִים וְהַחֲסִידִים וְהַנְּבִיאִים לֹא הָיוּ בָּעוֹלָם. אָמַר רַבִּי יְהוּדָה, כֵּיוָן שֶׁרוֹאֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא נִמְצָא בָּרְשָׁעִים כְּלוּם מִכָּל אוֹתָם הָעִנְיָנִים, מַה כָּתוּב? וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדמָה וְגוֹ'. עַד כָּאן מִדְרָשׁ הַנֶּעְלָם</p>"],[9522011227,"<p>אֵרֲדָה נָּא וְאֶרְאֶה הַכְּצַעֲקָתָהּ הַבָּאָה אֵלַי עָשׂוּ כָּלָה. לְמִי אָמַר? אִם תֹּאמַר לְאוֹתָם הַמַּלְאָכִים - מִי רָאָה מְדַבֵּר עִם זֶה וּמְצַוֶּה אֶת זֶה? אֶלָּא לְאַבְרָהָם אָמַר, שֶׁבִּרְשׁוּתוֹ עוֹמְדִים הַמְּקוֹמוֹת הַלָּלוּ. דָּבָר אַחֵר - לְאוֹתָם מַלְאָכִים.</p>\n<p>מַה שֶּׁנֶּאֱמַר לְאַבְרָהָם, מָה הַטַּעַם עָשׂוּ? הָיָה צָרִיךְ לִכְתֹּב עָשָׂה. מַה זֶּה עָשׂוּ? (אלא) זֶה אַבְרָהָם וּשְׁכִינָה שֶׁלֹּא זָזָה מִמֶּנּוּ. (דבר אחר) עָשׂוּ - מַה שֶּׁנֶּאֱמַר לַמַּלְאָכִים, מִשּׁוּם שֶׁהָיוּ מְזֻמָּנִים לְשָׁם, וְהָיוּ נִמְצָאִים לַעֲשׂוֹת דִּין, וְעַל זֶה עָשׂוּ.</p>\n<p>דָּבָר אַחֵר עָשׂוּ - (לעשות) כְּתַרְגּוּמוֹ עֲבָדוּ. וְכִי לֹא הָיָה יוֹדֵעַ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא אָמַר אֵרֲדָה נָּא וְאֶרְאֶה, וַהֲרֵי הַכֹּל גָּלוּי לְפָנָיו? אֶלָּא אֵרֲדָה נָּא מִדַּרְגַּת הָרַחֲמִים לְדַרְגַּת הַדִּין, וְהַיְנוּ (זו) יְרִידָה. וְאֶרְאֶה - רְאִיָּה זוֹ לְהַשְׁגִּיחַ עֲלֵיהֶם בְּאֵיזֶה דִין יָדוּן אוֹתָם.</p>\n<p>מָצָאנוּ רְאִיָּה לְטוֹב וּמָצָאנוּ רְאִיָּה לְרַע. רְאִיָּה לְטוֹב - שֶׁכָּתוּב (שמות ב) וַיַּרְא אֱלֹהִים אֶת בְּנֵי יִשְׂרָאֵל וַיֵּדַע. רְאִיָּה לְרַע - שֶׁכָּתוּב אֵרֲדָה נָּא וְאֶרְאֶה (נ\"א: מצאנו ירידה לטוב ומצאנו ירידה לרע, לטוב שכתוב (שם יט) וירד ה' על הר סיני, (במדבר יא) וירדתי ודברתי עמך שם, ירידה לרע ארדה נא, בשביל) לְהַשְׁגִּיחַ עֲלֵיהֶם בַּדִּין, וְעַל זֶה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם.</p>"],[9522011228,"<p>וְאַבְרָהָם הָיוֹ יִהְיֶה לְגוֹי גָּדוֹל וְעָצוּם. מָה הַטַּעַם הַבְּרָכָה הַזּוֹ כָּאן? אֶלָּא כְּדֵי לְהוֹדִיעַ שֶׁאֲפִלּוּ בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב בְּדִין עַל הָעוֹלָם, לֹא מִשְׁתַּנֶּה. שֶׁהֲרֵי יוֹשֵׁב בְּדִין עַל זֶה (ד\"א ויושב) וּבְרַחֲמִים עַל זֶה, וְהַכֹּל בְּרֶגַע אֶחָד וּבְשָׁעָה אַחַת.</p>\n<p>אָמַר רַבִּי יְהוּדָה, וַהֲרֵי כָּתוּב (תהלים סט) וַאֲנִי תְפִלָּתִי לְךְ ה' עֵת רָצוֹן. לִפְעָמִים שֶׁהוּא עֵת רָצוֹן, וְלִפְעָמִים שֶׁאֵינוֹ עֵת רָצוֹן. לִפְעָמִים שֶׁשּׁוֹמֵעַ, וְלִפְעָמִים שֶׁלֹּא שׁוֹמֵעַ. לִפְעָמִים שֶׁנִּמְצָא, וְלִפְעָמִים שֶׁלֹּא נִמְצָא, שֶׁכָּתוּב (ישעיה נה) דִּרְשׁוּ ה' בְּהִמָּצְאוֹ קְרָאֻהוּ בִּהְיוֹתוֹ קָרוֹב.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, כָּאן לְיָחִיד, כָּאן לְצִבּוּר. כָּאן לְמָקוֹם אֶחָד, וְכָאן לְכָל הָעוֹלָם. מִשּׁוּם כָּךְ בֵּרַךְ אֶת אַבְרָהָם, שֶׁהוּא שָׁקוּל כְּכָל הָעוֹלָם, שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, (וכתוב) וְשָׁנִינוּ בְּאַבְרָהָם.</p>\n<p>יִהְיֶה בְּגִימַטְרִיָּא שְׁלֹשִׁים. כָּךְ שָׁנִינוּ, שְׁלֹשִׁים צַדִּיקִים מַזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל דּוֹר וָדוֹר לְעוֹלָם, כְּמוֹ שֶׁהִזְמִין אֶת אַבְרָהָם.</p>\n<p>פָּתַח וְאָמַר, (שמואל ב כג) מִן הַשְּׁלֹשִׁים (הכי) נִכְבָּד וְאֶל הַשְּׁלֹשָׁה לֹא בָא וְגוֹ'. מִן הַשְּׁלֹשִׁים (הכי) נִכְבָּד - אֵלּוּ הֵם שְׁלֹשִׁים צַדִּיקִים שֶׁמַּזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא לָעוֹלָם וְלֹא יְבַטֵּל אוֹתָם מִמֶּנּוּ. וּבְנָיָהוּ בֶּן יְהוֹיָדָע כָּתוּב בּוֹ מִן הַשְּׁלֹשִׁים (הכי) נִכְבָּד, הוּא אֶחָד מֵהֶם. וְאֶל הַשְּׁלֹשָׁה לֹא בָא - שֶׁלֹּא שָׁקוּל לִשְׁלֹשֶׁת הָאֲחֵרִים שֶׁהָעוֹלָם עוֹמֵד עֲלֵיהֶם.</p>\n<p>וְאֶל הַשְּׁלֹשָׁה לֹא בָא - לִהְיוֹת בְּמִנְיָן כְּאֶחָד מֵהֶם. עִם אוֹתָם שְׁלֹשִׁים צַדִּיקִים זָכָה לְהִכָּנֵס בְּחֶשְׁבּוֹן, אֲבָל וְאֶל הַשְּׁלֹשָׁה לֹא בָא, שֶׁלֹּא זָכָה לְהִתְחַבֵּר עִמָּם וְלִהְיוֹת עִמָּהֶם בְּחֵלֶק אֶחָד. יִהְיֶ\"ה, כְּמוֹ שֶׁשָּׁנִינוּ שְׁלֹשִׁים הוּא, וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַךְ אוֹתוֹ עִם אוֹתָם שְׁלֹשִׁים צַדִּיקִים.</p>"],[9522011229,"<p>בֹּא רְאֵה, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם, זַעֲקַת סְדם וַעֲמֹרָה כִּי רָבָּה, שֶׁהֲרֵי עָלְתָה לְפָנַי מַה שֶּׁהֵם עוֹשִׂים לְכָל הָעוֹלָם, שֶׁכָּל הָעוֹלָם מוֹנְעִים רַגְלֵיהֶם שֶׁלֹּא לְהִכָּנֵס לִסְדם וַעֲמֹרָה, שֶׁכָּתוּב (איוב כח) פָּרַץ נַחַל מֵעִם גָּר הַנִּשְׁכָּחִים מִנִּי רָגֶל דַּלּוּ מֵאֱנוֹשׁ נָעוּ. פָּרַץ נַחַל מֵעִם גָּר - פִּרְצָה הָיָה פּוֹרֵץ הַנַּחַל לְאוֹתָם בְּנֵי הָעוֹלָם שֶׁנִּכְנְסוּ לְשָׁם. שֶׁכָּל מִי שֶׁרָאָה אֶת מִי שֶׁהָיָה נוֹתֵן לֶאֱכֹל וְלִשְׁתּוֹת לְאָדָם אַחֵר, זוֹרְקִים אוֹתוֹ לְעֹמֶק הַנָּהָר (בנקבי הנקרות), וּמִי שֶׁלּוֹקֵחַ אוֹתוֹ גַּם כֵּן.</p>\n<p>וְעַל זֶה כָּל בְּנֵי הָעוֹלָם הָיוּ נִשְׁכָּחִים מִנִּי רָגֶל, שֶׁמּוֹנְעִים רַגְלֵיהֶם שֶׁלֹּא לְהִכָּנֵס לְשָׁם. וּמִי שֶׁנִּכְנַס - דַּלּוּ מֵאֱנוֹשׁ נָעוּ, שֶׁהָיוּ מְדַלְדְּלִים אֶת הַגּוּף בָּרָעָב וְלֹא הָיוּ נוֹתְנִים לוֹ לֶאֱכֹל וְלִשְׁתּוֹת, וּמִשְׁתַּנֶּה דְיוֹקְנוֹ מִשְּׁאָר בְּנֵי הָעוֹלָם, שֶׁכָּתוּב דַּלּוּ מֵאֱנוֹשׁ, נָעוּ. כָּתוּב כָּאן נָעוּ, וְכָתוּב שָׁם (משלי ה) נָעוּ מַעְגְּלֹתֶיהָ. כָּךְ גַּם הָיוּ סוֹטִים מַעְגָּלִים וּדְרָכִים כְּדֵי לֹא לְהִכָּנֵס לְשָׁם, וַאֲפִלּוּ עוֹפוֹת הַשָּׁמַיִם הָיוּ מְנוּעִים מִלְּהִכָּנֵס לְשָׁם, שֶׁכָּתוּב (איוב כח) נָתִיב לֹא יְדָעוֹ עַיִט וְגוֹ'. וְלָכֵן כָּל הָעוֹלָם הָיוּ צוֹוְחִים עַל סְדם וְעַל עֲמֹרָה וְעַל כָּל הַקְּרָיוֹת, שֶׁכֻּלָּם כְּמוֹ גָוֶן אֶחָד הָיוּ.</p>\n<p>זַעָקַת סְדם וַעֲמֹרָה כִּי רָבָּה. אָמַר לוֹ אַבְרָהָם, לָמָּה? אָמַר לוֹ, וְחַטָּאתָם כִּי כָבְדָה מְאֹד. מִשּׁוּם כָּךְ אֵרֲדָה נָּא וְאֶרְאֶה הַכְּצַעֲקָתָהּ. הָיָה צָרִיךְ לִכְתֹּב הַכְּצַעֲקָתָם, שֶׁהֲרֵי כָתוּב זַעֲקַת סְדם וַעֲמֹרָה, וּשְׁתֵּי עָרִים הָיוּ, אָז לָמָּה הַכְּצַעֲקָתָהּ? אֶלָּא הֲרֵי פֵּרְשׁוּהָ.</p>\n<p>בֹּא רְאֵה, בַּצַּד שֶׁמִּתַּחַת אֶבֶן הַבָּרָד עוֹלִים עֲשָׁנִים בְּכָתֵף, מִתְכַּנְּסִים בְּטִפָּה אַחַת וְנִכְנָסִים לְתוֹךְ נִקְבֵי תְהוֹם רַבָּה וְנַעֲשִׂים חֲמִשָּׁה בְּאֶחָד. אֶחָד הוּא כַּאֲשֶׁר (הקולות צלולים) יֵשׁ קוֹלוֹת צְלוּלִים שֶׁכֻּלָּם נַעֲשִׂים אֶחָד. הַקּוֹל שֶׁעוֹלֶה מִלְּמַטָּה נִכְנָס בֵּינֵיהֶם וְנִמְשָׁכִים כְּאֶחָד.</p>\n<p>וְאוֹתוֹ הַקּוֹל עוֹלֶה וְיוֹרֵד וְתוֹבֵעַ דִּין לְהִמָּשֵׁךְ לְמַטָּה. כְּשֶׁקּוֹל זֶה עוֹלֶה לִתְבֹּעַ דִּין, אָז מִתְגַּלֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁגִּיחַ בְּדִין.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הַכְּצַעֲקָתָהּ, מִי הַכְּצַעֲקָתָהּ? זוֹ גְזֵרַת הַדִּין שֶׁתּוֹבַעַת דִּין כָּל יוֹם. שֶׁכָּךְ שָׁנִינוּ, כַּמָּה שָׁנִים עוֹמֶדֶת גְּזֵרַת דִּין וְתוֹבַעַת מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל שֶׁאֲחֵי יוֹסֵף מָכְרוּ אֶת יוֹסֵף, מִשּׁוּם שֶׁגְּזֵרַת הַדִּין צוֹוַחַת עַל הַדִּין, וְעַל זֶה הַכְּצַעֲקָתָהּ הַבָּאָה אֵלַי.</p>\n<p>מַה זֶּה הַבָּאָה אֵלַי? זֶהוּ סוֹד כְּמוֹ שֶׁנֶּאֱמַר (אסתר ב) בָּעֶרֶב הִיא בָאָה וּבַבֹּקֶר הִיא שָׁבָה. וְזֶהוּ הַבָּאָה אֵלַי, תָּמִיד. כְּמוֹ זֶה קֵץ כָּל בָּשָׂר בָּא לְפָנַי, וַהֲרֵי נִתְבָּאֵר. עָשׂוּ כָּלָה, הֲרֵי נִתְבָּאֵר.</p>"],[9522011230,"<p>וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר הַאַף תִּסְפֶּה צַדִּיק עִם רָשָׁע. אָמַר רַבִּי יְהוּדָה, מִי רָאָה אַב הָרַחֲמִים כְּמוֹ אַבְרָהָם. בּא רְאֵה, בְּנֹחַ כָּתוּב וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי וְגוֹ', עֲשֵׂה לְךְ תֵּבַת עֲצֵי גֹפֶר. וְשָׁתַק וְלֹא אָמַר לוֹ דָּבָר וְלֹא בִקֵּשׁ רַחֲמִים. אֲבָל אַבְרָהָם, בְּשָׁעָה שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא זַעֲקַת סְדם וַעֲמֹרָה כִּי רָבָּה, אֵרֲדָה נָּא וְאֶרְאֶה - מִיָּד כָּתוּב וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר הַאַף תִּסְפֶּה צַדִּיק עִם רָשָׁע.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אַף אַבְרָהָם לֹא עָשָׂה בִּשְׁלֵמוּת כָּרָאוּי. נֹחַ לֹא עָשָׂה דָבָר, לֹא זֶה וְלֹא זֶה. אַבְרָהָם בִּקֵּשׁ דִּין כָּרָאוּי שֶׁלֹּא יָמוּת צַדִּיק עִם רָשָׁע, וְהִתְחִיל מֵחֲמִשִּׁים עַד עֲשָׂרָה. עָשָׂה וְלֹא הִשְׁלִים, שֶׁלֹּא בִקֵּשׁ רַחֲמִים בֵּין כָּךְ וּבֵין כָּךְ, שֶׁאָמַר אַבְרָהָם שֶׁלֹּא רוֹצֶה לִתְבֹּעַ שְׂכַר מַעֲשָׂיו.</p>\n<p>אֲבָל מִי עָשָׂה בִּשְׁלֵמוּת כָּרָאוּי? זֶה מֹשֶׁה. שֶׁכֵּיוָן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא (שמות לב) סָרוּ מַהֵר מִן הַדֶּרֶךְ וְגוֹ', עָשׂוּ לָהֶם עֵגֶל מַסֵּכָה וַיִּשְׁתַּחֲווּ לוֹ - מִיָּד כָּתוּב וַיְחַל מֹשֶׁה אֶת פְּנֵי ה' אֱלֹהָיו וְגוֹ', עַד שֶׁאָמַר וְעַתָּה אִם תִּשָּׂא חַטָּאתָם וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךְ אֲשֶׁר כָּתָבְתָּ. וְאַף עַל גַּב שֶׁכֻּלָּם חָטְאוּ, לֹא זָז מִשָּׁם עַד שֶׁאָמַר לוֹ סָלַחְתִּי כִּדְבָרֶךְ.</p>\n<p>אֲבָל אַבְרָהָם לֹא הִשְׁגִּיחַ אֶלָּא אִם נִמְצָא בָהֶם צַדִּיק, וְאִם לֹא - לֹא. עַל זֶה לֹא הָיָה בָּעוֹלָם בֶּן אָדָם שֶׁיָּגֵן עַל דּוֹרוֹ כְּמוֹ מֹשֶׁה שֶׁהוּא רוֹעֶה נֶאֱמָן.</p>\n<p>וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר, הִתְקִין עַצְמוֹ לְבַקֵּשׁ אֶת זֶה. אוּלַי יִמָּצְאוּ שָׁם חֲמִשִּׁים. הִתְחִיל מֵחֲמִשִּׁים שֶׁהוּא רֵאשִׁית לְדַעַת, עַד עֲשָׂרָה, שֶׁהוּא עֲשִׂירִי, סוֹף כָּל הַדְּרָגוֹת.</p>\n<p>אָמַר רַבִּי יִצְחָק, עַד עֲשָׂרָה, אֵלּוּ עֲשָׂרָה יָמִים שֶׁבֵּין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים, מִשּׁוּם כָּךְ הִתְחִיל מֵחֲמִשִּׁים עַד עֲשָׂרָה. וְכֵיוָן שֶׁהִגִּיעַ לַעֲשָׂרָה, אָמַר, מִכָּאן וּלְמַטָּה אֵינוֹ מָקוֹם שֶׁעוֹמֵד בִּתְשׁוּבָה. מִשּׁוּם כָּךְ לֹא יָרַד מִתַּחַת לַעֲשָׂרָה.</p>"],[9522011231,"<p>וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדמָה בָּעֶרֶב וְגוֹ'. אָמַר רַבִּי יוֹסֵי, בֹּא רְאֵה מַה כָּתוּב לְמַעְלָה, וַיֵּלֶךְ ה' כַּאֲשֶׁר כִּלָּה לְדַבֵּר אֶל אַבְרָהָם. שֶׁהֲרֵי כֵּיוָן שֶׁנִּפְרְדָה שְׁכִינָה מֵאַבְרָהָם וְאַבְרָהָם שָׁב לִמְקוֹמוֹ, אָז וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדמָה בָּעֶרֶב, שֶׁהֲרֵי אֶחָד הִסְתַּלֵּק עִם הַשְּׁכִינָה, וְנִשְׁאֲרוּ אוֹתָם שְׁנַיִם.</p>\n<p>כֵּיוָן שֶׁרָאָה אוֹתָם לוֹט, רָץ אַחֲרֵיהֶם. מָה הַטַּעַם? וְכִי כָּל אוֹתָם שֶׁהָיוּ בָּאִים הוּא הִכְנִיס לְבֵיתוֹ וְנָתַן לָהֶם לֶאֱכֹל וְלִשְׁתּוֹת? וּבְנֵי הָעִיר אֵיךְ לֹא הָרְגוּ אוֹתוֹ, שֶׁהֲרֵי לְבִתּוֹ עָשׂוּ דִין,</p>\n<p>וּמַה הוּא? שֶׁבַּת לוֹט נָתְנָה פַּת לֶחֶם לְעָנִי אֶחָד, יָדְעוּ בָזֶה, וּמָרְחוּ אוֹתָהּ בִּדְבַשׁ וְהוֹשִׁיבוּהָ בְּרֹאשׁ הַגַּג עַד שֶׁהַצְּרָעוֹת אָכְלוּ אוֹתָהּ.</p>\n<p>אֶלָּא מִשּׁוּם שֶׁזֶּה הָיָה בַּלַּיְלָה, חָשַׁב שֶׁלֹּא יִסְתַּכְּלוּ בְּנֵי הָעִיר עָלָיו. וְעִם כָּל זֶה, כֵּיוָן שֶׁנִּכְנְסוּ לַבַּיִת, הִתְכַּנְּסוּ כֻלָּם וְהִקִּיפוּ אֶת הַבַּיִת.</p>\n<p>אָמַר רַבִּי יִצְחָק, לָמָּה רָץ לוֹט אַחֲרֵיהֶם, (אלא משום) שֶׁכָּתוּב וַיַּרְא לוֹט וַיָּרָץ לִקְרָאתָם? רַבִּי חִזְקִיָּה וְרַבֵּי יֵיסָא. אֶחָד אָמַר, דְּמוּת אַבְרָהָם רָאָה עִמָּם. וְאֶחָד אָמַר, שְׁכִינָה בָּאָה עִמָּהֶם. כָּתוּב כָּאן וַיַּרְא לוֹט וַיָּרָץ לִקְרָאתָם, וְכָתוּב שָׁם וַיָּרָץ לִקְרָאתָם מִפֶּתַח הָאֹהֶל. מַה לְּהַלָּן רָאָה שְׁכִינָה, אַף כָּאן רָאָה שְׁכִינָה.</p>\n<p>וַיַּרְא לוֹט וַיָּרָץ לִקְרָאתָם, וַיֹּאמֶר הִנֶּה נָּא אֲדֹנַ\"י, בְּאָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד. סוּרוּ נָא, הָיָה צָרִיךְ לִכְתֹּב גְּשׁוּ נָא, מַה זֶּה סוּרוּ נָא? אֶלָּא לְהַחֲזִירָם סְבִיב הַבַּיִת כְּדֵי שֶׁלֹּא יִרְאוּ אוֹתָם בְּנֵי הָעִיר וְלֹא יִכָּנְסוּ בְּדֶרֶךְ יָשָׁר הַבַּיְתָה, וּמִשּׁוּם כָּךְ סוּרוּ נָא.</p>\n<p>רַבִּי חִזְקִיָּה פָּתַח, (איוב כח) כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט תַּחַת כָּל הַשָּׁמַיִם יִרְאֶה. כַּמָּה יֵשׁ לָהֶם לִבְנֵי אָדָם לְהִסְתַּכֵּל בְּמַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִשְׁתַּדֵּל בַּתּוֹרָה יָמִים וְלֵילוֹת, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ לְמַעְלָה וּמִשְׁתַּבֵּחַ בּוֹ לְמַטָּה, מִשּׁוּם שֶׁהַתּוֹרָה הִיא עֵץ חַיִּים לְכָל אוֹתָם הָעוֹסְקִים בָּהּ לָתֵת לָהֶם חַיִּים בָּעוֹלָם הַזֶּה וְלָתֵת לָהֶם חַיִּים בָּעוֹלָם הַבָּא.</p>\n<p>בֹּא רְאֵה, כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט, לָתֵת לָהֶם מָזוֹן וּלְסַפֵּק אוֹתָם מִכָּל מַה שֶּׁהִצְטָרְכוּ, מִשּׁוּם שֶׁהוּא מַשְׁגִּיחַ בָּהּ תָּמִיד, שֶׁכָּתוּב (דברים יא) תָּמִיד עֵינֵי ה' אֱלֹהֶיךְ בָּהּ מֵרֵשִׁית הַשָּׁנָה וְעַד אַחֲרִית שָׁנָה.</p>\n<p>מִשּׁוּם שֶׁאֶרֶץ זוֹ מַה כָּתוּב בָּהּ? (משלי לא) מִמֶּרְחָק תָּבִיא לַחְמָהּ. אַחַר כָּךְ הִיא נוֹתֶנֶת מָזוֹן וְטֶרֶף לְכָל חַיּוֹת הַשָּׂדֶה, שֶׁכָּתוּב (שם) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ.</p>\n<p>וְעַל זֶה כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט תַּחַת כָּל הַשָּׁמַיִם יִרְאֶה, אֶת כָּל בְּנֵי הָעוֹלָם לָתֵת לָהֶם מָזוֹן וְסִפּוּק לְכָל מַה שֶּׁצָּרִיךְ כָּל אֶחָד וְאֶחָד, שֶׁכָּתוּב (תהלים קמה) פּוֹתֵחַ אֶת יָדֶךְ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן.</p>\n<p>דָּבָר אַחֵר כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט, לְהִסְתַּכֵּל בְּמַעֲשֵׂי בֶּן הָאָדָם וּלְהַשְׁגִּיחַ בְּכָל מַה שֶּׁעוֹשִׂים בּוֹ בְּנֵי אָדָם בָּעוֹלָם. תַּחַת כָּל הַשָּׁמַיִם יִרְאֶה, מִסְתַּכֵּל וְרוֹאֶה כָּל אֶחָד וְאֶחָד.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא מַעֲשֵׂי סְדם וַעֲמֹרָה, שָׁלַח לָהֶם אוֹתָם הַמַּלְאָכִים לְהַשְׁחִית אֶת סְדם. מַה כָּתוּב? וַיַּרְא לוֹט. רָאָה אֶת הַשְּׁכִינָה. וְכִי מִי יָכוֹל לִרְאוֹת שְׁכִינָה? אֶלָּא רָאָה זהַר אֶחָד שֶׁמֵּאִיר וְעוֹלֶה עַל רָאשֵׁיהֶם. וְאָז, וַיֹּאמֶר הִנֶּה נָּא אֲדנַי, בְּאָלֶ\"ף דָּלֶ\"ת כְּמוֹ שֶׁנִּתְבָּאֵר. וּבִגְלַל הַשְּׁכִינָה אוֹתוֹ הָאוֹר שֶׁהֵאִיר הוּא אָמַר סוּרוּ נָא אֶת בֵּית עַבְדְּכֶם וְלִינוּ וְרַחֲצוּ רַגְלֵיכֶם.</p>\n<p>לֹא עָשָׂה כָּךְ אַבְרָהָם, אֶלָּא בַּתְּחִלָּה אָמַר וְרַחֲצוּ רַגְלֵיכֶם, וְאַחַר כָּךְ וְאֶקְחָה פַּת לֶחֶם וְגוֹ'. אֲבָל לוֹט אָמַר סוּרוּ נָא אֶל בֵּית עַבְדְּכֶם וְלִינוּ, וְאַחַר כָּךְ וְרַחֲצוּ רַגְלֵיכֶם וְהִשְׁכַּמְתֶּם וַהֲלַכְתֶּם לְדַרְכְּכֶם, כְּדֵי שֶׁלֹּא יֵדְעוּ בָהֶם בְּנֵי הָאָדָם.</p>\n<p>וַיֹּאמְרוּ לֹא כִּי בָרְחוֹב נָלִין. מִשּׁוּם שֶׁכָּךְ הָיוּ עוֹשִׂים: אוֹרְחִים שֶׁנִּכְנָסִים לְשָׁם, לֹא הָיָה בֶּן אָדָם שֶׁיַּכְנִיסֵם לַבַּיִת. וְעַל זֶה אָמְרוּ, לֹא כִּי בָרְחוֹב נָלִין. מַה כָּתוּב וַיִּפְצַר? בָּם מְאֹד וְגוֹ'.</p>\n<p>בּא רְאֵה, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִין בָּעוֹלָם, שָׁלִיחַ אֶחָד עוֹשֶׂה אוֹתוֹ, וְכָעֵת רָאִינוּ שְׁנֵי שְׁלִיחִים, לָמָּה? וְכִי לֹא מַסְפִּיק בְּאֶחָד? אֶלָּא אֶחָד הָיָה, וּמַה שֶּׁאָמַר שְׁנַיִם (כך זה ודאי, משום שאחד) - אֶחָד הָיָה לְהוֹצִיא אֶת לוֹט וּלְהַצִּילוֹ, וְאֶחָד לַהֲפֹךְ אֶת הָעִיר וּלְהַשְׁחִית אֶת הָאָרֶץ, וּלְכָךְ נִשְׁאַר אֶחָד.</p>"],[9522011232,"<p>רַבִּי פָּתַח בְּפָסוּק זֶה, (שופטים ג) וְאֵלֶּה הַגּוֹיִם אֲשֶׁר הִנִּיחַ ה' לְנַסּוֹת בָּם אֶת יִשְׂרָאֵל. אָמַר רַבִּי, רָאִיתִי בְּאוֹתוֹ עוֹלָם, (ואין העולם) עוֹמֵד (ואין מעלה) אֶלָּא בְּאוֹתָם שֶׁשּׁוֹלְטִים עַל רְצוֹן לִבָּם, שֶׁנֶּאֱמַר (תהלים פא) עֵדוּת בִּיהוֹסֵף שָׂמוֹ וְגוֹ'. אָמַר רַב יְהוּדָה, לָמָּה זָכָה יוֹסֵף לְאוֹתָהּ הַמַּעֲלָה וְהַמַּלְכוּת? בִּשְׁבִיל שֶׁכָּבַשׁ יִצְרוֹ. שֶׁשָּׁנִינוּ, כָּל הַכּוֹבֵשׁ אֶת יִצְרוֹ, מֵחִיל עָלָיו אֶת מַלְכוּת הַשָּׁמַיִם.</p>\n<p>שֶׁאָמַר רַב אָחָא, לֹא בָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַיֵּצֶר הָרָע אֶלָּא לְנַסּוֹת בּוֹ בְּנֵי אָדָם. וְהַאִם רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְנַסּוֹת בְּנֵי אָדָם? כֵּן. שֶׁאָמַר רַב אָחָא, מִנַּיִן לָנוּ? מִשֶּׁכָּתוּב (דברים יג) כִּי יָקוּם בְּקִרְבְּךְ נָבִיא וְגוֹ' וּבָא הָאוֹת וְהַמּוֹפֵת וְגוֹ', כִּי מְנַסֶּה ה' אֱלֹהֵיכֶם וְגוֹ'. וְלָמָּה צָרִיךְ נִסָּיוֹן, שֶׁהֲרֵי כָּל מַעֲשֵׂי בְּנֵי אָדָם גְּלוּיִים לְפָנָיו? אֶלָּא שֶׁלֹּא לִתֵּן פִּתְחוֹן פֶּה לִבְנֵי אָדָם. רְאֵה מַה כָּתוּב וְלוֹט? יֹשֵׁב בְּשַׁעַר סְדם, שֶׁהָיָה יוֹשֵׁב לְנַסּוֹת אֶת הַבְּרִיּוֹת.</p>\n<p>אָמַר רַבִּי יִצְחָק, מַהוּ שֶׁכָּתוּב (ישעיה נז) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ וְגוֹ'? אֲפִלּוּ בִּשְׁעַת דִּינוֹ שֶׁל רָשָׁע הוּא מֵעֵז פָּנָיו, וַאֲזַי הוּא בְּרִשְׁעָתוֹ קַיָּם. רְאֵה מַה כָּתוּב, טֶרֶם יִשְׁכָּבוּ וְגוֹ'. אָמַר רַבִּי יִצְחָק, כְּשֵׁם שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא גַּן עֵדֶן בָּאָרֶץ - כָּךְ בָּרָא גֵיהִנֹּם בָּאָרֶץ. וּכְשֵׁם שֶׁבָּרָא גַּן עֵדֶן לְמַעְלָה - כָּךְ בָּרָא גֵיהִנֹּם לְמַעְלָה.</p>\n<p>גַּן עֵדֶן בָּאָרֶץ, שֶׁכָּתוּב (בראשית ב) וַיִּטַּע ה' אֱלֹהִים גַּן בְּעֵדֶן וְגוֹ'. גֵּיהִנֹּם בָּאָרֶץ, שֶׁכָּתוּב (איוב י) אֶרֶץ עֵיפָתָה כְּמוֹ אֹפֶל וְגוֹ'. גַּן עֵדֶן לְמַעְלָה, שֶׁכָּתוּב (שמואל א כה) וְהָיְתָה נֶפֶשׁ אֲדנִי צְרוּרָה בִּצְרוֹר הַחַיִּים אֵת ה' אֱלֹהֶיךְ, וְכָתוּב (קהלת יב) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ.</p>\n<p>גֵּיהִנֹּם לְמַעְלָה, שֶׁכָּתוּב וְאֵת נֶפֶשׁ אֹיְבֶיךְ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע. גַּן עֵדֶן לְמַטָּה, כְּמוֹ שֶׁאָמַרְנוּ. גַּן עֵדֶן לְמַעְלָה לְנִשְׁמָתָן שֶׁל צַדִּיקִים גְּמוּרִים לִהְיוֹת נִזּוֹנִים מֵאוֹר הַגָּדוֹל שֶׁל מַעְלָה.</p>\n<p>גֵּיהִנֹּם לְמַטָּה לְאוֹתָם הָרְשָׁעִים (של ישראל) שֶׁלֹּא קִבְּלוּ בְּרִית מִילָה וְלֹא הֶאֱמִינוּ בַּקָּבָּ\"ה וְדָתוֹ וְלֹא שָׁמְרוּ שַׁבָּת, וְאֵלּוּ הֵם עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁנִּדּוֹנִים בָּאֵשׁ, שֶׁנֶּאֱמַר (יחזקאל טו) מֵהָאֵשׁ יָצָאוּ וְהָאֵשׁ תֹּאכְלֵם וְגוֹ', וְכָתוּב (ישעיה סו) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים וְגוֹ'.</p>\n<p>גֵּיהִנֹּם לְמַעְלָה לְאוֹתָם פּוֹשְׁעֵי יִשְׂרָאֵל שֶׁעָבְרוּ עַל מִצְווֹת הַתּוֹרָה וְלֹא חָזְרוּ בִּתְשׁוּבָה, שֶׁדּוֹחִים אוֹתָם לַחוּץ עַד שֶׁיְּקַבְּלוּ עָנְשָׁם, וְהוֹלְכִים וְסוֹבְבִים כָּל הָעוֹלָם, שֶׁנֶּאֱמַר (תהלים יב) סָבִיב רְשָׁעִים יִתְהַלָּכוּן.</p>\n<p>וְשָׁם נִדּוֹנִים שְׁנֵים עָשָׂר חֹדֶשׁ. לְאַחַר כֵּן מָדוֹרָם עִם אוֹתָם שֶׁקִּבְּלוּ עָנְשָׁם בְּמוֹתָם, כָּל אֶחָד וְאֶחָד כְּפִי הַמָּקוֹם הָרָאוּי לוֹ. וְהָרְשָׁעִים שֶׁל הָעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת נִדּוֹנִים תָּמִיד בָּאֵשׁ וּבַמַּיִם וְשׁוּב אֵינָם עוֹלִים, שֶׁנֶּאֱמַר וְאִשָּׁם לֹא תִכְבֶּה.</p>\n<p>מִשְׁפַּט הָרְשָׁעִים בַּגֵּיהִנֹּם כְּמוֹ שֶׁכָּתוּב וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה גָּפְרִית וָאֵשׁ וְגוֹ', וְשׁוּב אֵינָם עוֹלִים, וְלֹא יָקוּמוּ לְיוֹם הַדִּין, שֶׁנֶּאֱמַר (דברים כט) אֲשֶׁר הָפַךְ ה' בְּאַפּוֹ וּבַחֲמָתוֹ. בְּאַפּוֹ - בָּעוֹלָם הַזֶּה. וּבַחֲמָתוֹ - בָּעוֹלָם הַבָּא.</p>\n<p>אָמַר רַבִּי יִצְחָק, כְּמוֹ זֶה יֵשׁ גַּן עֵדֶן לְמַעְלָה וְיֵשׁ גַּן עֵדֶן לְמַטָּה. יֵשׁ גֵּיהִנֹּם לְמַטָּה וְיֵשׁ גֵּיהִנֹּם לְמַעְלָה. אָמַר רַבִּי יַעֲקֹב, הָרְשָׁעִים שֶׁקִּלְקְלוּ בְּרִית מִילָה שֶׁבָּהֶם וְחִלְלוּ שַׁבָּת בְּפַרְהֶסְיָה וְחִלְלוּ אֶת הַמּוֹעֲדוֹת וְשֶׁכָּפְרוּ בַּתּוֹרָה וְשֶׁכָּפְרוּ בִּתְחִיַּת הַמֵּתִים וְכַדּוֹמֶה לָהֶם, יוֹרְדִים לַגֵּיהִנֹּם שֶׁלְּמַטָּה וְנִדּוֹנִים שָׁם, וְשׁוּב אֵינָם עוֹלִים.</p>\n<p>אֲבָל יָקוּמוּ לְיוֹם הַדִּין וְיָקוּמוּ לִתְחִיַּת הַמֵּתִים, וַעֲלֵיהֶם נֶאֱמַר (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְגוֹ', וַעֲלֵיהֶם נֶאֱמַר (ישעיה סו) וְהָיוּ דֵרָאוֹן לְכָל בָּשָׂר. מַהוּ דֵרָאוֹן? דַּי רָאוֹן, שֶׁהַכֹּל יֹאמְרוּ דַּי בִּרְאִיָּתָם. וְעַל הַצַּדִּיקִים שֶׁבְּיִשְׂרָאֵל נֶאֱמַר (שם ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'. (ע\"כ מדרש הנעלם).</p>"]]});
